def held_label(ctx):
    """the first edition's label T-LAYER holds below the one line over its mounted article (issue #169) as the page shows it — its
    words, its rect, whether a press at its start meets it, what assistive technology is told of it, whether it reads as a corner —
    beside the lead the page's first-line rule gives it (issue #23), its corner, its outline's rects, its first column's text left,
    its outline's bottom and the half gutter on screen, the one line's bottom and the places the line names"""
    return ctx.js('''(() => { const S = window.__skep, h = S.heldLabel(%s), f = S.fold(%s), c = S.view.camera(), p = S.view.viewport();
      const scr = (b) => ({x: (b.x - c.x) * c.scale + p.VW / 2, y: (b.y - c.y) * c.scale + p.VH / 2, w: b.w * c.scale, h: b.h * c.scale});
      const el = document.querySelector(%s), v = S.visible(%s), o = scr(f.outline);
      const hit = h ? document.elementFromPoint(h.rect.x + Math.min(4, h.rect.w / 2), h.rect.y + h.rect.h / 2) : null;
      return {label: h, lead: S.firstLine(%s).lead, hidden: el ? el.getAttribute('aria-hidden') : null, cornerLike: el ? el.matches('.corner, [data-corner]') : null, takes: !!hit && !!el && el.contains(hit),
              corner: v.length === 1 ? v[0].rect : null, rects: f.rects.map(scr), left: scr(f.columns[0]).x, bottom: o.y + o.h, gutter: %s / 2 * f.fs * c.scale,
              line: document.getElementById('line').getBoundingClientRect().bottom, named: S.named()}; })()''' % (json.dumps(DOC), json.dumps(DOC), json.dumps('#corners [data-held="%s"]' % DOC), json.dumps(CORNER), json.dumps(DOC), GUTTER_EM))


def corner_of(ctx):
    """the first edition's corner as the page shows it (the `visible` oracle), the one line's bottom, and the document's top
    and bottom on screen as its fold sets them (issue #15): its first column's top, its outline's bottom"""
    return ctx.js('''(() => { const S = window.__skep, v = S.visible(%s), f = S.fold(%s), c = S.view.camera(), p = S.view.viewport();
      return {corner: v.length === 1 ? v[0] : null, n: v.length, line: document.getElementById('line').getBoundingClientRect().bottom,
              top: (f.columns[0].y - c.y) * c.scale + p.VH / 2, bottom: (f.outline.y + f.outline.h - c.y) * c.scale + p.VH / 2}; })()''' % (json.dumps(CORNER), json.dumps(DOC)))


def on_own_line(a):
    """does the beam's endpoint lie level with one of its words' line rects, at the edge of the part of its block that holds
    the line (its column's, where the block is split across columns)?"""
    at_edge = a['edge'] is not None and abs(a['x'] - a['edge']) <= ANCHOR_TOL_PX
    return at_edge and any(w['y'] - ANCHOR_TOL_PX <= a['y'] <= w['y'] + w['h'] + ANCHOR_TOL_PX for w in a['words'])


def symbols_view(ctx):
    """each link of the first edition drawn at one span, as the mounted article sets it: its marked words and its
    symbols counted; where it has both, whether the symbol stands in the paragraph holding the end of its words and
    after them, and the article's own text between the words' end and the symbol and after the symbol to the
    paragraph's end, the chrome inside a paragraph (a symbol, the count) set aside"""
    return ctx.js('''(() => {
      const S = window.__skep, art = document.querySelector(%s);
      if (!art) return null;
      const shown = S.links.shown(%s), once = shown.filter((s) => shown.filter((x) => x.link === s.link).length === 1);
      const text = (r) => { const f = r.cloneContents(); f.querySelectorAll('.sym, .others').forEach((x) => x.remove()); return f.textContent; };
      return once.map((s) => {
        const words = [...art.querySelectorAll(`.lip[data-links~="${s.link}"]`)], syms = [...art.querySelectorAll(`.sym[data-link="${s.link}"]`)];
        const out = {link: s.link, pos: s.pos, width: s.width, words: words.length, syms: syms.length};
        if (!words.length || syms.length !== 1) return out;
        const last = words[words.length - 1], sym = syms[0], block = last.closest('.sp');
        const after_words = !!(last.compareDocumentPosition(sym) & Node.DOCUMENT_POSITION_FOLLOWING) && !last.contains(sym);
        const between = document.createRange(), rest = document.createRange();
        if (after_words) { between.setStartAfter(last); between.setEndBefore(sym); }
        rest.setStartAfter(sym); rest.setEnd(block, block.childNodes.length);
        return Object.assign(out, {same_block: block === sym.closest('.sp'), after_words, between: after_words ? text(between) : null, after: text(rest)});
      });
    })()''' % (json.dumps('#domlayer article.dtext[data-addr="%s"]' % DOC), json.dumps(DOC)))


def rect_like(a, b):
    """do two rects stand at one place and size, ANCHOR_TOL_PX either way?"""
    return all(abs(a[k] - b[k]) <= ANCHOR_TOL_PX for k in ('x', 'y', 'w', 'h'))


def beam_ink(ctx, doc, link, pos):
    """the ink the beams' canvas holds about the start of the beam that leaves `doc` at `pos` for `link`: the alpha of every
    pixel in the square BEAM_WINDOW_PX either way of the point it leaves the text at, summed, in px² — read from the canvas's
    pixels, apart from the beams' own set; None where no such beam is built"""
    return ctx.js('''((doc, link, pos, half) => {
      const S = window.__skep, a = S.beamAnchors().find((b) => b.link === link && b.near === doc && b.pos === pos);
      if (!a) return null;
      const cv = document.getElementById('beams'), k = cv.width / S.view.viewport().VW;
      const x0 = Math.max(0, Math.floor((a.x - half) * k)), y0 = Math.max(0, Math.floor((a.y - half) * k));
      const x1 = Math.min(cv.width, Math.ceil((a.x + half) * k)), y1 = Math.min(cv.height, Math.ceil((a.y + half) * k));
      if (x1 <= x0 || y1 <= y0) return {at: {x: a.x, y: a.y}, ink: 0};
      const img = cv.getContext('2d').getImageData(x0, y0, x1 - x0, y1 - y0).data;
      let ink = 0;
      for (let i = 3; i < img.length; i += 4) ink += img[i] / 255;
      return {at: {x: a.x, y: a.y}, ink: ink / (k * k)};
    })(%s, %s, %d, %s)''' % (json.dumps(doc), json.dumps(link), pos, BEAM_WINDOW_PX))


def handoff(ctx):
    """every mounted article's block parts against the canvas's own bars for them (`barsOf`), part by part (issue #15:
    mid scale greeks the columns the mount sets; issue #122: a document stands by line, each part a run of a column's
    lines) — a withheld run's gap among them, as tall as its bars whatever it holds (F2.1-i: its bars take its true
    width; issue #151: no face reflows the text); the ones off their bars — in another column or part, at another top,
    of another height, or of another count of lines — named, and the withheld gaps compared counted"""
    compared, off, gaps = 0, [], 0
    for addr in ctx.js('window.__skep.mountedAddrs()'):
        h = ctx.js('window.__skep.barsOf(%s)' % json.dumps(addr))
        if not h or h['text'] is None:
            continue
        bars = {(b['pos'], b['column'], b['part']): b for b in h['bars']}
        for t in h['text']:
            if t['lines'] == 0:
                continue
            gaps += 1 if t['withheld'] else 0
            compared += 1
            b = bars.get((t['pos'], t['column'], t['part']))
            if b is None or b['top'] is None or abs(b['top'] - t['top']) > HANDOFF_TOL_PX or abs(b['height'] - t['height']) > HANDOFF_TOL_PX or b['lines'] != t['lines']:
                off.append({'addr': addr, 'pos': t['pos'], 'column': t['column'], 'part': t['part'], 'char': t['char'], 'text_top': t['top'], 'bars_top': b and b['top'], 'text_height': t['height'],
                            'bars_height': b and b['height'], 'text_lines': t['lines'], 'bars_lines': b and b['lines'], 'line_px': h['line_px']})
    return {'compared': compared, 'off': off, 'gaps': gaps}


def stand_in_view(ctx):
    """THE HANDOFF over a stand-in article, what no document on the board shows the gate — no other party's link touches
    a document the gate mounts, so no count stands in one: T-ARTICLE's article of three paragraphs, the first two full
    lines of its column with its others' count, the second a separator alone, the third three lines, set on the text
    layer as T-LAYER sets an article's column — at LAY_FS, the measure STAND_IN_CPL of its face's average advance wide, its
    fits measured by T-LAYER's measure — once with its count and once with none, both measured and taken down in the one
    evaluation, so no frame draws them; beside P-LAY's layout of the same article's plan and of the plan with no count.
    Each block's top below the article's first line, its height and its count of lines, in px at the layout size, on
    either side; the count's rect beside its block's and its block's first line's box"""
    return ctx.js('''(async () => {
      const A = await import('./text/article.js'), L = await import('./plane/layout.js'), T = await import('./text/layer.js');
      const cpl = %d, account = '1.0.1', addr = '1.0.1.0.999999', word = 'aaaaaaaaa', enc = new TextEncoder();
      let pos = 1;
      const blocks = [12, 0, 15].map((n) => { const text = Array(n).fill(word).join(' '), b = {pos, width: enc.encode(text).length + 2, kind: 'para', text, origin: null}; pos += b.width; return b; });
      const d = {addr, account, kind: 'edition', label: '', standing: 'public', system: false, extent: pos - 1, linkPositions: 0, meta: null, runs: [], from: 1, to: pos,
                 blocks, image: [], origins: [], imageFor: null, links: new Set(), linksRead: true, members: 1, whole: pos - 1, rev: 0, refused: null};
      const v = {selected: null, focus: null, marks: [], symbols: [], countAt: (b) => ({n: b.pos === blocks[0].pos ? 3 : 0, social: false}), wholeLinks: 0,
                 reader: {account, keyPresent: true}, localTrust: true, notebook: true, scene: false, originKinds: new Map(),
                 keyOf: () => ({label: 'dev-notebook', fingerprint: 'e4272902a11439e5' + '0'.repeat(48)}), measure: T.widthOf};
      const bare = {...v, countAt: () => ({n: 0, social: false})};
      const lay = L.layoutOf(A.articlePlan(d, v, account), cpl), plain = L.layoutOf(A.articlePlan(d, bare, account), cpl);
      const plan = blocks.map((b) => { const x = lay.blocks.get(b.pos), first = lay.lines[x.first], last = lay.lines[x.first + x.n - 1];
        return {pos: b.pos, lines: x.n, top: x.n ? first.top * L.LAY_FS : null, height: x.n ? (last.top + last.h - first.top) * L.LAY_FS : 0}; });
      const same = JSON.stringify(lay.lines) === JSON.stringify(plain.lines);
      const set = (view) => {
        const art = document.createElement('article');
        art.className = 'dtext';
        Object.assign(art.style, {width: cpl * L.CHAR_W + 'em', fontSize: L.LAY_FS + 'px', lineHeight: String(L.LINE_H)});
        art.innerHTML = A.articleHTML(d, view, account);
        document.getElementById('domlayer').appendChild(art);
        return art;
      };
      const counted = set(v), uncounted = set(bare);
      try {
        const rects = (art) => { const top = art.getBoundingClientRect().top; return (e) => { const r = e.getBoundingClientRect(); return {x: r.left, y: r.top - top, w: r.width, h: r.height}; }; };
        const read = (art) => { const q = rects(art); return blocks.map((b) => { const e = art.querySelector(`.run > .sp[data-pos="${b.pos}"]`); if (!e) return {pos: b.pos, top: null, height: null, lines: null};
          const r = q(e); return {pos: b.pos, top: r.y, height: r.h, lines: Math.round(r.h / parseFloat(getComputedStyle(e).lineHeight))}; }); };
        const q = rects(counted), top = counted.getBoundingClientRect().top;
        const c = counted.querySelector('.others'), host = c && c.closest('.sp');
        // the block's first line: the client rect of its first text's first character
        const firstLine = (e) => { const w = document.createTreeWalker(e, NodeFilter.SHOW_TEXT); for (let n = w.nextNode(); n; n = w.nextNode()) { if (n.parentElement.closest('.others') || !n.data.trim()) continue; const r = document.createRange(); r.setStart(n, 0); r.setEnd(n, 1); const x = r.getClientRects()[0]; return x ? {x: x.left, y: x.top - top, w: x.width, h: x.height} : null; } return null; };
        return {plan, text: read(counted), without: read(uncounted), same, lay_fs: L.LAY_FS, width: counted.getBoundingClientRect().width, advance: L.CHAR_W,
                count: c ? {pos: host ? Number(host.dataset.pos) : null, rect: q(c), block: host ? q(host) : null, line: host ? firstLine(host) : null, text: c.textContent} : null};
      } finally { counted.remove(); uncounted.remove(); }
    })()''' % STAND_IN_CPL)


def same_lines(t, w):
    """do a block as the DOM sets it with its count and without stand on the same lines: as many, at its top and its
    height within HANDOFF_TOL_PX?"""
    if t['lines'] is None or w['lines'] is None:
        return False
    return t['lines'] == w['lines'] and abs(t['top'] - w['top']) <= HANDOFF_TOL_PX and abs(t['height'] - w['height']) <= HANDOFF_TOL_PX


def stand_in_holds(ctx, r):
    """THE HANDOFF's checks over the stand-in article (issue #151's design decision: the count stands in its column's
    edge and sets no line — A-254); its figures"""
    v = stand_in_view(ctx)
    a, b, c = v['plan']
    staged = a['lines'] == 2 and b['lines'] == 0 and c['lines'] >= 2
    r.check(staged and v['same'], 'the stand-in: P-LAY sets its first block on its own two lines, the count setting none — its lines the same as with no count — its second block, a separator alone, on no line, its third on two lines or more', {'plan': v['plan'], 'same_as_with_no_count': v['same']})
    moved = [dict(t, without=w) for t, w in zip(v['text'], v['without']) if not same_lines(t, w)]
    lines = [t['lines'] for t in v['text']]
    r.check(all(n is not None for n in lines) and lines[0] >= 1 and lines[1] == 0 and lines[2] >= 1 and not moved,
            f'the stand-in, set {STAND_IN_CPL} of its face\'s average advance wide: each block — the count\'s, the separator alone, the one after them — stands on the same lines with its count as with none, its top and its height within {HANDOFF_TOL_PX} px and as many lines (A-254); the separator alone on no line',
            {'with': v['text'], 'moved': moved, 'width_px': v['width'], 'advance': v['advance']})
    t0, t2 = v['text'][0], v['text'][2]
    dom = t2['top'] - (t0['top'] + t0['height']) if t0['top'] is not None and t2['top'] is not None else None
    planned = c['top'] - (a['top'] + a['height']) if a['top'] is not None and c['top'] is not None else None
    r.check(dom is not None and planned is not None and abs(dom - planned) <= HANDOFF_TOL_PX,
            f'the stand-in: the separator alone\'s margins collapse into one as P-LAY collapses them — the block after it stands as far below the block before it as P-LAY sets it, {HANDOFF_TOL_PX} px either way',
            {'dom_px': dom, 'plan_px': planned})
    n, gap, edge = v['count'], EDGE_GAP_EM * v['lay_fs'], EDGE_EM * v['lay_fs']
    in_edge = bool(n) and n['block'] is not None and n['line'] is not None and n['pos'] == a['pos']
    if in_edge:
        q, blk, line = n['rect'], n['block'], n['line']
        in_edge = (abs(q['x'] - (blk['x'] + blk['w']) - gap) <= HANDOFF_TOL_PX and q['x'] + q['w'] <= blk['x'] + blk['w'] + edge + HANDOFF_TOL_PX
                   and abs((q['y'] + q['h'] / 2) - (line['y'] + line['h'] / 2)) <= HANDOFF_TOL_PX and not meets(q, blk))
    r.check(in_edge, f'the stand-in: the others\' count stands in its column\'s edge — {gap} px past its block\'s text, inside the {edge} px edge, level with the block\'s first line, {HANDOFF_TOL_PX} px either way — and on none of its text', n)
    return {'blocks': v['text'], 'plan': v['plan'], 'count': n}


def label_view(ctx):
    """the labels the last frame set and left out, beside the places the projection and the fold give, on screen: the
    outlines of the documents in view that no mark drawn the stronger holds (none where the frame draws the clusters the
    stronger) — each the disjoint rects of its padded columns (issue #15: the document's one edge traces its columns) —
    the marks drawn the stronger, the accounts' cells, the board's label cell — the first of its user grid, three cells
    across (P-PROJ's G) — the first row of the outline of each document labelled, where its label stands, the visible
    view below the one line, and each mid connection drawn — its two places, named as a pair in sorted order, its count,
    the count set on it, and its places' centres, a document's its outline's, a mark's the centre of its continuation's
    cell — and each tail drawn: its site, its links and their far documents, where its stroke leaves and ends; the shape of
    each held label's place (issue #169), by its kind and place — a document's outline's rects, a mark's cell for each
    of its labels (issue #42), an account's cell — the places the one line names, and for each document labelled the lead its label sets (the page's
    first-line rule), where its first line stands in its fold (issue #23) and the clause it carries while it stands kept (issue #368)"""
    return ctx.js('''(async () => {
      const P = await import('./plane/projection.js'), T = await import('./text/layer.js');
      const S = window.__skep, c = S.view.camera(), p = S.view.viewport(), lod = S.view.lod();
      const scr = (b) => ({x: (b.x - c.x) * c.scale + p.VW / 2, y: (b.y - c.y) * c.scale + p.VH / 2, w: b.w * c.scale, h: b.h * c.scale});
      const view = {x: 0, y: 0, w: p.VW, h: p.VH}, top = document.getElementById('line').getBoundingClientRect().bottom;
      const cell = (place) => { const i = place.indexOf(':'); return scr(i < 0 ? S.fold(place).outline : P.continuationCell(place.slice(0, i), Number(place.slice(i + 1)))); };
      const centre = (place) => { const b = cell(place); return {x: b.x + b.w / 2, y: b.y + b.h / 2}; };
      const connections = S.connections().map((x) => ({place: [x.a, x.b].sort().join('|'), count: x.count, label: x.label ?? null, ends: [centre(x.a), centre(x.b)]}));
      const crosses = (a, b) => a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h;
      const labels = S.labels();
      const marks = S.residues().filter((m) => m.alpha >= 0.5);
      const held = new Set(marks.flatMap((m) => m.members));
      const boxesDrawn = lod.name !== 'far' && (lod.name !== 'far~mid' || lod.fade >= 0.5);
      const places = S.model.places().filter((q) => !q.system);
      const boxes = boxesDrawn ? places.filter((q) => !held.has(q.doc) && crosses(scr(S.boxOf(q.doc)), view)).flatMap((q) => S.fold(q.doc).rects.map((r) => ({place: q.doc, rect: scr(r)}))).filter((b) => crosses(b.rect, view)) : [];
      const accounts = S.model.counts().filter((a) => !a.system).map((a) => ({place: a.account, rect: scr(S.accountCell(a.account))}));
      const b = S.boardCell('1');
      const docs = Object.fromEntries(labels.filter((l) => l.kind === 'doc').map((l) => [l.place, scr(S.fold(l.place).row)]));
      // each document's label room: its outline's first row, inside the half gutter its columns are padded by
      const inner = (f) => { const g = S.constants.GUTTER / 2 * f.fs; return scr({x: f.row.x + g, y: f.row.y + g, w: f.row.w - 2 * g, h: f.row.h - 2 * g}); };
      const rows = Object.fromEntries(boxesDrawn ? places.filter((q) => !held.has(q.doc) && crosses(scr(S.boxOf(q.doc)), view)).map((q) => [q.doc, inner(S.fold(q.doc))]) : []);
      // the shape of each held label's place: a document's outline's rects, a mark's cell, an account's cell
      const shapeOf = (l) => l.kind === 'doc' ? S.fold(l.place).rects.map(scr) : ['mark', 'newest', 'member'].includes(l.kind) ? [cell(l.place)] : [scr(S.accountCell(l.place))];
      // each document labelled: the lead the page's first-line rule gives it and where its first line stands in its fold, on screen
      const leads = Object.fromEntries(labels.filter((l) => l.kind === 'doc').map((l) => { const at = S.fold(l.place).lead; return [l.place, {words: S.firstLine(l.place).lead, at: scr({x: at.x, y: at.y, w: 0, h: at.h})}]; }));
      // each document labelled: the clause it carries while it stands kept, else null
      const kept = Object.fromEntries(labels.filter((l) => l.kind === 'doc').map((l) => { const k = T.keptIn(l.place); return [l.place, k ? k.text : null]; }));
      return {lod: lod.name, view, seen: {x: 0, y: top, w: p.VW, h: p.VH - top}, labels, out: S.labelsLeftOut(), marks: marks.map((m) => ({place: m.key, rect: m.rect, lines: m.lines})), leads, kept,
              boxes, rows, accounts, board: scr({x: b.x, y: b.y, w: b.w / 3, h: b.h / 3}), docs, connections, mounted: S.mountedAddrs(),
              tails: S.tails().map((t) => ({key: t.key, links: t.links, far: t.far, from: t.from, to: t.to})),
              held: Object.fromEntries(labels.filter((l) => l.held).map((l) => [l.kind + ' ' + l.place, shapeOf(l)])), named: S.named()};
    })()''')


def inside(a, b):
    """is `a` inside `b`, LABEL_TOL_PX either way?"""
    return a['x'] >= b['x'] - LABEL_TOL_PX and a['y'] >= b['y'] - LABEL_TOL_PX and a['x'] + a['w'] <= b['x'] + b['w'] + LABEL_TOL_PX and a['y'] + a['h'] <= b['y'] + b['h'] + LABEL_TOL_PX


def meets(a, b):
    """do two rects overlap by more than LABEL_TOL_PX each way?"""
    return min(a['x'] + a['w'], b['x'] + b['w']) - max(a['x'], b['x']) > LABEL_TOL_PX and min(a['y'] + a['h'], b['y'] + b['h']) - max(a['y'], b['y']) > LABEL_TOL_PX


def place_of(v, label):
    """a label's place on screen, as the projection gives it; None where the frame drew no such place — and for a
    connection's count, whose place is its stroke (`on_stroke`)"""
    kind, place = label['kind'], label['place']
    if kind == 'board':
        return v['board']
    if kind in ('cluster', 'frame'):
        return next((a['rect'] for a in v['accounts'] if a['place'] == place), None)
    if kind in ('mark', 'newest', 'member'):
        return next((m['rect'] for m in v['marks'] if m['place'] == place), None)
    if kind == 'doc':
        return v['docs'].get(place)
    return None


def on_stroke(v, label, line):
    """does a connection's count stand on its stroke: its line's centre on the segment between its connection's two
    places' centres, as the projection gives them, LABEL_TOL_PX either way, and the line inside the visible view?"""
    c = next((c for c in v['connections'] if c['place'] == label['place']), None)
    if c is None:
        return False
    a, b, q = c['ends'][0], c['ends'][1], line['rect']
    px, py = q['x'] + q['w'] / 2, q['y'] + q['h'] / 2
    dx, dy = b['x'] - a['x'], b['y'] - a['y']
    t = max(0, min(1, ((px - a['x']) * dx + (py - a['y']) * dy) / ((dx * dx + dy * dy) or 1)))
    return math.hypot(a['x'] + dx * t - px, a['y'] + dy * t - py) <= LABEL_TOL_PX and inside(q, v['seen'])


def at_tail(v, label, line):
    """does a tail's label stand at its tail's end: its lines' left edge TAIL_GAP_PX past the end of the tail's stroke, its first
    line centred on the stroke's height and every later one below it, LABEL_TOL_PX either way, inside the visible view?"""
    t = next((t for t in v['tails'] if t['key'] == label['place']), None)
    if t is None:
        return False
    first, q = label['lines'][0]['rect'], line['rect']
    return (abs(q['x'] - (t['to']['x'] + TAIL_GAP_PX)) <= LABEL_TOL_PX and abs(first['y'] + first['h'] / 2 - t['from']['y']) <= LABEL_TOL_PX
            and q['y'] >= first['y'] - LABEL_TOL_PX and inside(q, v['seen']))


def in_shape(q, shape):
    """does a held line stand inside its place's shape — rects sharing their left edge, a document's outline's rows — between
    the left and right edges of the rects holding its foot, the narrowest row it meets, LABEL_TOL_PX either way?"""
    at = q['y'] + q['h'] - LABEL_TOL_PX
    row = [s for s in shape if s['y'] <= at < s['y'] + s['h']]
    return bool(row) and q['x'] >= min(s['x'] for s in row) - LABEL_TOL_PX and q['x'] + q['w'] <= max(s['x'] + s['w'] for s in row) + LABEL_TOL_PX


def in_held(v, label, line):
    """does a label held below the one line stand inside its place's shape (`in_shape`), its bottom inside the visible view
    and the line across it inside the view, LABEL_TOL_PX either way (issue #169: "A label never leaves its box")?"""
    q, seen = line['rect'], v['seen']
    return (in_shape(q, v['held'].get(label['kind'] + ' ' + label['place'], []))
            and q['y'] + q['h'] > seen['y'] + LABEL_TOL_PX and q['x'] >= seen['x'] - LABEL_TOL_PX and q['x'] + q['w'] <= seen['x'] + seen['w'] + LABEL_TOL_PX)


def address_line(label):
    """the line of a label the canvas set whose every run is in the identifier's face: a document's address (issue #23)"""
    return next((x for x in label['lines'] if x.get('runs') and all(q['face'] == 'ident' for q in x['runs'])), None)


def word_cut(text, words):
    """is `text` a document's lead `words` as a label sets it (issue #23's design decision: "cut on a word"): whole; or a start of
    its whole words — a separator ending the start dropped — with LEAD_WORDS words kept at the least, ending in an ellipsis and the
    bracket its words close with; or, cut apart from a lead that reads alike, its first word, an ellipsis, then a run of its words?"""
    if text == words:
        return True
    close = ']' if words.endswith(']') and words.startswith('[') else ''
    ws = words.split(' ')
    if ' … ' in text:
        head, rest = text.split(' … ', 1)
        for suffix in ('…' + close, ''):
            if suffix and not rest.endswith(suffix):
                continue
            tail = (rest[:-len(suffix)] if suffix else rest).split(' ')
            if head == ws[0] and any(ws[i:i + len(tail)] == tail and (suffix or i + len(tail) == len(ws)) for i in range(2, len(ws))):
                return True
        return False
    end = '…' + close
    if not text.endswith(end):
        return False
    start = text[:-len(end)].split(' ')
    real = [w for w in start if re.search(r'\w', w)]
    return len(start) < len(ws) and ws[:len(start)] == start and len(real) >= LEAD_WORDS and bool(re.search(r'\w', start[-1]))


def labels_hold(r, name, v):
    """THE LABELS' checks at one view; its figures: the labels set by kind, the parts left out by rule, the
    connections' counts set and left out"""
    labels = v['labels']
    small = [{'kind': l['kind'], 'place': l['place'], 'text': x['text'], 'px': x['px']} for l in labels for x in l['lines'] if x['px'] < MIN_LABEL_PX]
    r.check(not small, f'{name}: (i) every label the canvas set, the trail\'s pip numbers among them, is {MIN_LABEL_PX} px or larger', small[:6])
    placed = [(l, place_of(v, l), x) for l in labels if l['kind'] != 'pip' for x in l['lines']]
    outside = [{'kind': l['kind'], 'place': l['place'], 'held': l.get('held'), 'text': x['text'], 'rect': x['rect'], 'place_rect': p} for l, p, x in placed
               if (not on_stroke(v, l, x) if l['kind'] == 'connection' else not at_tail(v, l, x) if l['kind'] == 'tail' else not in_held(v, l, x) if l.get('held')
                   else p is None or not inside(x['rect'], p) or not inside(x['rect'], v['seen']))]
    r.check(not outside, f'{name}: (ii) every label lies inside its place, as the projection gives it, and inside the visible view below the one line, which stands opaque over the strip above it — a connection\'s count centred on its stroke, the segment between its two places\' centres, a tail\'s label at its stroke\'s end, a label held below the line inside its place\'s shape, its bottom in view — {LABEL_TOL_PX} px either way',
            {'outside': outside[:6], 'seen': v['seen']})
    lines = [(l, [x['rect'] for x in l['lines']]) for l in labels if l.get('held')]
    r.check(all(len({(q['y'], q['h']) for q in qs}) == 1 for _, qs in lines), f'{name}: every label held below the one line stands on one line, never wrapped (issue #169)',
            [[l['kind'], l['place'], qs] for l, qs in lines if len({(q['y'], q['h']) for q in qs}) != 1][:4])
    crossing = [{'a': [a[0]['kind'], a[0]['place'], a[2]['text']], 'b': [b[0]['kind'], b[0]['place'], b[2]['text']]} for i, a in enumerate(placed) for b in placed[i + 1:] if meets(a[2]['rect'], b[2]['rect'])]
    r.check(not crossing, f'{name}: (iii) no two labels meet', crossing[:6])
    met = []
    for l, p, x in placed:
        others = [('box', o) for o in v['boxes'] if o['place'] != l['place']] + [('mark', o) for o in v['marks'] if o['place'] != l['place']]
        if l['kind'] not in ('connection', 'tail'):
            others += [('account', o) for o in v['accounts'] if p is None or not inside(p, o['rect'])]
        met += [{'kind': l['kind'], 'place': l['place'], 'text': x['text'], 'meets': [what, o['place']]} for what, o in others if meets(x['rect'], o['rect'])]
    r.check(not met, f'{name}: (iv) no label meets another place: the box of a document in view that no mark drawn the stronger holds, a continuation\'s mark, an account\'s cell that does not hold its place — a connection\'s count and a tail\'s label, no one account\'s, meeting no box and no mark, the tail\'s own document\'s among them', met[:6])
    # (v) the address (issue #23's design decision: "Show only the fields past the region's prefix while that region's label is in
    # view"; foundations F-9): every document's label carries its address whole in the identifier's face, past its region's prefix
    # only where the region's label is set in this frame or the one line names the region
    regions = {l['place'] for l in labels if l['kind'] in ('frame', 'cluster')} | ({v['named']['account']} if v['named']['account'] else set())
    unnamed = []
    for l in labels:
        if l['kind'] != 'doc':
            continue
        acct, a = account_of(l['place']) or '', address_line(l)
        want = l['place'][len(acct):] if acct in regions else l['place']
        if a is None or a['text'] != want:
            unnamed.append({'place': l['place'], 'address': a and a['text'], 'want': want, 'region_named': acct in regions})
    r.check(not unnamed, f'{name}: (v) every document\'s label carries its address whole in the identifier\'s face — its fields past its region\'s prefix (".0.3") only where its region\'s label is set in view or the one line names the region, its whole address elsewhere (issue #23)', unnamed[:6])
    # (v-b) the contents line (issue #23's design decision: "Set it at the head of the first column, where those words will stand when
    # the text mounts ... at the end of that row, like a page number"): a document's label set in its place stands on one row — its
    # address ending at the end of its outline's first row, or, while the document stands kept, before its clause, which ends there
    # (issue #368's design decision: "the clause follows the address"); its first line, where set, the page's lead cut on a whole word,
    # LEAD_WORDS kept at the least, starting where those words stand in its fold and centred on that line, unless its row is held to its
    # first row's top
    astray = []
    for l in labels:
        if l['kind'] != 'doc' or l.get('held') or l['place'] not in v['rows']:
            continue
        a, row, lead, kept = address_line(l), v['rows'][l['place']], v['leads'].get(l['place']), v['kept'].get(l['place'])
        if a is None:
            continue
        mid = a['rect']['y'] + a['rect']['h'] / 2
        level = lambda x: abs(x['rect']['y'] + x['rect']['h'] / 2 - mid) <= LABEL_TOL_PX
        # its kept clause where it stands on the row: its words whole, level with the address
        after = next((x for x in l['lines'] if x is not a and kept and x['text'] == kept and level(x)), None)
        on_row = [x for x in l['lines'] if x is not a and x is not after and level(x)]
        row_top = mid - max([a['rect']['h']] + [x['rect']['h'] for x in on_row]) / 2
        end = (after or a)['rect']
        end_ok = abs(end['x'] + end['w'] - (row['x'] + row['w'])) <= LABEL_TOL_PX and (after is None or a['rect']['x'] + a['rect']['w'] < after['rect']['x'])
        lead_mid = lead and lead['at']['y'] + lead['at']['h'] / 2
        firsts_ok = len(on_row) <= 1 and all(lead and word_cut(x['text'], lead['words']) and abs(x['rect']['x'] - lead['at']['x']) <= LABEL_TOL_PX
                                             and (abs(mid - lead_mid) <= LABEL_TOL_PX or abs(row_top - row['y']) <= LABEL_TOL_PX) for x in on_row)
        if not (end_ok and firsts_ok):
            astray.append({'place': l['place'], 'address': a['rect'], 'kept': after and [after['text'], after['rect']], 'row': row, 'first': [[x['text'], x['rect']] for x in on_row], 'lead': lead})
    r.check(not astray, f'{name}: (v-b) every document\'s label set in its place is one contents line — its address ending at its outline\'s first row\'s end, or before its kept clause, which ends there; its first line, where set, its lead cut on a whole word with {LEAD_WORDS} words kept at the least, starting where those words stand in its fold and level with that line — {LABEL_TOL_PX} px either way (issues #23, #368)', astray[:6])
    # the connections' counts (foundations §2.1's register: "one connection drawn per document pair with its count"; P44 forbids a merged mark
    # that hides it): the numeral of its links on each holding two or more, else the rule that left it out named; none on one holding one
    conns = v['connections']
    counts = {l['place']: l['lines'][0]['text'] for l in labels if l['kind'] == 'connection'}
    left = {o['place']: o['reason'] for o in v['out'] if o['kind'] == 'connection'}
    wrong = [{'place': c['place'], 'count': c['count'], 'carries': c['label'], 'set': counts.get(c['place']), 'left_out': left.get(c['place'])} for c in conns
             if (c['count'] >= 2 and not (counts.get(c['place']) == c['label'] == str(c['count']) or (c['label'] is None and c['place'] in left)))
             or (c['count'] < 2 and (c['label'] is not None or c['place'] in counts or c['place'] in left))]
    stray = sorted((set(counts) | set(left)) - {c['place'] for c in conns})
    r.check(not wrong and not stray, f'{name}: (vi) every mid connection holding two links or more carries its count on its stroke — the numeral of its links — or the pass names the rule that left it out; none holding one carries a count, and no count stands for a connection the frame did not draw',
            {'wrong': wrong[:6], 'stray': stray[:6]})
    # the tails' labels (issue #132's design decision: a tail "ending in that label"; "tails ... merge into one tail showing their count"):
    # the numeral of its links on each holding two or more, its far document's address leading the label of each holding one, else the
    # rule that left it out named; none for a tail the frame did not draw
    tails = v['tails']
    tail_set = {l['place']: [x['text'] for x in l['lines']] for l in labels if l['kind'] == 'tail'}
    tail_left = {o['place']: o['reason'] for o in v['out'] if o['kind'] == 'tail'}
    want = lambda t: str(len(t['links'])) if len(t['links']) > 1 else t['far'][0]
    untold = [{'key': t['key'], 'links': len(t['links']), 'set': tail_set.get(t['key']), 'left_out': tail_left.get(t['key'])} for t in tails
              if not ((tail_set.get(t['key']) or [None])[0] == want(t) or (t['key'] not in tail_set and t['key'] in tail_left))]
    stray_tails = sorted((set(tail_set) | set(tail_left)) - {t['key'] for t in tails})
    r.check(not untold and not stray_tails, f'{name}: (viii) every tail carries at its end the count of its links where it holds two or more — the numeral — and its far document\'s address where it holds one, or the pass names the rule that left its label out; no tail\'s label stands for a tail the frame did not draw',
            {'untold': untold[:6], 'stray': stray_tails[:6]})
    if name in ('mid-extents', 'home'):
        hidden = [[c['place'], c['count'], left.get(c['place'])] for c in conns if c['count'] >= 2 and c['label'] != str(c['count'])]
        r.check(any(c['count'] >= 2 for c in conns) and not hidden, f'{name}: (vii) no count is hidden — every mid connection holding two links or more carries it',
                {'hidden': hidden, 'connections': [[c['place'], c['count'], c['label']] for c in conns][:12]})
    if name == 'home':
        # the label rule (F-9; foundations §2.1: drawn only where its place holds it): a document's label stands in its
        # outline's first row (issue #15), so it is set wherever that row holds its address at the floor — past its region's
        # prefix where (v) has it so, set in the identifier face, Atkinson Hyperlegible Mono, 0.632 em a character (issue #16),
        # the case's own bound, and a line box tall — and named left out wherever it does not
        labelled = {l['place'] for l in labels if l['kind'] == 'doc'}
        named = {o['place'] for o in v['out'] if o['kind'] == 'doc'}
        shown = {o['place'] for o in v['boxes'] if o['place'] not in v['mounted']}
        whole = sorted(q for q in shown if all(inside(o['rect'], v['seen']) for o in v['boxes'] if o['place'] == q))
        addr_of = lambda q: q[len(account_of(q) or ''):] if (account_of(q) or '') in regions else q
        holds = lambda q: v['rows'][q]['w'] >= len(addr_of(q)) * MIN_LABEL_PX * 0.632 + 1 and v['rows'][q]['h'] >= MIN_LABEL_PX * 1.2 + 1
        must = [q for q in whole if holds(q)]
        r.check(bool(must) and set(must) <= labelled and set(whole) <= labelled | named,
                'home: every document standing whole in the visible view whose outline\'s first row holds its address at the label floor carries its label, and every other is named left out by the rule that left it out',
                {'in_view': len(whole), 'rows_holding': len(must), 'unlabelled': sorted(set(must) - labelled)[:8], 'unnamed': sorted(set(whole) - labelled - named)[:8]})
        r.check(any(m['lines'] for m in v['marks']), 'home: the continuation drawn as one mark carries its count', [m['lines'] for m in v['marks']])
    if name == 'whole-board':
        named = {(l['kind'], l['place']) for l in labels}
        r.check(('board', '1') in named and ('cluster', '1.0.1') in named, 'whole-board: the board and the acting account\'s cluster carry their labels', sorted(named))
    by_kind, by_rule = {}, {}
    for l in labels:
        by_kind[l['kind']] = by_kind.get(l['kind'], 0) + 1
    for o in v['out']:
        by_rule[o['reason']] = by_rule.get(o['reason'], 0) + 1
    counts_out = {}
    for reason in left.values():
        counts_out[reason] = counts_out.get(reason, 0) + 1
    return {'lod': v['lod'], 'set': by_kind, 'left_out': by_rule, 'left_out_parts': [[o['kind'], o['place'], o['text'][:48], o['reason']] for o in v['out'] if o['reason'] != 'after'][:12],
            'counts': {'connections': len(conns), 'holding_two_or_more': sum(1 for c in conns if c['count'] >= 2), 'set': len(counts), 'left_out': counts_out},
            'tails': {'drawn': len(tails), 'labels_set': len(tail_set), 'left_out': len(tail_left)}}


def tails_hold(ctx, r):
    """THE TAILS' checks at the first edition, the reveal at stage 3 and the camera over its first column at em 12.5 (issue
    #132's design decision: a link whose far document the plane draws nowhere leaves its near end by a short tail, "at reading
    scale ... the document's edge at its passage's line", replacing the connection and the stub): the case's own reading of
    which of its drawn links reach a document the plane draws nowhere — one `places` does not list and the model holds no text,
    metadata or withheld box of — each tailed (LK's `tailed`) and drawing no beam; each whose passage's last line stands in the
    visible view carried by a tail drawn there; each tail leaving at its passage's own line — level with one of its links' marked
    words' line rects — from the edge of the part of its block holding the line (`tailAnchors`, read apart from the canvas as a
    beam's are); its figures"""
    v = ctx.js('''(async (doc) => {
      const A = await import('./model/address.js');
      const S = window.__skep, places = new Set(S.model.places().filter((p) => !p.system).map((p) => p.doc));
      const nowhere = (far) => { const d = S.model.doc(far); return !places.has(A.documentOf(far) || far) && d.from < 0 && !d.meta && d.refused !== 'withheld'; };
      const top = document.getElementById('line').getBoundingClientRect().bottom, vp = S.view.viewport();
      const art = document.querySelector(`#domlayer article.dtext[data-addr="${doc}"]`);
      const shown = S.links.shown(doc).map((x) => {
        const words = art ? [...art.querySelectorAll(`.lip[data-links~="${x.link}"]`)].flatMap((w) => [...w.getClientRects()]).filter((q) => q.width > 0 && q.height > 0) : [];
        const last = words[words.length - 1], mid = last ? last.top + last.height / 2 : null;
        return {link: x.link, far: x.far, pos: x.pos, nowhere: !!x.far && nowhere(x.far), tailed: S.links.tailed(doc, x.link), seen: mid != null && mid >= top && mid <= vp.VH};
      });
      return {shown, beams: S.beamAnchors().filter((a) => a.near === doc).map((a) => a.link), tails: S.tails().filter((t) => t.at === doc && t.form === 'line'), anchors: S.tailAnchors().filter((a) => a.at === doc)};
    })(%s)''' % json.dumps(DOC))
    nowhere = sorted(x['link'] for x in v['shown'] if x['nowhere'])
    tailed = sorted(x['link'] for x in v['shown'] if x['tailed'])
    r.check(bool(nowhere) and tailed == nowhere, 'the tails: every link the first edition draws whose far document the plane draws nowhere — by the case\'s own reading — is tailed, and no other',
            {'drawn_nowhere': nowhere, 'tailed': tailed})
    beamed = sorted(set(v['beams']) & set(tailed))
    r.check(not beamed, 'the tails: no tailed link draws a beam, which would point at its address\'s place on the plane', beamed)
    carried = {l for t in v['tails'] for l in t['links']}
    lost = [x['link'] for x in v['shown'] if x['tailed'] and x['seen'] and x['link'] not in carried]
    r.check(any(x['tailed'] and x['seen'] for x in v['shown']) and not lost, 'the tails: every tailed link whose passage\'s last line stands in the visible view leaves it by a tail drawn there',
            {'lost': lost, 'tails': [[t['key'], t['links']] for t in v['tails']]})
    off = [{'links': a['links'], 'pos': a['pos'], 'x': a['x'], 'y': a['y'], 'edge': a['edge'], 'words': a['words'][:4]} for a in v['anchors'] if not on_own_line(a)]
    r.check(bool(v['anchors']) and not off, f'the tails: every tail leaves the text at its passage\'s own line, from the article\'s edge — its point\'s y within one of its links\' marked words\' line rects and its x at the edge of the part of the block holding the line, {ANCHOR_TOL_PX} px either way',
            off[:4])
    return {'drawn_nowhere': len(nowhere), 'tailed': len(tailed), 'tails': [[t['links'], t['label']] for t in v['tails']], 'on_own_line': len(v['anchors']) - len(off), 'off_own_line': len(off)}


def beams_hold(ctx, r):
    """THE BEAMS' checks where citations reach documents the plane draws — at BEAMED, a citer of FAR_LEAP, at em 12.5 over the
    passage whose line the most beams leave inside the visible view, the reveal at stage 3: every beam whose leaving line the
    view holds — a line the article stands, where the oracle reads (FP-12) — leaving the text at its span's own line, from the
    edge of the part of its block that holds the line (its endpoint level with one of its marked words' line rects, at that
    part's edge — foundations §2.1; S1 Q1), a beam leaving at a line past the view counted unmeasured (FP-18); every stub
    whose beam leaves the text in the visible view carrying its far document's label inside that view (S1 Q3); and, where two
    labels or more stand in view, no two of them meeting — issue #9's, marked, and unmeasured where fewer stand; its figures"""
    ctx.leap(BEAMED, None)
    ctx.js('window.__skep.links.reveal(%s, 3)' % json.dumps(BEAMED))
    ctx.settle()
    ctx.frames(3)
    scale = ctx.js('window.__skep.scaleFor(%s, "em", 12.5)' % json.dumps(BEAMED))
    vp = ctx.js('window.__skep.view.viewport()')
    top = ctx.js("document.getElementById('line').getBoundingClientRect().bottom")
    view = {'x': 0, 'y': top, 'w': vp['VW'], 'h': vp['VH'] - top}
    leaving = lambda anchors: [a for a in anchors if 0 <= a['x'] <= vp['VW'] and top <= a['y'] <= vp['VH']]
    beamed = [x for x in ctx.js('window.__skep.links.shown(%s)' % json.dumps(BEAMED)) if ctx.js('window.__skep.links.tailed(%s, %s)' % (json.dumps(BEAMED), json.dumps(x['link']))) is False]
    best = None
    for pos in sorted({x['pos'] for x in beamed}):
        ctx.view_at(BEAMED, pos, scale)
        n = len(leaving(ctx.js('window.__skep.beamAnchors()')))
        if best is None or n > best[1]:
            best = (pos, n)
    r.check(best is not None, f'{BEAMED} draws beams: its citations reach documents the plane draws', [x['link'] for x in beamed])
    if best is None:
        ctx.js('window.__skep.links.hide(%s)' % json.dumps(BEAMED))
        return None
    ctx.view_at(BEAMED, best[0], scale)
    ctx.frames(3)
    anchors = ctx.js('window.__skep.beamAnchors()')
    r.check(len(anchors) >= 1, f'beams are built at stage 3 at {BEAMED}', len(anchors))
    # the oracle reads the article's standing lines (FP-12): a beam leaving at a line the view holds is held to it; one leaving
    # at a line past the view, which stands nowhere, is counted unmeasured (FP-18)
    standing = [a for a in anchors if 0 <= a['rect']['y'] + a['rect']['h'] / 2 <= vp['VH'] and a['rect']['x'] <= vp['VW'] and a['rect']['x'] + a['rect']['w'] >= 0]
    r.check(bool(standing) and all(a['words'] for a in standing), 'every beam leaving at a line the view holds has its link marked at its words in the mounted article (the oracle\'s rects exist)',
            {'unmarked': [a['link'] for a in standing if not a['words']], 'standing': len(standing), 'anchors': len(anchors)})
    off = [{'link': a['link'], 'pos': a['pos'], 'x': a['x'], 'y': a['y'], 'edge': a['edge'], 'words': a['words']} for a in standing if not on_own_line(a)]
    r.check(not off, f'every beam leaving at a line the view holds leaves the text at its span\'s own line, from the article\'s edge: its endpoint\'s y within one of its words\' line rects and its x at the article\'s edge, {ANCHOR_TOL_PX} px either way', off[:4])
    # the stubs' labels (S1 Q3): every bundle with a beam that leaves the text in the visible view and ends at the view's border sets the label
    # naming its far document, in the visible view — below the one line, which stands over the beams. A beam whose line lies past the visible
    # view — under the one line, or past the viewport — is cut at its start where it is bound away from the view, and sets no label there,
    # where none would stand whole in the view (beams.test.js holds that rule)
    labels = ctx.js('window.__skep.beamLabels()')
    stubbed = sorted({(a['near'], a['far']) for a in leaving(anchors) if a['stub']})
    named = {(l['near'], l['far']) for l in labels if l['stub'] and l['text'].startswith(l['far']) and inside(l['rect'], view)}
    r.check(bool(stubbed) and set(stubbed) <= named, f'every stub in view carries its far document\'s label: each bundle with a beam that leaves the text in the visible view and ends at the view\'s border sets a label naming its far document, inside the visible view below the one line, {LABEL_TOL_PX} px either way',
            {'stubbed': stubbed, 'labels': [[l['far'], l['text'], l['rect']] for l in labels], 'view': view})
    in_view = [l for l in labels if meets(l['rect'], view)]
    met = [[a['far'], b['far'], a['rect'], b['rect']] for i, a in enumerate(in_view) for b in in_view[i + 1:] if meets(a['rect'], b['rect'])]
    if len(in_view) >= 2:
        r.check(not met, f'no two beam labels in view meet, {LABEL_TOL_PX} px either way', met[:6], xfail=XFAIL_BEAM_LABELS)
    else:
        r.note(f'the beam labels\' meeting (issue #9) is unmeasured at {BEAMED}: fewer than two labels stand in view')
    # whether a beam stub at this view is bound above the visible view's top, whose label is set below its cut; none, and beams.test.js alone holds that rule
    above = ctx.js('''((fars, top) => { const S = window.__skep, c = S.view.camera(), p = S.view.viewport();
      return fars.filter((f) => { const b = S.boxOf(f); return (b.y + b.h / 2 - c.y) * c.scale + p.VH / 2 < top; }); })(%s, %s)''' % (json.dumps(sorted({a['far'] for a in anchors if a['stub']})), json.dumps(top)))
    ctx.js('window.__skep.links.hide(%s)' % json.dumps(BEAMED))
    return {'doc': BEAMED, 'at': best[0], 'count': len(anchors), 'stubs': sum(1 for a in anchors if a['stub']), 'far': sorted({a['far'] for a in anchors})[:8], 'on_own_line': len(standing) - len(off), 'off_own_line': len(off),
            'unmeasured_past_view': len(anchors) - len(standing),
            'stubs_in_view': len(stubbed), 'labels': len(labels), 'labels_in_view': len(in_view), 'labels_meeting_pairs': len(met) if len(in_view) >= 2 else 'unmeasured: fewer than two labels in view',
            'stubs_bound_above': above or 'unmeasured: no beam stub at em 12.5 is bound above the visible view\'s top'}


def type_view(ctx):
    """the first edition's mounted article as the person meets it, in px at the layout size: each element that sets
    text in its lines — a sign in a column's edge apart — with its font size and its line height; the head's lines, each
    with its height beside P-LAY's line box for its size; every heading element it holds; each typed line's element —
    its block, the character its part starts at, its white space, its indent, its size and its weight, and the
    character the bytes delivered hold before its block; each block that sets a line, in each part, its top below the
    block before it there; the body's size; the first family the computed face of each voice names — a typed line's,
    the head's byline's, the head's address's — and the platform's font set asked of each face the page ships; the
    advance of a weighed sample set in a typed line"""
    art = json.dumps('#domlayer article.dtext[data-addr="%s"]' % DOC)
    return ctx.js('''(async () => {
      const L = await import('./plane/layout.js');
      const S = window.__skep, m = S.mounted(%s), art = document.querySelector(%s);
      if (!m || !art) return null;
      const s = S.view.camera().scale / m.lay;
      const name = (e) => e.tagName.toLowerCase() + (e.className ? '.' + String(e.className).split(' ').join('.') : '');
      const sized = [...art.querySelectorAll('.hd > *, .run > *, .rec .derived, .withheld .arm, .withheld .clause')].map((e) => {
        const cs = getComputedStyle(e); return {el: name(e), pos: e.dataset.pos || null, font: parseFloat(cs.fontSize), line: parseFloat(cs.lineHeight)}; });
      const boxes = [...art.querySelectorAll('.hd .by, .hd .pres')].map((e) => {
        const font = parseFloat(getComputedStyle(e).fontSize); return {el: name(e), pos: e.dataset.pos || null, height: e.getBoundingClientRect().height / s, line_box: L.lineBox(font / L.LAY_FS) * L.LAY_FS}; });
      const headings = [...art.querySelectorAll('h1, h2, h3, h4, h5, h6')].map(name);
      const typed = [...art.querySelectorAll('.run > p.sp')].filter((e) => !e.matches('.empty')).map((e) => { const cs = getComputedStyle(e), pos = Number(e.dataset.pos);
        return {pos, char: Number(e.dataset.char || 0), el: name(e), tag: e.tagName.toLowerCase(), white: cs.whiteSpace, collapse: cs.whiteSpaceCollapse || null, wrap: cs.textWrapMode || null,
                indent: parseFloat(cs.textIndent), font: parseFloat(cs.fontSize), weight: cs.fontWeight, text: (S.model.text(%s, pos, pos + 24) || ''), before: pos > 1 ? S.model.text(%s, pos - 1, pos) : null}; });
      // each block that sets a line, in each part, below the block before it there that sets one
      const steps = [...art.querySelectorAll('.col')].flatMap((col) => { const bs = [...col.querySelectorAll(':scope > .run > .sp, :scope > .run > .withheld')].filter((e) => e.getBoundingClientRect().height > 0);
        return bs.slice(1).map((e, i) => ({pos: Number(e.dataset.pos), after: Number(bs[i].dataset.pos), px: (e.getBoundingClientRect().top - bs[i].getBoundingClientRect().top) / s})); });
      const family = (sel) => { const e = art.querySelector(sel); return e ? getComputedStyle(e).fontFamily.split(',')[0].trim().replace(/^["']|["']$/g, '') : null; };
      const para = art.querySelector('.run > p.sp.blk-para:not(:empty)'), addr = art.querySelector('.hd .addr');
      // the address's advance a character, in em of its own size: its run's width over its characters
      const ident = addr && addr.textContent ? addr.getBoundingClientRect().width / s / [...addr.textContent].length / parseFloat(getComputedStyle(addr).fontSize) : null;
      return {sized, boxes, headings, typed, steps, body: parseFloat(getComputedStyle(art).fontSize), line_box: L.lineBox(1) * L.LAY_FS, faces: {reading: family('.run > p.sp'), client: family('.hd .by'), ident: family('.hd .addr')},
              loaded: %s.map((f) => [f, document.fonts.check(f)]), set: [...document.fonts].map((f) => ({family: f.family.replace(/^["']|["']$/g, ''), style: f.style, weight: f.weight, status: f.status})),
              advance: para ? %s(para, s) / L.LAY_FS : null, ident_advance: ident, page_advance: L.CHAR_W};
    })()''' % (json.dumps(DOC), art, json.dumps(DOC), json.dumps(DOC), json.dumps(SHIPPED_FACES), ADVANCE_JS))


def starts_view(ctx):
    """each line of a typed line of the first edition's fold that stands as text after a standing line of its own,
    as T-LAYER reads it — the position it opens at — beside where its characters stand on screen: its line box and the
    line box before it, each across its column, and the middle of the character at that position and of the last
    character before it, spaces apart, each read through T-LAYER's byte-span mapping over the standing parts
    (`spanRects`)"""
    return ctx.js('''(async (doc) => {
      const T = await import('./text/layer.js'), P = await import('./plane/projection.js'), C = await import('./plane/camera.js');
      const rec = T.mountedSet().get(doc);
      if (!rec) return null;
      const f = rec.fold, box = P.docBox(doc), enc = new TextEncoder(), out = [];
      const byPos = new Map(rec.made.blocks.map((b) => [b.pos, b]));
      const mid = (rs) => { const q = (rs || []).find((x) => x.w > 0 && x.h > 0); return q ? {x: q.x + q.w / 2, y: q.y + q.h / 2} : null; };
      // a line's box on screen, across the column that holds it
      const lineBox = (i) => { const c = f.columns.find((k) => i >= k.first && i < k.first + k.n); if (!c) return null; const l = f.lines[i], y = C.sy(box.y + c.y + (l.top - c.top) * f.fs);
        return {top: y, bottom: y + l.h * f.fs * C.cam.scale, left: C.sx(box.x + c.x), right: C.sx(box.x + c.x + c.w)}; };
      for (const i of [...rec.lines].sort((x, y) => x - y)) {
        const l = f.lines[i], b = l.pos != null ? byPos.get(l.pos) : null;
        if (!b || b.kind !== 'para' || l.kind !== 'text' || l.at == null || l.nth === 0 || !rec.lines.has(i - 1) || f.lines[i - 1].pos !== l.pos || f.lines[i - 1].at == null) continue;
        // the character the line opens at, and the last before it that is not a space, by their byte positions in the block
        let bytes = l.at - b.pos, at = 0;
        for (const ch of b.text) { if (bytes <= 0) break; bytes -= enc.encode(ch).length; at += ch.length; }
        let k = at - 1;
        while (k >= 0 && /\\s/.test(b.text[k])) k--;
        if (k < 0) continue;
        if (k > 0 && b.text.charCodeAt(k) >= 0xdc00 && b.text.charCodeAt(k) <= 0xdfff) k--;
        const before = b.pos + enc.encode(b.text.slice(0, k)).length;
        out.push({line: i, at: l.at, before, box: lineBox(i), prev: lineBox(i - 1), first: mid(T.spanRects(doc, l.at, 1)), last: mid(T.spanRects(doc, before, 1)), text: b.text.slice(at, at + 16)});
      }
      return out;
    })(%s)''' % json.dumps(DOC))


def starts_on_line(x):
    """does a line T-LAYER read begin where its first character stands: the character at the position it opens at on
    the line, and the last one before it, spaces apart, on the line before it?"""
    tol = ANCHOR_TOL_PX
    within = lambda p, q: bool(p and q) and q['top'] - tol <= p['y'] <= q['bottom'] + tol and q['left'] - tol <= p['x'] <= q['right'] + tol
    return within(x['first'], x['box']) and within(x['last'], x['prev'])


def type_holds(ctx, r):
    """THE TYPE's checks over the first edition at reading scale; its figures"""
    ctx.view_doc_em(DOC, 12)
    v = type_view(ctx)
    r.check(v is not None, 'the type: the first edition is mounted at em 12')
    if v is None:
        return None
    off = [x for x in v['sized'] if not x['font'] or abs(x['line'] / x['font'] - LINE_RATIO) > LINE_RATIO_TOL]
    r.check(bool(v['sized']) and not off, f'the type: every element of the first edition that sets text spaces its lines at {LINE_RATIO} of its own size, {LINE_RATIO_TOL} either way — the head\'s lines, the blocks, a record\'s keys, a withheld run\'s face, the offer; a sign in a column\'s edge stands on its block\'s first line instead, which the stand-in holds',
            [dict(x, ratio=round(x['line'] / x['font'], 3) if x['font'] else None) for x in off[:8]])
    unlike = []
    for b in v['boxes']:
        n = round(b['height'] / b['line_box'])
        if n < 1 or abs(b['height'] - n * b['line_box']) > LINE_BOX_TOL_PX:
            unlike.append(b)
    r.check(bool(v['boxes']) and not unlike, f'the type: the head\'s lines stand on P-LAY\'s line box for their size, as the engine lays it out ({LINE_BOX_TOL_PX:.4f} px at the layout size)', unlike[:6])
    lines = v['typed']
    marked = [x for x in lines if x['text'].startswith('#') and x['char'] == 0]
    unlike_body = [x for x in lines if x['tag'] != 'p' or abs(x['font'] - v['body']) > 1e-6 or x['weight'] != '400']
    r.check(bool(marked) and not v['headings'] and not unlike_body,
            'the type: no element of the first edition\'s article is a heading — every typed line a `p` at the body\'s size and weight, those its bytes open with "#" among them (issue #17\'s design decision: "`##` at the start of a line is text, set in body type like the rest")',
            {'headings': v['headings'][:6], 'opening_with_hash': [x['text'][:24] for x in marked[:6]], 'unlike_body': unlike_body[:6], 'body_px': v['body']})
    kept = [x for x in lines if not (x['white'] == 'pre-wrap' or (x['collapse'] == 'preserve' and x['wrap'] == 'wrap'))]
    r.check(bool(lines) and not kept, 'the type: every typed line of the first edition keeps its white space, set `pre-wrap` — every character in its place, spaces and indentation included (issue #17\'s design decision)',
            {'typed': len(lines), 'collapsing': kept[:6]})
    # a typed line's own block — its bytes open with a character, never with the newlines a run may lead with — and whether it
    # opens a typed line, by the bytes delivered
    own = [x for x in lines if x['text'] and not x['text'].startswith('\n')]
    opens = lambda x: x['pos'] == 1 or x['before'] == '\n'
    astray = [dict(x, opens=opens(x)) for x in own if abs(x['indent'] - (x['font'] if opens(x) and x['char'] == 0 else 0)) > 1e-6]
    indented = [x for x in own if opens(x) and x['char'] == 0]
    r.check(bool(indented) and not astray,
            'the type: a typed line stands on a one-em indent where it opens a typed line — the first position, or the byte before it a newline — in the part that starts at its first character, and on none elsewhere (issue #17\'s design decision: "Every typed line starts with a one-em indent")',
            {'indented': len(indented), 'astray': astray[:6]})
    off_grid = [x for x in v['steps'] if x['px'] < v['line_box'] - LINE_BOX_TOL_PX or abs(x['px'] / v['line_box'] - round(x['px'] / v['line_box'])) * v['line_box'] > LINE_BOX_TOL_PX]
    r.check(bool(v['steps']) and not off_grid,
            f'the type: each block of the first edition a whole count of body line boxes below the block before it in its part — an empty line typed between them one line box, no other room — so a column keeps its grid of lines ({LINE_BOX_TOL_PX:.4f} px at the layout size; issue #17\'s design decision: "No space is added between blocks")',
            {'steps': len(v['steps']), 'line_box': v['line_box'], 'off_grid': off_grid[:6]})
    shipped = v['advance'] is not None and v['ident_advance'] is not None and abs(v['advance'] - SHIPPED_ADVANCE['reading']) <= ADVANCE_TOL and abs(v['ident_advance'] - SHIPPED_ADVANCE['ident']) <= ADVANCE_TOL
    r.check(v['faces'] == FACE_FAMILIES and shipped, f'the type: each voice stands in its face — a typed line, the document\'s words, in Charter; the head\'s byline, the client\'s, in the system face; the head\'s address in Atkinson Hyperlegible Mono — the reading and identifier faces set as shipped, their rendered advances their files\' own, {ADVANCE_TOL} em either way (issue #16\'s design decision)',
            {'faces': v['faces'], 'want': FACE_FAMILIES, 'advance': {'reading': v['advance'], 'ident': v['ident_advance'], 'shipped': SHIPPED_ADVANCE}})
    boot = ctx.js('window.__skep.boot') or {}
    typed = boot.get('type') or {}
    at_boot, at_frame = dict(typed.get('faces') or []), dict(boot.get('firstFrame') or [])
    in_set = {(f['family'], f['style'], f['weight']) for f in v['set'] if f['status'] == 'loaded'}
    unloaded = {'set': sorted(SHIPPED_SET - in_set), 'now': [f for f, ok in v['loaded'] if not ok], 'boot': [f for f in SHIPPED_FACES if not at_boot.get(f)], 'first_frame': [f for f in SHIPPED_FACES if not at_frame.get(f)]}
    r.check(len(v['loaded']) == len(SHIPPED_FACES) and not any(unloaded.values()),
            'the type: every face the page ships — Charter in its four styles, Atkinson Hyperlegible Mono — stands in the platform\'s font set, loaded, and was loaded as boot set the type and as the first frame laid anything out (issue #16\'s design decision: the first layout waits for the faces)',
            dict(unloaded, faces=sorted(in_set)))
    r.check(v['advance'] is not None and abs(v['advance'] - v['page_advance']) <= ADVANCE_TOL and typed.get('advance') == v['page_advance'],
            f'the type: the advance the page set — the reading face\'s average, as boot measured it — is the one the case probes in a typed line as rendered, {ADVANCE_TOL} em either way',
            {'probed': v['advance'], 'page': v['page_advance'], 'boot': typed.get('advance')})
    r.check(typed.get('root') == '16px' and typed.get('readingPx') == READING_PX,
            f'the type: at the root\'s 16 px the reading size is {READING_PX} px — 1.0625 of the root, as the reader\'s own settings render it',
            {'root': typed.get('root'), 'reading_px': typed.get('readingPx')})
    starts = starts_view(ctx) or []
    astray = [x for x in starts if not starts_on_line(x)]
    r.check(bool(starts) and not astray,
            f'the type: every line a typed line of the first edition sets past its first, as T-LAYER reads it, begins where its first character stands — the character at the position it opens at on the line, the last one before it, spaces apart, on the line before it, {ANCHOR_TOL_PX} px either way',
            {'lines': len(starts), 'astray': astray[:6]})
    return {'elements': len(v['sized']), 'boxes': [[b['el'], round(b['height'], 4), b['line_box']] for b in v['boxes']], 'typed': len(lines), 'indented': len(indented), 'steps': len(v['steps']),
            'faces': v['faces'], 'advance': {'reading': v['advance'], 'ident': v['ident_advance']}, 'reading_px': typed.get('readingPx'), 'line_starts': len(starts)}


def scene_level(ctx):
    """the scene as it stands: its runs, the two ends it set level, and each end's passage in its pane — its first line
    on screen, its first characters, the pane's visible rect"""
    return ctx.js('''(() => { const S = window.__skep.scene, p = S.pairs(); if (!p) return null;
      return {pairs: p.pairs, level: p.level, a: p.level.a != null ? S.at('a', p.level.a) : null, b: p.level.b != null ? S.at('b', p.level.b) : null}; })()''')


def level_holds(r, name, v):
    """the two ends set level: their first lines at one height, inside both panes, holding the same material"""
    a, b = (v or {}).get('a'), (v or {}).get('b')
    la, lb = a and a['line'], b and b['line']
    level = bool(la and lb) and abs(la['y'] - lb['y']) <= LEVEL_TOL_PX and abs(la['y'] + la['h'] - (lb['y'] + lb['h'])) <= LEVEL_TOL_PX and inside(la, a['pane']) and inside(lb, b['pane'])
    r.check(level, f'{name}: the two ends stand level — the matched passage\'s first line at one height in both panes, its top and its bottom within {LEVEL_TOL_PX} px, inside both panes',
            {'level': v and v['level'], 'a': la, 'b': lb, 'pane_a': a and a['pane'], 'pane_b': b and b['pane']})
    same = bool(a and b and a['text'] and b['text']) and a['text'][:24] == b['text'][:24]
    r.check(same, f'{name}: the lines set level hold the same material — the passage\'s first characters alike in both panes', {'a': a and a['text'], 'b': b and b['text']})


def band_off(t, side):
    """what is off at a band's end on one side, read against its run as the gate reads it apart from the scene's own
    measure (`scene.ties`' `runA`, `runB`: the line boxes of its run's first and last glyphs, of the last glyph before it
    and the first after it, and the line height): held at the pane's visible top where its extent passes it — its run's
    first line then reaching above it — else its top inside the view, no lower than its run's first line's middle and
    reaching into no line before its run; its bottom likewise (issue #331's design decision: "On each pane's facing edge a
    band covers all of its run's lines"); None where nothing is, and where its run sets no glyph the gate reads — an
    item's alone, which `glyphs_unread` counts"""
    end, run, pane = t[side], t.get('run' + side.upper()), t.get('pane' + side.upper())
    if run is None or pane is None or 'top' not in end:
        return {'side': side, 'pos': end.get('pos'), 'off': ['no extent drawn, or none read'], 'end': end, 'run': run}
    if not run['first'] or not run['last']:
        return None
    first, last, prev, nxt, lh = run['first'], run['last'], run['prev'], run['next'], run['lh']
    top, bottom, bad = pane['y'], pane['y'] + pane['h'], []
    # where the band's extent stands, held inside the visible height as the scene holds it
    hold = lambda y: max(top, min(bottom, y))
    if end['above']:
        if abs(end['top'] - top) > TIE_TOL_PX or first['mid'] > top + lh:
            bad.append('held at the visible top')
    elif end['top'] < top - TIE_TOL_PX or end['top'] > hold(first['mid']) + TIE_TOL_PX or (prev and end['top'] < hold(min(prev['bottom'], first['top'])) - TIE_TOL_PX):
        bad.append('its top at its run\'s first line')
    if end['below']:
        if abs(end['bottom'] - bottom) > TIE_TOL_PX or last['mid'] < bottom - lh:
            bad.append('held at the visible bottom')
    elif end['bottom'] > bottom + TIE_TOL_PX or end['bottom'] < hold(last['mid']) - TIE_TOL_PX or (nxt and end['bottom'] > hold(max(nxt['top'], last['bottom'])) + TIE_TOL_PX):
        bad.append('its bottom at its run\'s last line')
    return {'side': side, 'pos': end['pos'], 'width': end['width'], 'off': bad, 'top': end['top'], 'bottom': end['bottom'], 'first': first, 'last': last, 'prev': prev, 'next': nxt, 'pane': pane} if bad else None


def bands_meet(bands):
    """what is off where two bands consecutive on a side — their runs holding no byte of each other there — meet or
    part, read against their runs as the gate reads them, where neither is held at the pane's edge between them: a line
    both runs stand on divided at its middle; runs adjoining there meeting; a whole line of glyphs between their runs
    standing unbanded, as far as the visible height holds it (issue #331's design decision: "two bands that share a line divide it at its middle. A difference
    that takes a whole line on one side then shows on that side as an unbanded stretch"); and the junctions read, by kind"""
    off, seen = [], {'shared': 0, 'adjoining': 0, 'apart': 0}
    for side in ('a', 'b'):
        key = 'run' + side.upper()
        seq = sorted((t for t in bands if t.get(key) and t[key]['first'] and t[key]['last'] and 'top' in t[side]), key=lambda t: (t[side]['pos'], t[side]['width']))
        for p, q in zip(seq, seq[1:]):
            pe, qe, pr, qr = p[side], q[side], p[key], q[key]
            if qe['pos'] < pe['pos'] + pe['width'] or pe['below'] or qe['above']:
                continue
            lh = pr['lh']
            if abs(pr['last']['mid'] - qr['first']['mid']) < lh / 2:
                seen['shared'] += 1
                mid = (pr['last']['mid'] + qr['first']['mid']) / 2
                if abs(pe['bottom'] - mid) > TIE_TOL_PX or abs(qe['top'] - mid) > TIE_TOL_PX:
                    off.append({'side': side, 'junction': 'a shared line', 'at': [pe['pos'], qe['pos']], 'bottom': pe['bottom'], 'top': qe['top'], 'mid': mid})
            elif qe['pos'] == pe['pos'] + pe['width']:
                seen['adjoining'] += 1
                if abs(pe['bottom'] - qe['top']) > TIE_TOL_PX:
                    off.append({'side': side, 'junction': 'adjoining runs', 'at': [pe['pos'], qe['pos']], 'bottom': pe['bottom'], 'top': qe['top']})
            else:
                line, pane = pr['next'], p['pane' + side.upper()]
                hold = lambda y: max(pane['y'], min(pane['y'] + pane['h'], y))
                if line and line['top'] >= pr['last']['bottom'] - TIE_TOL_PX and line['bottom'] <= qr['first']['top'] + TIE_TOL_PX:
                    seen['apart'] += 1
                    if pe['bottom'] > hold(line['top']) + TIE_TOL_PX or qe['top'] < hold(line['bottom']) - TIE_TOL_PX:
                        off.append({'side': side, 'junction': 'a whole line between', 'at': [pe['pos'], qe['pos']], 'bottom': pe['bottom'], 'top': qe['top'], 'line': line})
    return off, seen


def ties_hold(r, name, ties, in_view, band=True):
    """every band drawn between the panes stands at its extent on each pane's facing edge (`band_off`, `bands_meet`;
    issue #331's design decision), and every line leaves each pane at its passage's own first line, or, where that line
    has left the pane, at the pane's edge on the side it left by; an end naming its pane's document whole stands at that
    pane's facing edge, level with the line's other end held inside the pane's visible height, never clipped (issue #59),
    and stands in view; `in_view` the ends that must stand in view, a band's where any of its extent does; `band` the
    shared identity is drawn as a band among them"""
    if band:
        r.check(any(t['kind'] == 'band' for t in ties), f'{name}: the shared identity is drawn as a band', [t['kind'] for t in ties])
    off, ends = [], 0
    bands = [t for t in ties if t['kind'] == 'band']
    for t in bands:
        for side in ('a', 'b'):
            bad = band_off(t, side)
            if bad:
                off.append(dict(bad, kind='band'))
            elif t[side]['bottom'] > t[side]['top'] or not (t[side]['above'] or t[side]['below']):
                ends += 1
    met, junctions = bands_meet(bands)
    off.extend(dict(m, kind='band') for m in met)
    # the ends whose run sets no glyph the gate reads — an item's alone — held to nothing here, and counted
    unread = sum(1 for t in bands for s in ('A', 'B') if t.get('run' + s) and not (t['run' + s]['first'] and t['run' + s]['last']))
    for t in ties:
        if t['kind'] == 'band':
            continue
        for side, line, pane, face, other in (('a', t['lineA'], t['paneA'], t.get('faceA'), 'b'), ('b', t['lineB'], t['paneB'], t.get('faceB'), 'a')):
            end = t[side]
            if end.get('whole'):
                there = t[other]
                level = None if pane is None else pane['y'] if there.get('whole') else min(max(there['y'], pane['y']), pane['y'] + pane['h'])
                if pane is None or face is None or end['clipped'] or abs(end['x'] - face) > TIE_TOL_PX or abs(end['y'] - level) > TIE_TOL_PX:
                    off.append({'kind': t['kind'], 'link': t['link'], 'side': side, 'whole': True, 'x': end['x'], 'y': end['y'], 'face': face, 'level': level, 'clipped': end['clipped'], 'pane': pane})
                else:
                    ends += 1
                continue
            if line is None or pane is None:
                off.append({'kind': t['kind'], 'link': t['link'], 'side': side, 'pos': end['pos'], 'line': line})
                continue
            mid, top, bottom = line['y'] + line['h'] / 2, pane['y'], pane['y'] + pane['h']
            if end['clipped']:
                edge = top if mid < top else bottom if mid > bottom else None
                if edge is None or abs(end['y'] - edge) > TIE_TOL_PX:
                    off.append({'kind': t['kind'], 'link': t['link'], 'side': side, 'pos': end['pos'], 'y': end['y'], 'clipped': True, 'line': line, 'pane': pane})
                continue
            ends += 1
            if not (line['y'] - TIE_TOL_PX <= end['y'] <= line['y'] + line['h'] + TIE_TOL_PX):
                off.append({'kind': t['kind'], 'link': t['link'], 'side': side, 'pos': end['pos'], 'y': end['y'], 'line': line})
    r.check(ends >= in_view and not off, f'{name}: every band stands at its extent — from its run\'s first line to its last, a line it shares with the band beside it divided at its middle, a whole line between their runs unbanded, held at the pane\'s edge where it passes it — and every line leaves its pane at its passage\'s own first line, {TIE_TOL_PX} px either way, or at the pane\'s edge where that line has left the pane, a whole document\'s end at its pane\'s facing edge level with the line\'s other end — {in_view} end(s) or more in view',
            {'ends_in_view': ends, 'off': off[:6]})
    return {'ties': len(ties), 'bands': len(bands), 'ends_in_view': ends, 'off': len(off), 'junctions': junctions, 'glyphs_unread': unread}


def every_run_banded(r, name, v, ties):
    """every run of shared identity the scene holds (`scene.pairs`) drawn as a band, none dropped, however many (issue
    #331's design decision: "every difference is drawn, as a gap or a stroke depending on its height, and none is
    dropped"); the runs and bands counted"""
    runs = sorted((p['u1'], p['u2'], p['width']) for p in ((v or {}).get('pairs') or []))
    bands = sorted((t['a']['pos'], t['b']['pos'], t['a']['width']) for t in ties if t['kind'] == 'band')
    r.check(bool(runs) and bands == runs, f'{name}: every run of shared identity is drawn as a band, none dropped',
            {'runs': len(runs), 'bands': len(bands), 'missing': [x for x in runs if x not in bands][:6]})
    return {'runs': len(runs), 'bands': len(bands)}


def stroke_at_junction(ctx, pairs):
    """the reading scene's panes scrolled, junction by junction, to where two runs consecutive in both documents part —
    the earlier run's last byte's line 100 px below each pane's visible top — until the draw stands a stroke; the
    strokes then drawn, and the junctions tried"""
    by_a = sorted(pairs, key=lambda p: (p['u1'], p['u2']))
    by_b = sorted(pairs, key=lambda p: (p['u2'], p['u1']))
    after_b = {(p['u1'], p['u2']): (q['u1'], q['u2']) for p, q in zip(by_b, by_b[1:])}
    tried = 0
    for p, q in zip(by_a, by_a[1:]):
        if after_b.get((p['u1'], p['u2'])) != (q['u1'], q['u2']):
            continue
        tried += 1
        for side, pos in (('a', p['u1'] + p['width'] - 1), ('b', p['u2'] + p['width'] - 1)):
            at = ctx.js('window.__skep.scene.at(%s, %d, 1)' % (json.dumps(side), pos))
            if at and at['line']:
                ctx.js('document.getElementById(%s).scrollTop += %f' % (json.dumps('scene' + side.upper()), at['line']['y'] - at['pane']['y'] - 100))
        ctx.frames(2)
        strokes = ctx.js('window.__skep.scene.strokes()')
        if strokes:
            return strokes, tried
    return [], tried


def stroke_holds(ctx, r, name, s, ties, panes):
    """one stroke as the last draw drew it (issue #331's design decision): at the edge the band before it and the band
    after it share on each side, as `scene.ties` draws them; drawn in the gutter's half beside each pane holding
    characters between them, as the gate reads those characters (`scene.text`); its button centred on its point in the
    gutter, under the pointer there, named by each change's characters on each side in ST's words — unread where a change
    touches an item, whose characters the DOM does not give as the item rule names them — its count where it stands for two
    changes or more; its figures"""
    bands = [t for t in ties if t['kind'] == 'band']
    first, last = s['changes'][0], s['changes'][-1]
    before = next((t for t in bands if t['a']['pos'] + t['a']['width'] == first['a']['from'] and t['b']['pos'] + t['b']['width'] == first['b']['from']), None)
    after = next((t for t in bands if t['a']['pos'] == last['a']['to'] and t['b']['pos'] == last['b']['to']), None)
    edge = bool(before and after) and all(abs(s[x]['y'] - before[x]['bottom']) <= TIE_TOL_PX and abs(s[x]['y'] - after[x]['top']) <= TIE_TOL_PX for x in ('a', 'b'))
    r.check(edge, f'{name}: the stroke stands at the edge the band before it and the band after it share on both sides',
            {'stroke': {k: s[k] for k in ('key', 'a', 'b')}, 'before': before and [before['a'], before['b']], 'after': after and [after['a'], after['b']]})
    texts = [{x: (ctx.js('window.__skep.scene.text(%s, %d, %d)' % (json.dumps(x), c[x]['from'], c[x]['to'])) or '') if c[x]['to'] > c[x]['from'] else '' for x in ('a', 'b')} for c in s['changes']]
    halves = [any(t['a'] for t in texts), any(t['b'] for t in texts)]
    r.check([s['halfA'], s['halfB']] == halves, f'{name}: the stroke drawn in the gutter\'s half beside each pane holding characters between the runs, and in no other',
            {'halves': [s['halfA'], s['halfB']], 'texts': texts})
    rect, at = s['rect'], s['at']
    hit = ctx.js('''((id, x, y) => { const e = document.elementFromPoint(x, y); return !!e && !!e.closest && !!e.closest('[id="' + id + '"]'); })(%s, %f, %f)''' % (json.dumps(s['id'] or ''), at['x'], at['y']))
    placed = bool(rect) and abs(rect['x'] + rect['w'] / 2 - at['x']) <= 1 and abs(rect['y'] + rect['h'] / 2 - at['y']) <= 1 and s['a']['x'] <= at['x'] <= s['b']['x'] and hit
    r.check(placed and s['count'] == ('' if len(s['changes']) == 1 else str(len(s['changes']))),
            f'{name}: the stroke\'s button stands centred on it in the gutter, under the pointer there, its count where it stands for two changes or more',
            {'rect': rect, 'at': at, 'hit': hit, 'count': s['count'], 'changes': len(s['changes'])})
    items = [b for x in ('a', 'b') for b in (panes.get(x) or {}).get('blocks', []) for c in s['changes'] if b['kind'] != 'para' and b['pos'] < c[x]['to'] and c[x]['from'] < b['pos'] + b['width']]
    want = None if items else ctx.js('''(async (texts, A, B) => { const {t} = await import('./strings.js');
      const side = (x) => (x ? t('L.scene.change.text', {text: x}) : t('L.scene.change.none'));
      const changes = texts.map((c) => t('L.scene.change', {a: A, one: side(c.a), b: B, other: side(c.b)})).join(' · ');
      return t('L.scene.stroke.name', {count: t(texts.length > 1 ? 'L.scene.stroke' : 'L.scene.stroke.1', {n: texts.length}), changes}); })(%s, %s, %s)''' % (json.dumps(texts), json.dumps(panes['a']['shows']), json.dumps(panes['b']['shows'])))
    if want is not None:
        r.check(s['name'] == want, f'{name}: the stroke\'s button is named by each change\'s characters on each side, as the gate reads them, in ST\'s words', {'name': s['name'], 'want': want})
    else:
        r.note(f'{name}: the stroke\'s name against the characters the DOM gives: unmeasured — a change touches an item (FP-18)')
    return {'key': s['key'], 'changes': len(s['changes']), 'halves': halves, 'texts': texts}


def scene_strokes_hold(ctx, r):
    """THE STROKES BETWEEN BANDS (issue #331's design decision: "When two runs that are consecutive in both documents meet
    on both sides, the difference has no drawn height. Draw their shared edge as a stroke in the half of the gutter beside
    each document that holds characters between them"): the scene on VERSIONED's first member beside its latest, at its
    plain address — every band at its extent (`ties_hold`) and every run a band (`every_run_banded`); each pane scrolled
    to where two runs consecutive in both documents part, until a stroke stands in view (`stroke_at_junction`), the
    stroke holding (`stroke_holds`); a person's click on its button showing its list at it, the focus left on the
    button, and Esc closing the list there; Enter at it showing the list with the focus on its first row, and Esc
    returning the focus to the button (FP-20); the list leaving with the scene by Mod+0 and reopened with it by Mod+[,
    the focus on its first row (issue #264; FP-36). Unmeasured where no stroke stands (FP-18); the measure's own figures,
    the runs it read and its time on this machine. Its figures"""
    first = VERSIONED + '.1'
    name = f'the scene on {first} beside {VERSIONED}'
    ctx.js('window.__skep.scene.open(%s, %s)' % (json.dumps(first), json.dumps(VERSIONED)))
    wait_for(ctx, 'window.__skep.scene.isOpen()')
    v = scene_level(ctx)
    ties = ctx.js('window.__skep.scene.ties()')
    figures = {'runs': every_run_banded(r, name, v, ties), 'ties': ties_hold(r, name, ties, 0), 'measured': ctx.js('window.__skep.scene.measured()')}
    strokes, figures['junctions'] = stroke_at_junction(ctx, (v or {}).get('pairs') or [])
    if not strokes:
        r.note(f'{name}: a stroke between two bands: unmeasured — no two runs consecutive in both documents meet on both sides here, in view at any junction ({figures["junctions"]} tried) (FP-18)')
        ctx.js('window.__skep.scene.close()')
        ctx.frames(2)
        return figures
    ties = ctx.js('window.__skep.scene.ties()')
    figures['ties_at_stroke'] = ties_hold(r, f'{name}, scrolled to a stroke', ties, 0)
    panes = ctx.js('window.__skep.scene.panes()') or {}
    figures['strokes'] = [stroke_holds(ctx, r, name, s, ties, panes) for s in strokes]
    s = strokes[0]
    sel = '[id="%s"]' % s['id']
    hit = click_on(ctx, sel)
    ctx.frames(2)
    shown = ctx.js('({overlay: window.__skep.overlay(), focus: document.activeElement && document.activeElement.id, rows: [...document.querySelectorAll("#overlay .changes li")].length})')
    r.check(bool(hit) and hit['hits'] and shown['overlay']['id'] == 'stroke:' + s['key'] and shown['rows'] == len(s['changes']) and shown['focus'] == s['id'],
            f'{name}: a person\'s click on the stroke shows its list at it, a row for each change, the focus left on the stroke', dict(shown, hit=hit))
    ctx.drv.key('Escape')
    ctx.frames(2)
    closed = ctx.js('({overlay: window.__skep.overlay().id, scene: window.__skep.scene.isOpen(), focus: document.activeElement && document.activeElement.id})')
    r.check(closed == {'overlay': None, 'scene': True, 'focus': s['id']}, f'{name}: Esc closes the list, the scene standing and the focus on the stroke', closed)
    ctx.drv.key('Enter')
    ctx.frames(2)
    keyed = ctx.js('({overlay: window.__skep.overlay().id, row: !!document.activeElement && !!document.activeElement.closest && !!document.activeElement.closest("#overlay .changes li")})')
    ctx.drv.key('Escape')
    ctx.frames(2)
    back = ctx.js('document.activeElement && document.activeElement.id')
    r.check(keyed == {'overlay': 'stroke:' + s['key'], 'row': True} and back == s['id'],
            f'{name}: Enter at the stroke shows its list with the focus on its first row, and Esc returns the focus to the stroke (FP-20)', dict(keyed, back=back))
    # the list leaves and returns with the scene (issue #264's design decision: "Back and Forward reopen them as left, the
    # scene with its panes' versions"): Enter at the stroke shows it, the focus on its first row; Mod+0 leaves the scene,
    # and Mod+[ reopens it with the list over the stroke again, the focus on its first row (FP-36, FP-20)
    ctx.drv.key('Enter')
    ctx.frames(2)
    ctx.drv.key('0', code='Digit0', mods=('Meta',))
    ctx.settle()
    ctx.frames(2)
    away = ctx.js('({scene: window.__skep.scene.isOpen(), overlay: window.__skep.overlay().id})')
    ctx.drv.key('[', code='BracketLeft', mods=('Meta',))
    ctx.settle()
    wait_for(ctx, '(window.__skep.overlay().id || "") === %s' % json.dumps('stroke:' + s['key']))
    ctx.frames(2)
    again = ctx.js('''({scene: window.__skep.scene.isOpen(), overlay: window.__skep.overlay().id, rows: [...document.querySelectorAll("#overlay .changes li")].length,
      row: !!document.activeElement && !!document.activeElement.closest && !!document.activeElement.closest("#overlay .changes li")})''')
    r.check(away == {'scene': False, 'overlay': None} and again == {'scene': True, 'overlay': 'stroke:' + s['key'], 'rows': len(s['changes']), 'row': True},
            f'{name}: the stroke\'s list leaves with the scene, and Mod+[ reopens the scene with the list over the stroke again, a row for each change, the focus on its first row (issue #264; FP-36)',
            {'away': away, 'again': again})
    ctx.drv.key('Escape')
    ctx.frames(2)
    ctx.js('window.__skep.scene.close()')
    ctx.frames(2)
    return figures


# the board busy, as the bridge hands a refusal up: one a retry may tell past
BUSY = {'kind': 'refused', 'name': 'busy', 'status': 503, 'code': 'busy', 'detail': None, 'op': 'compare', 'body': None, 'site': {}}


def without(pairs, side, lo, hi):
    """`compare`'s pairs as the board answers them, the positions [lo, hi) of one side's text (`u1` or `u2`) taken out of
    every run — a run crossing them cut in two — so the answer holds none of those bytes"""
    other, out = ('u2' if side == 'u1' else 'u1'), []
    for q in pairs:
        if q[side].get('subspace') != '1':
            out.append(q)
            continue
        at, w = int(q[side]['ordinal']), int(q['width'])
        for a, b in ((at, min(at + w, lo)), (max(at, hi), at + w)):
            if b > a:
                out.append(dict(q, width=str(b - a), **{side: dict(q[side], ordinal=str(a)), other: dict(q[other], ordinal=str(int(q[other]['ordinal']) + a - at))}))
    return out


def cutting(*cuts):
    """the provider's `compare` answer cut, for the driver's `answer_op`: its pairs without the positions each `(side, lo, hi)`
    names"""
    def cut(body):
        res = dict(body.get('result') or {})
        for side, lo, hi in cuts:
            res['pairs'] = without(res.get('pairs') or [], side, lo, hi)
        return dict(body, result=res)
    return cut


def where_focus(ctx):
    """where the platform's focus stands, the ARIA mirror beside it: the focused element's id — an act of a pane's corner by
    the corner's id and the act's class — whether the mirror is out of the page's order and holds the focus, and its current
    item"""
    return ctx.js('''(() => { const e = document.activeElement, m = document.getElementById('mirror'), c = e && e.closest ? e.closest('.pane > .corner') : null;
      return {at: e ? (c && e !== c ? c.id + ': ' + e.className.split(' ')[0] : e.id || e.tagName.toLowerCase()) : null, inert: !!m.inert, holds: !!e && m.contains(e), item: window.__skep.mirror.index()}; })()''')


# a reading scene's stop the selector names focused, as Tab lands on it: a pane itself, or a pane's corner's stop — its first
# act where it holds acts, else itself; the stop's name as `where_focus` gives it, null where the stop took no focus
FOCUS_STOP = '''((sel) => { const e = document.querySelector(sel); if (!e) return null;
  const s = e.matches('.corner') ? ([...e.querySelectorAll('button')].find((b) => b.getAttribute('tabindex') === '0') || e) : e;
  s.focus(); return document.activeElement === s ? (s === e ? e.id : e.id + ': ' + s.className.split(' ')[0]) : null; })(%s)'''


def focused_ax(ctx):
    """the node the AX tree holds the focus on, past the document's own: its role and its name; None where CDP does not answer"""
    ax = ctx.drv.ax_tree()
    if 'error' in ax:
        return None
    on = [n for n in ax.get('nodes', []) if (n.get('role') or {}).get('value') != 'RootWebArea'
          and any(p['name'] == 'focused' and (p.get('value') or {}).get('value') for p in n.get('properties', []))]
    n = on[-1] if on else {}
    return {'role': (n.get('role') or {}).get('value'), 'name': (n.get('name') or {}).get('value')}


def back_to(ctx):
    """the reading scene left by WHOLE BOARD and returned to by Back, its `compare` held at its answer (the driver's
    `hold_op`): the stop the reader returned to as it stands"""
    ctx.drv.hold_op('compare')
    ctx.drv.key('0', code='Digit0', mods=('Meta',))
    ctx.settle()
    ctx.frames(2)
    ctx.drv.key('[', code='BracketLeft', mods=('Meta',))
    ctx.settle()
    ctx.frames(3)
    return ctx.js('window.__skep.scene.returned()')


def answered_now(ctx):
    """the stop the reader returned to once the page took the held `compare`'s answer; None where the scene let it go"""
    wait_for(ctx, '(() => { const r = window.__skep.scene.returned(); return !r || !!r.answer; })()')
    return ctx.js('window.__skep.scene.returned()')


def stop_returns(ctx, r, name, sel, kind, cuts, made):
    """THE RETURNS to a stop only the panes' `compare` draws (see `scene_return_holds`), from the stop `sel` names: the scene
    left by WHOLE BOARD and returned to by Back once for each answer — whole, part, none, refused, and whole with the reader
    moved on first by Tab — the focus, the mirror and the AX tree held before the answer and after it; then Enter made
    before the answer and abandoned by Esc, and Enter made before a whole answer, which makes it (`made`, a page expression
    whose value the act changes). Its figures"""
    seen = {}
    D = ctx.js('window.__skep.scene.panes().b.shows')
    tr = lambda sid, vals: ctx.js('(async () => (await import("./strings.js")).t(%s, %s))()' % (json.dumps(sid), json.dumps(vals)))
    kind_id, kind_vals = ('L.scene.shared.1', {'D': D}) if kind == 'shared' else ('L.scene.stroke.kind', {})
    kind_words = tr(kind_id, kind_vals)
    # a name the answer completes: the stop's kind and what the answer told, each a sentence (style S1, S2)
    told_as = lambda said: ctx.js('(async (id, v, said) => { const S = await import("./strings.js"); return S.sentences(S.sentence(id, v), said); })(%s, %s, %s)'
                                  % (json.dumps(kind_id), json.dumps(kind_vals), json.dumps(said)))
    focus = 'document.querySelector(%s).focus()' % json.dumps(sel)
    ctx.js(focus)
    ctx.frames(1)
    for outcome in ('whole', 'part', 'none', 'refused', 'moved on first'):
        ret, before, ax = back_to(ctx), where_focus(ctx), None
        ax = focused_ax(ctx)
        r.check(bool(ret) and ret['kind'] == kind and ret['answer'] is None and ret['shown'] and ret['reading'] and before['at'] == ret['id']
                and before['inert'] and not before['holds'] and (ret['name'] or '').startswith(kind_words),
                f'{name}, returned to ({outcome}): before its `compare` answers, the stop stands with the landing and holds the focus — the mirror out of the page\'s order, holding none — named for its kind, its count being read',
                {'returned': ret, 'focus': before})
        if ax is not None:
            r.check(bool(ret) and ax['name'] == ret['name'], f'{name}, returned to ({outcome}): the AX tree\'s focused node is the stop, named for its kind with its count being read', {'ax': ax, 'name': ret and ret['name']})
        tabbed = None
        if outcome == 'moved on first':
            ctx.drv.key('Tab')
            ctx.frames(2)
            tabbed = where_focus(ctx)
        how = {'whole': 'whole', 'moved on first': 'whole', 'part': 'cut', 'none': 'cut', 'refused': 'refused'}[outcome]
        released = ctx.drv.answer_op(how, cut=cuts.get(outcome), refusal=BUSY)
        after = answered_now(ctx)
        ctx.frames(2)
        now, ax2, face = where_focus(ctx), focused_ax(ctx), ctx.overlay_shown()
        o = ctx.js('window.__skep.overlay().id')
        a = (after or {}).get('answer') or {}
        held = now['inert'] and not now['holds'] and now['item'] == before['item']
        if outcome == 'moved on first':
            r.check(released and bool(tabbed) and tabbed['at'] != before['at'] and now['at'] == tabbed['at'] and o is None and held,
                    f'{name}, the reader moved on first: the answer moves nothing — the focus where Tab put it, no face, the mirror as the return left it', {'tabbed': tabbed, 'now': now, 'overlay': o, 'returned': after})
        else:
            want = {'whole': ('all',), 'part': ('part', 'pieces'), 'none': ('none',), 'refused': ('unknown',)}[outcome]
            words = told_as(a.get('words') or '') if outcome != 'whole' else None
            # at its site the face of what the answer told: the dead end's own words, else the line's
            site = ctx.js('(async (d) => (await import("./beams/held.js")).floatingOf(d))(%s)' % json.dumps(D)) if outcome == 'none' else (a.get('words') or '')
            face_ok = o is None if outcome == 'whole' else (o == ('face:floating' if outcome == 'none' else 'face:held') and bool(site) and site in face['text'] and face['acts'] == (1 if outcome == 'refused' else 0))
            r.check(released and bool(after) and a.get('holds') in want and now['at'] == before['at'] and held and not after['reading'] and (outcome == 'whole' or after['name'] == words) and face_ok,
                    f'{name}, answered {outcome}: the focus kept on the stop, the mirror as the return left it, its count no longer read'
                    + ('' if outcome == 'whole' else ' — it stays, saying so in FP-21\'s words in its name and at its site' + (', "try again" offered' if outcome == 'refused' else '')),
                    {'returned': after, 'focus': now, 'overlay': o, 'face': face, 'want': words})
            if ax2 is not None and after:
                r.check(ax2['name'] == after['name'], f'{name}, answered {outcome}: the AX tree\'s focused node is still the stop, named as it is now', {'ax': ax2, 'name': after['name']})
        seen[outcome] = {'answer': a, 'focus': now['at'], 'overlay': o}
        if o:
            ctx.js('window.__skep.dismiss()')
        ctx.js(focus)
        ctx.frames(1)
    # Enter made before the answer, then Esc: abandoned, and the whole answer then moves nothing
    back_to(ctx)
    ctx.drv.key('Enter')
    ctx.frames(2)
    waits = ctx.js('({o: window.__skep.overlay().id, r: window.__skep.scene.returned()})')
    ctx.drv.key('Escape')
    ctx.frames(2)
    gone = ctx.js('({o: window.__skep.overlay().id, r: window.__skep.scene.returned(), open: window.__skep.scene.isOpen()})')
    was = ctx.js(made)
    ctx.drv.answer_op('whole')
    after = answered_now(ctx)
    ctx.frames(2)
    r.check((waits['o'] or '').startswith('reaching:') and bool(waits['r']) and waits['r']['waiting'] and gone['o'] is None and gone['open'] and bool(gone['r']) and not gone['r']['waiting']
            and ctx.js(made) == was and bool(after) and (after.get('answer') or {}).get('holds') == 'all' and where_focus(ctx)['at'] == after['id'],
            f'{name}: Enter made while its `compare` is read waits, its reaching face at the stop; Esc dismisses the face and abandons it, the scene standing; the whole answer then moves nothing, the focus on the stop',
            {'waiting': waits, 'after_esc': gone, 'answered': after, 'made': [was, ctx.js(made)]})
    # Enter made before a whole answer: made as it answers
    ctx.js(focus)
    back_to(ctx)
    ctx.drv.key('Enter')
    ctx.frames(2)
    was = ctx.js(made)
    ctx.drv.answer_op('whole')
    answered_now(ctx)
    ctx.frames(3)
    o = ctx.js('window.__skep.overlay().id')
    r.check(ctx.js(made) != was and not (o or '').startswith('reaching:'), f'{name}: Enter made while its `compare` is read is made as the whole answer comes, its reaching face gone', {'made': [was, ctx.js(made)], 'overlay': o})
    seen['enter'] = {'made': [was, ctx.js(made)]}
    if o:
        ctx.js('window.__skep.dismiss()')
    return seen


def scene_return_holds(ctx, r):
    """A STOP ONLY THE PANES' `compare` DRAWS, LEFT FROM AND RETURNED TO (FP-20, FP-21, FP-25, FP-34): a whole-document scene
    — the far end naming pane B's document whole, which shows before its `compare` answers — left from the stop at a band's
    clipped end, and from a stroke's button, by WHOLE BOARD, and returned to by Back with that `compare` held at its answer
    (the driver's `hold_op`): before the answer the stop stands with the landing and holds the focus, named for its kind,
    its count being read, the mirror out of the page's order holding no focus, the AX tree's focused node the stop; the
    answer released whole, cut to part of what the stop stood for or none of it (`cutting`), refused — the board busy —
    and whole with the reader moved on first: the focus kept, or where they put it, the stop filled in or saying so in
    FP-21's words; Enter made before the answer waiting, Esc abandoning it, a whole answer making it (`stop_returns`).
    Where this board stands no such stop it is said unmeasured (FP-18). The driver's hold is lifted after; its figures"""
    figures = {}
    try:
        # the stop at a band's clipped end: the draft's passage holding the window run's material beside the first edition,
        # whose passage holding it stands below pane B's view
        ctx.leap(WINDOW[2], 1)
        ctx.js('window.__skep.scene.open(%s, %s, %s)' % (json.dumps(WINDOW[2]), json.dumps(DOC), json.dumps({'posA': 1, 'widthA': WINDOW[1], 'wholeB': True})))
        wait_for(ctx, 'window.__skep.scene.isOpen() && window.__skep.scene.pairs().pairs.length > 0')
        s = ctx.js('window.__skep.scene.stop()') or {}
        if s.get('shared') and not s.get('shown'):
            s = scrolled_past(ctx, s['shared'][0])
        at = s.get('at')
        if s.get('shown') and at and at['width'] >= 2:
            half = at['pos'] + at['width'] // 2
            figures['shared'] = stop_returns(ctx, r, 'the stop at a band\'s clipped end', '#scenestop', 'shared',
                                             {'part': cutting(('u2', half, at['pos'] + at['width'])), 'none': cutting(('u2', at['pos'], at['pos'] + at['width']))},
                                             'document.getElementById("sceneB").scrollTop')
        else:
            r.note('a return to the stop at a band\'s clipped end: unmeasured — no scene here stands one (FP-18)')
            figures['shared'] = 'unmeasured'
        ctx.js('window.__skep.scene.close()')
        ctx.frames(2)
        # a stroke's button: the edition with two members' first member beside its latest, the latest named whole
        first = VERSIONED + '.1'
        ctx.leap(first, None)
        ctx.js('window.__skep.scene.open(%s, %s, %s)' % (json.dumps(first), json.dumps(VERSIONED), json.dumps({'wholeB': True})))
        wait_for(ctx, 'window.__skep.scene.isOpen() && window.__skep.scene.pairs().pairs.length > 0')
        strokes, tried = stroke_at_junction(ctx, (scene_level(ctx) or {}).get('pairs') or [])
        one = next((x for x in strokes if len(x['changes']) == 1), strokes[0] if strokes else None)
        if one:
            c0, c1 = one['changes'][0], one['changes'][-1]
            before, after = c0['a']['from'] - 1, c1['a']['to']
            figures['stroke'] = stop_returns(ctx, r, 'a stroke\'s button', '[id="%s"]' % one['id'], 'stroke',
                                             {'part': cutting(('u1', after, after + 1)), 'none': cutting(('u1', before, before + 1), ('u1', after, after + 1))},
                                             'window.__skep.overlay().id')
        else:
            r.note(f'a return to a stroke\'s button: unmeasured — no stroke stands in this board\'s whole-document scene ({tried} junctions tried) (FP-18)')
            figures['stroke'] = 'unmeasured'
        ctx.js('window.__skep.scene.close()')
        ctx.frames(2)
    finally:
        ctx.drv.unhold()
    return figures


# a reading scene's pane scrolled down `by` px at the most, the top of its last block kept 10 px or more below the pane's
# visible top, so the place the scene records as the reader leaves it names a block of it; its scroll after, null where the
# pane holds no block
SCROLL_AWAY = '''((side, by) => { const p = document.getElementById(side === 'a' ? 'sceneA' : 'sceneB'), art = p && p.querySelector(':scope > article.dtext');
  const blocks = art ? [...art.querySelectorAll('.run > .sp, .run > .withheld')] : [], last = blocks[blocks.length - 1];
  if (!last) return null;
  p.scrollTop += Math.max(0, Math.min(by, last.getBoundingClientRect().top - (p.getBoundingClientRect().top + p.clientTop) - 10));
  return p.scrollTop; })(%s, %d)'''


def scene_pane_return_holds(ctx, r):
    """A WHOLE-DOCUMENT SCENE LEFT FROM A PANE, RETURNED TO (FP-20, FP-25): the first edition's window run beside the draft
    it windows, the far end naming the draft whole, opened anew for each pane and each pane's corner; its panes scrolled
    away from where the scene set them (`SCROLL_AWAY`), the focus put on the stop — a pane's corner's its first act where
    it holds acts, else itself (`FOCUS_STOP`) — the scene left by WHOLE BOARD and returned to by Back with its `compare`
    held at its answer (`back_to`): before the answer the scene stands with no band and no stop returned with it, the
    focus on the stop it was left from, the mirror out of the page's order holding none, the AX tree's focused node that
    stop by its role, each pane where the reader left it, 1 px either way; the answer released whole, its bands added and
    nothing else moved — each pane's scroll, 0.5 px either way, and the focus. The driver's hold is lifted after; its
    figures, by stop"""
    figures = {}
    held = {'posA': WINDOW[0], 'widthA': WINDOW[1], 'wholeB': True}
    banded = 'window.__skep.scene.isOpen() && window.__skep.scene.pairs().pairs.length > 0'
    stops = (('a', '#sceneA'), ('b', '#sceneB'), ('a:corner', '#sceneA > .corner'), ('b:corner', '#sceneB > .corner'))
    try:
        ctx.leap(DOC, WINDOW[0])
        for stop, sel in stops:
            ctx.js('window.__skep.scene.open(%s, %s, %s)' % (json.dumps(DOC), json.dumps(WINDOW[2]), json.dumps(held)))
            wait_for(ctx, banded)
            set_at = ctx.js(SCENE_SCROLLS)
            ctx.js(SCROLL_AWAY % (json.dumps('a'), 200))
            ctx.js(SCROLL_AWAY % (json.dumps('b'), 300))
            at = ctx.js(FOCUS_STOP % json.dumps(sel))
            # its role in the AX tree: a pane's a region, a corner's act a button, a corner holding none a group
            role = 'region' if ':' not in stop else 'button' if ': ' in (at or '') else 'group'
            name = f'a whole-document scene left from {at}'
            ctx.frames(2)
            left, on = ctx.js(SCENE_SCROLLS), where_focus(ctx)
            r.check(bool(at) and left['a'] != set_at['a'] and left['b'] > 0 and on['at'] == at,
                    f'{name}: each pane scrolled away from where the scene set it, pane B past its top, the focus on the stop', {'set': set_at, 'left': left, 'focus': on})
            ret = back_to(ctx)
            now = ctx.js('({open: window.__skep.scene.isOpen(), pairs: (window.__skep.scene.pairs() || {pairs: null}).pairs, scrolls: %s})' % SCENE_SCROLLS)
            before, ax = where_focus(ctx), focused_ax(ctx)
            r.check(now['open'] and now['pairs'] == [] and ret is None and before['at'] == at and before['inert'] and not before['holds']
                    and all(abs(now['scrolls'][s] - left[s]) <= 1 for s in 'ab'),
                    f'{name}, returned to by Back: before its `compare` answers, the scene stands with no band and no stop returned with it, the focus on the stop it was left from — the mirror out of the page\'s order, holding none — and each pane where the reader left it, 1 px either way',
                    {'scene': now, 'returned': ret, 'focus': before, 'left': left})
            if ax is not None:
                r.check(ax['role'] == role, f'{name}, returned to: the AX tree\'s focused node is the stop it was left from, a {role}', ax)
            released = ctx.drv.answer_op('whole')
            wait_for(ctx, banded)
            after = ctx.js('({pairs: (window.__skep.scene.pairs() || {pairs: []}).pairs.length, bands: (window.__skep.scene.ties() || []).filter((t) => t.kind === "band").length, scrolls: %s})' % SCENE_SCROLLS)
            then, ax2 = where_focus(ctx), focused_ax(ctx)
            r.check(released and after['pairs'] > 0 and after['bands'] > 0 and all(abs(after['scrolls'][s] - now['scrolls'][s]) <= 0.5 for s in 'ab')
                    and then['at'] == at and then['inert'] and not then['holds'] and (ax2 is None or ax2['role'] == role),
                    f'{name}: its `compare` answered, its bands added and nothing else moved — each pane\'s scroll, 0.5 px either way, and the focus on the stop it was left from, the mirror still out of the page\'s order',
                    {'released': released, 'scene': after, 'returned': now['scrolls'], 'focus': then, 'ax': ax2})
            figures[stop] = {'set': set_at, 'left': left, 'returned': now['scrolls'], 'answered': after['scrolls'], 'focus': then['at'],
                             'pairs': after['pairs'], 'bands': after['bands'], 'ax': ax}
            ctx.js('window.__skep.scene.close()')
            ctx.settle()
            ctx.frames(2)
    finally:
        ctx.drv.unhold()
    return figures


def whole_edges_hold(ctx, r, name, lines):
    """each pane a line's end naming its document whole meets (issue #59's design decision: "that whole edge is drawn in
    the link's colour as the end. Wherever the reader scrolls, they stay inside it"): its facing edge drawn whole — the
    stroke against that edge, EDGE_TOL_PX either way, from the pane's visible top to its visible bottom, TIE_TOL_PX
    either way, for the links whose whole ends meet it, in the hue their marks there merge into as the page's own LK
    marks them — and every line leaving its pane as `ties_hold` holds it, as the scene stands and again with that pane
    scrolled by half its height; its figures"""
    sides = sorted({s for t in lines for s in ('a', 'b') if t[s].get('whole')})
    r.check(bool(sides), f'{name}: a line ends at a document named whole', [(t['link'], t['a'], t['b']) for t in lines])
    seen = []
    for at in ('as it stands', 'its pane scrolled'):
        if at == 'its pane scrolled':
            for s in sides:
                ctx.js('(() => { const p = document.getElementById(%s); p.scrollTop += p.clientHeight / 2; })()' % json.dumps('scene' + s.upper()))
            ctx.frames(2)
        ties = ctx.js('window.__skep.scene.ties()')
        edges = ctx.js('window.__skep.scene.edges()')
        panes = ctx.js('window.__skep.scene.panes()') or {}
        for s in sides:
            links = sorted({t['link'] for t in ties if t['kind'] == 'link' and t[s].get('whole')})
            e = next((x for x in edges if x['side'] == s), None)
            pane, face = (ties[0]['pane' + s.upper()], ties[0]['face' + s.upper()]) if ties else (None, None)
            hue = ctx.js('''(async (links, doc) => { const LK = await import('./links/links.js'), R = await import('./model/records.js'), BM = await import('./beams/beams.js');
              const marks = links.map((l) => R.link(l)).filter(Boolean).map((l) => LK.markOf(l, doc));
              return marks.length ? BM.inkOf(LK.mergedMark(marks)).hue : null; })(%s, %s)''' % (json.dumps(links), json.dumps((panes.get(s) or {}).get('src'))))
            ok = bool(e and pane and face is not None and hue) and sorted(set(e['links'])) == links and abs(e['x'] - face) <= EDGE_TOL_PX \
                and abs(e['top'] - pane['y']) <= TIE_TOL_PX and abs(e['bottom'] - (pane['y'] + pane['h'])) <= TIE_TOL_PX and e['hue'] == hue
            r.check(ok, f'{name}, {at}: pane {s.upper()}\'s facing edge drawn whole as the end its whole document is — against the edge, {EDGE_TOL_PX} px either way, from the pane\'s visible top to its bottom, in the colour the links\' marks there merge into (issue #59)',
                    {'edge': e, 'pane': pane, 'face': face, 'links': links, 'hue': hue})
            seen.append({'at': at, 'side': s, 'links': len(links), 'edge': e and {k: round(e[k], 1) for k in ('x', 'top', 'bottom')}, 'hue': hue})
        ties_hold(r, f'{name}, {at}', [t for t in ties if t['kind'] == 'link'], 1, band=False)
    return seen


# the scrolls of the reading scene's two panes, as the page reads them
SCENE_SCROLLS = '({a: document.getElementById("sceneA").scrollTop, b: document.getElementById("sceneB").scrollTop})'


def scene_whole_holds(ctx, r):
    """A FAR END NAMING ITS DOCUMENT WHOLE (issue #59's design decision): the scene opened, through the gate's door as the
    card's "read side by side" opens it at such a link, on a passage beside a document a far end of it names whole — the
    first edition's window run beside the draft it windows, then the draft's passage holding the run's material beside
    the first edition: pane A set at the passage, pane B at its document's start, the `compare` adding its bands once the
    scene shows, moving no pane; pane B the focus, named by its address and the words saying the whole document is the
    link's end, and the current location; the stop standing exactly where a passage of pane B holding the near passage's
    material has its first line out of pane B's view — as a scene opens, else, in the last, once the reader scrolls pane
    B past the passage — and holding (`stop_holds`) in the first scene that stands it. Unmeasured where neither does
    (FP-18). Its figures, by pane B's document"""
    whole = ctx.js('(async () => { const {t} = await import("./strings.js"); return t("L.scene.whole-end"); })()')
    orders = ((DOC, WINDOW[2]), (WINDOW[2], DOC))
    near, figures, measured = {'pos': WINDOW[0], 'width': WINDOW[1]}, {}, False
    for k, (a, b) in enumerate(orders):
        ctx.leap(a, near['pos'])
        held = {'posA': near['pos'], 'widthA': near['width'], 'wholeB': True}
        ctx.js('window.__skep.scene.open(%s, %s, %s)' % (json.dumps(a), json.dumps(b), json.dumps(held)))
        wait_for(ctx, 'window.__skep.scene.isOpen() && window.__skep.scene.pairs().pairs.length > 0')
        v = scene_level(ctx)
        opened = ctx.js('''(() => { const b = document.getElementById('sceneB');
          return {focus: document.activeElement && document.activeElement.id, current: b.getAttribute('aria-current'),
                  named: (b.getAttribute('aria-labelledby') || '').split(' ').map((id) => { const e = document.getElementById(id); return e ? e.textContent : null; })}; })()''')
        at_open = ctx.js(SCENE_SCROLLS)
        shows = ((ctx.js('window.__skep.scene.panes()') or {}).get('b') or {}).get('shows')
        kind = ctx.js('window.__skep.kind(%s).words' % json.dumps(b))
        r.check(bool(v) and v['level'] == {'a': near['pos'], 'b': None} and bool(v['pairs']) and at_open['b'] == 0,
                f'{a}\'s passage at {near["pos"]} beside {b}, which a far end of it names whole: pane A at the passage, pane B at its document\'s start, the bands its `compare` added once the scene showed moving neither (issue #59)',
                {'level': v and v['level'], 'bands': v and len(v['pairs']), 'scroll': at_open})
        r.check(opened['focus'] == 'sceneB' and opened['current'] == 'location' and opened['named'] == [kind, shows, whole],
                f'{a} beside {b}: pane B takes the focus, named by its kind, its address and the words saying the whole document is the link\'s end, and is the current location (issues #59, #423)', dict(opened, kind=kind, shows=shows, want=whole))
        s = ctx.js('window.__skep.scene.stop()') or {}
        seen = figures[b] = {'level': v and v['level'], 'bands': v and len(v['pairs']), 'shared': s.get('shared'), 'stop': s.get('shown')}
        if not s.get('shared'):
            r.check(False, f'{b} holds the material of {a}\'s passage at {near["pos"]}: the stop has passages to reach', s)
            ctx.js('window.__skep.scene.close()')
            ctx.frames(2)
            break
        then, at_first, away = s['shared'][0], bool(s.get('shown')), out_of_view(ctx, s['shared'])
        r.check(at_first == bool(away), f'{a} beside {b} as the scene opens: the stop stands exactly where a passage of pane B holding the near passage\'s material has its first line out of the pane\'s view (issue #59)', {'stop': s, 'away': away})
        if not measured and not away and k == len(orders) - 1:
            s = scrolled_past(ctx, then)
            away = out_of_view(ctx, s['shared'])
            seen['scrolled'] = True
            r.check(bool(s.get('shown')) == bool(away), f'{a} beside {b}, pane B scrolled past the passage: the stop stands exactly where a passage holding the near passage\'s material has its first line out of the pane\'s view (issue #59)', {'stop': s, 'away': away})
        if not measured and away and s.get('shown'):
            seen.update(stop_holds(ctx, r, near, s, at_open, shows, at_first))
            measured = True
        near = {'pos': then['pos'], 'width': then['width']}
        ctx.js('window.__skep.scene.close()')
        ctx.frames(2)
    if not measured:
        r.note('the stop at a band\'s clipped end: unmeasured — no scene here clipped a band to a passage holding the near passage\'s material, as it opened or scrolled past it (FP-18)')
        figures['unmeasured'] = True
    return figures


def out_of_view(ctx, shared):
    """the passages of the reading scene's pane B among `shared` whose first line — read now through the gate's `at`,
    apart from the scene's own measure — has its middle outside the pane's visible content"""
    out = []
    for p in shared:
        at = ctx.js('window.__skep.scene.at("b", %d, %d)' % (p['pos'], p['width']))
        line, pane = at and at['line'], at and at['pane']
        if line and not pane['y'] <= line['y'] + line['h'] / 2 <= pane['y'] + pane['h']:
            out.append(p)
    return out


def scrolled_past(ctx, p):
    """the reader's scroll of the reading scene's pane B past a passage `p` it holds — its first line a line and 4 px
    above the pane's visible top — and the stop as the draw on that scroll placed it"""
    at = ctx.js('window.__skep.scene.at("b", %d, %d)' % (p['pos'], p['width']))
    line = at and at['line']
    if line:
        ctx.js('document.getElementById("sceneB").scrollTop += %f' % (line['y'] + line['h'] - at['pane']['y'] + 4))
        ctx.frames(2)
    return ctx.js('window.__skep.scene.stop()') or {}


def stop_holds(ctx, r, near, s, at_open, shows, at_first):
    """THE STOP AT A BAND'S CLIPPED END (issue #59's design decision), the reading scene standing with the near passage
    `near` in pane A and the stop shown, `s` as the gate reads it: a native button at pane B's facing edge on the band's
    bearing, at the end of the near passage's band to the passage it stands for where that band's extent passes the
    pane's edge, held there, named by
    ST's words, its count where the passages holding the near passage's material are several; a person's click on it
    bringing that passage into pane B, its first line level with the near passage's where that line stands in pane A's
    view, else STOP_AT_PX below pane B's top, pane A unmoved; where it was the one passage, the stop gone and the focus
    on pane B, else the stop gone on to the next passage; the re-level act putting both panes back where the scene
    opened (`at_open`), the stop standing as it stood then (`at_first`), at its first passage. Its figures"""
    n, first = len(s['shared']), s['at']
    pane = ctx.js('(() => { const p = document.getElementById("sceneB"), q = p.getBoundingClientRect(); return {x: q.left, y: q.top + p.clientTop, h: p.clientHeight}; })()')
    name = ctx.js('(async (n, D) => { const {t} = await import("./strings.js"); return t(n > 1 ? "L.scene.shared" : "L.scene.shared.1", {D, n}); })(%d, %s)' % (n, json.dumps(shows)))
    rect = s['rect']
    above = abs(rect['y'] - pane['y']) <= TIE_TOL_PX
    below = abs(rect['y'] + rect['h'] - (pane['y'] + pane['h'])) <= TIE_TOL_PX
    edge = pane['y'] if above else pane['y'] + pane['h'] if below else None
    band = next((t for t in ctx.js('window.__skep.scene.ties()') if t['kind'] == 'band' and t['b']['pos'] <= first['pos'] < t['b']['pos'] + t['b']['width']), None)
    # the band at its extent (issue #331): passing pane B's visible top, held at it, or its bottom, on the stop's bearing
    held = bool(band) and ((above and band['b']['above'] and abs(band['b']['top'] - edge) <= TIE_TOL_PX) or (below and band['b']['below'] and abs(band['b']['bottom'] - edge) <= TIE_TOL_PX))
    r.check(abs(rect['x'] + rect['w'] - pane['x']) <= TIE_TOL_PX and edge is not None and held
            and s['name'] == name and s['count'] == (str(n) if n > 1 else ''),
            'the stop stands at pane B\'s facing edge, at the end of the near passage\'s band to the passage it stands for where that band passes the pane\'s edge on its bearing and is held there, named by ST\'s words, its count where the passages holding its material are several (issue #59)',
            {'stop': s, 'pane': pane, 'band': band and band['b'], 'want': name})
    hit = click_on(ctx, '#scenestop')
    ctx.frames(2)
    after, moved = ctx.js('window.__skep.scene.stop()') or {}, ctx.js(SCENE_SCROLLS)
    la = ctx.js('window.__skep.scene.at("a", %d, %d)' % (near['pos'], near['width']))
    lb = ctx.js('window.__skep.scene.at("b", %d, %d)' % (first['pos'], first['width']))
    in_view = bool(la and la['line']) and inside(la['line'], la['pane'])
    want_y = la['line']['y'] if in_view else pane['y'] + STOP_AT_PX
    brought = bool(lb and lb['line']) and inside(lb['line'], lb['pane']) and abs(lb['line']['y'] - want_y) <= LEVEL_TOL_PX
    where = "level with the near passage's" if in_view else "%d px below the pane's top" % STOP_AT_PX
    r.check(bool(hit) and hit['hits'] and brought and moved['a'] == at_open['a'],
            f'a person\'s click on the stop brings the passage it stands for into pane B, its first line {where}, {LEVEL_TOL_PX} px either way, pane A unmoved (issue #59)',
            {'hit': hit, 'a': la and la['line'], 'b': lb and lb['line'], 'want_y': want_y, 'scroll': moved})
    focus = ctx.js('document.activeElement && document.activeElement.id')
    if n == 1:
        r.check(not after.get('shown') and focus == 'sceneB', 'its one passage in view: the stop leaves, the focus on pane B (FP-20)', {'stop': after, 'focus': focus})
    else:
        r.check(after.get('shown') and after.get('at') != first and after.get('next') == (s['shared'].index(first) + 1) % n,
                'its passages several: the stop goes on to the next of them (issue #59)', {'before': s, 'after': after})
    click_on(ctx, '#scenebar [data-relevel]')
    ctx.frames(2)
    back, again = ctx.js(SCENE_SCROLLS), ctx.js('window.__skep.scene.stop()') or {}
    r.check(back == at_open and bool(again.get('shown')) == at_first and again.get('next') == 0 and (not at_first or again.get('at') == first),
            'the re-level act puts both panes back where the scene opened, and the stop as it stood then, at its first passage (issue #59)', {'opened': at_open, 'back': back, 'stop': again, 'shown_at_open': at_first})
    return {'count': n, 'bearing': 'above' if above else 'below', 'near_in_view': in_view, 'brought': lb and lb['line'] and round(lb['line']['y'], 1)}


def untouched(ctx):
    """what a click on a scene's pane could move: whether the scene stands, the overlay, the camera, the trail, the selection"""
    return ctx.js('({scene: window.__skep.scene.isOpen(), overlay: window.__skep.overlay().id, cam: window.__skep.view.camera(), trail: window.__skep.trail(), sel: window.__skep.selection()})')


def pane_mark(ctx, selector):
    """a mark in a scene's pane as a pointer meets it: the first element the selector names (kept as `window.__gateMark`),
    its pane scrolled to stand it a third of the way down — a corner's held at the pane's top needs none, nor a sign in its
    column's edge, which stands beside its run's first line in view wherever the pane scrolls — and the point at the middle
    of a block's first character of its own text, the chrome and the link marks inside it skipped, or of any other mark's
    box; whether the mark is what lies under that point. None where no element answers"""
    return ctx.js('''((sel) => { const e = document.querySelector(sel); window.__gateMark = e; if (!e) return null;
      const pane = e.closest('.pane');
      if (pane && !e.closest('.corner, .edge-sign')) { const p = pane.getBoundingClientRect(); pane.scrollTop += e.getBoundingClientRect().top - p.top - pane.clientHeight / 3; }
      let q = e.getBoundingClientRect();
      if (e.matches('.sp')) {
        const w = document.createTreeWalker(e, NodeFilter.SHOW_TEXT);
        for (let n = w.nextNode(); n; n = w.nextNode()) {
          const i = n.textContent.search(/\\S/);
          if (i < 0 || n.parentElement.closest('.sym, .others, .lip')) continue;
          const r = document.createRange(); r.setStart(n, i); r.setEnd(n, i + 1); q = r.getBoundingClientRect(); break;
        }
      }
      const x = q.left + q.width / 2, y = q.top + q.height / 2, hit = document.elementFromPoint(x, y);
      return {x, y, hits: !!hit && (hit === e || e.contains(hit))}; })(%s)''' % json.dumps(selector))


def pane_click_holds(ctx, r, what, selector):
    """a person's click on a mark in a scene's pane (SC: the panes are read, never clicked): the mark under the pointer,
    and after the click the scene standing over the page as the click found it"""
    before = untouched(ctx)
    at = pane_mark(ctx, selector)
    if at:
        ctx.drv.mouse(at['x'], at['y'])
        ctx.settle()
        ctx.frames(2)
    after = untouched(ctx)
    r.check(bool(at) and at['hits'] and after['scene'] and after == before, f'a click on {what} in a scene\'s pane acts on nothing: the scene stands, and the overlay, the camera, the trail and the selection are as the click found them',
            {'at': at, 'moved': [k for k in before if before[k] != after[k]], 'overlay': after['overlay'], 'sel': after['sel']})


def scene_marks_hold(ctx, r):
    """THE SCENE'S PANES ARE READ, NOT ACTED ON (SC; B1-S9): the scene on the first edition and the draft it windows, the
    first edition's links revealed to their symbols — pane A scrolled away, a click on the re-level act's chord mark sets
    the two ends level again (K-62); no block, run's key in the column's edge or symbol in a pane takes the plane's click
    cues, which the plane's keep, and a block under the pointer keeps a clear ground; a click on a block, the window run's
    key, the presence ⟡ or a link's symbol changes nothing; its figures"""
    ctx.leap(DOC, WINDOW[0])
    ctx.js('window.__skep.links.reveal(%s, 2)' % json.dumps(DOC))
    ctx.frames(2)
    # the plane's own cues, read before the scene stands over it: the window run's key in its column's edge at the landing,
    # then, the first column in view — its head among the lines standing (issue #122: a document stands by line), where
    # the presence ⟡ stands — the text's, and the camera back at the landing
    cursors = '(sel) => [...document.querySelectorAll(sel)].map((e) => getComputedStyle(e).cursor)'
    keys = ctx.js('(%s)("#corners .edge-sign .src-key")' % cursors)
    landing = ctx.camera()
    ctx.view_doc_em(DOC, 12.5)
    plane_cues = ctx.js('''(() => { const cur = %s;
      return {blocks: cur('#domlayer .run > .sp'), presence: cur('#domlayer .sym.reveal'), symbols: cur('#domlayer .sym[data-link]')}; })()''' % cursors)
    plane_cues['keys'] = keys
    ctx.set_view(landing['x'], landing['y'], landing['scale'])
    ctx.js('window.__skep.scene.open(%s, %s)' % (json.dumps(DOC), json.dumps(WINDOW[2])))
    ctx.settle()
    ctx.frames(3)
    # the re-level act's chord mark: the act is its button's wherever on the button a click lands
    ctx.js('document.getElementById("sceneA").scrollTop += 400')
    ctx.frames(2)
    away = scene_level(ctx) or {}
    a, b = away.get('a'), away.get('b')
    r.check(bool(a and b and a['line'] and b['line']) and abs(a['line']['y'] - b['line']['y']) > LEVEL_TOL_PX, 'pane A scrolled away: its matched line stands off pane B\'s, what the re-level act restores',
            {'a': a and a['line'], 'b': b and b['line']})
    mark = ctx.js('''(() => { const k = document.querySelector('#scenebar [data-relevel] kbd'); if (!k) return null;
      const q = k.getBoundingClientRect(), x = q.left + q.width / 2, y = q.top + q.height / 2; return {x, y, hits: document.elementFromPoint(x, y) === k}; })()''')
    if mark:
        ctx.drv.mouse(mark['x'], mark['y'])
        ctx.frames(2)
    r.check(bool(mark) and mark['hits'], 'the re-level act\'s chord mark is what lies under the pointer', mark)
    level_holds(r, 'a click on the re-level act\'s chord mark (K-62)', scene_level(ctx))
    # the click cues are the plane's: none in a pane, every one kept on the plane's text layer
    cues = ctx.js('''(() => { const cur = %s;
      const at = (root) => ({blocks: cur(root + ' .run > .sp'), keys: cur(root + ' .edge-sign .src-key'), presence: cur(root + ' .sym.reveal'), symbols: cur(root + ' .sym[data-link]')});
      return {pane: at('.pane')}; })()''' % cursors)
    cues['plane'] = plane_cues
    kinds = ('blocks', 'keys', 'presence', 'symbols')
    pointer = {k: sum(1 for c in cues['pane'][k] if c == 'pointer') for k in kinds}
    r.check(all(cues['pane'][k] for k in kinds) and not any(pointer.values()), 'no click cue in a scene\'s pane: no block, run\'s key in the column\'s edge, presence ⟡ or link\'s symbol takes the pointer cursor',
            {'pane': {k: len(cues['pane'][k]) for k in kinds}, 'pointer': pointer})
    r.check(all(cues['plane'][k] and all(c == 'pointer' for c in cues['plane'][k]) for k in kinds), 'the plane keeps its click cues: every block, presence ⟡ and link\'s symbol of a mounted article, and the window run\'s key in its column\'s edge, takes the pointer cursor',
            {k: sorted(set(cues['plane'][k])) for k in kinds})
    # the window run's key in its column's edge, while pane A stands at the run: a block's hover and its click scroll the pane to
    # the article's first block
    pane_click_holds(ctx, r, 'the window run\'s key', '#sceneA .edge-sign .src-key')
    at = pane_mark(ctx, '#sceneA .run > p.sp')
    if at:
        ctx.drv.mouse(at['x'], at['y'], kind='move')
        ctx.frames(2)
    ground = ctx.js('(() => { const e = window.__gateMark; return e ? {hovered: e.matches(":hover"), ground: getComputedStyle(e).backgroundColor} : null; })()')
    r.check(bool(at) and at['hits'] and bool(ground) and ground['hovered'] and ground['ground'] in ('rgba(0, 0, 0, 0)', 'transparent'), 'a block in a scene\'s pane under the pointer keeps a clear ground: no hover cue',
            {'at': at, 'ground': ground})
    for what, selector in (('a block', '#sceneA .run > p.sp'), ('the presence ⟡', '#sceneA .sym.reveal'), ('a link\'s symbol', '#sceneA .sym[data-link]')):
        pane_click_holds(ctx, r, what, selector)
    ctx.js('window.__skep.scene.close()')
    ctx.js('window.__skep.links.hide(%s)' % json.dumps(DOC))
    vp = ctx.js('window.__skep.view.viewport()')
    ctx.drv.mouse(vp['VW'] - 2, vp['VH'] - 2, kind='move')
    ctx.frames(2)
    return {'cues': {side: {k: len(cues[side][k]) for k in kinds} for side in ('pane', 'plane')}, 'hover': ground}


def pane_columns(ctx):
    """each scene pane's text column as a person meets it, by side: the pane's content box and its padding's top, its
    article's box — its top's depth in the pane's content, whatever its scroll — and its text column inside it — the
    article's content box, its padding the column's edge on the pane's inner side (issue #151) — its face's size, and its
    corner's box below the pane's visible top and the form it stands in, the flex gap between them, and its face's average
    advance at the body's size as the case probes it in one of its typed lines (`ADVANCE_JS`); the window's size beside
    them"""
    return ctx.js('''(() => { const advance = %s; const side = (id) => {
        const pane = document.getElementById(id), art = pane && pane.querySelector(':scope > article.dtext'), corner = pane && pane.querySelector(':scope > .corner');
        if (!art || !corner) return null;
        const p = pane.getBoundingClientRect(), s = getComputedStyle(pane), x0 = p.left + pane.clientLeft, y0 = p.top + pane.clientTop, b = art.getBoundingClientRect(), c = corner.getBoundingClientRect(), as = getComputedStyle(art);
        const pl = parseFloat(as.paddingLeft) + parseFloat(as.borderLeftWidth), pr = parseFloat(as.paddingRight) + parseFloat(as.borderRightWidth);
        const a = {left: b.left + pl, right: b.right - pr, width: b.width - pl - pr};
        const para = art.querySelector('.run > p.sp'), ch = para ? advance(para, 1) : null;
        const form = corner.classList.contains('head') ? 'head' : corner.classList.contains('compact') ? 'compact' : 'whole';
        return {content: {left: x0 + parseFloat(s.paddingLeft), right: x0 + pane.clientWidth - parseFloat(s.paddingRight), top: parseFloat(s.paddingTop)},
                box: {left: b.left, right: b.right, w: b.width, depth: b.top - y0 + pane.scrollTop}, text: {left: a.left, right: a.right, w: a.width}, edge: {left: pl, right: pr, font: parseFloat(as.fontSize)},
                corner: {left: c.left, right: c.right, w: c.width, top: c.top - y0, bottom: c.bottom - y0, form}, gap: parseFloat(s.columnGap), ch, scroll: pane.scrollTop};
      };
      return {vw: window.innerWidth, vh: window.innerHeight, a: side('sceneA'), b: side('sceneB')}; })()''' % ADVANCE_JS)


def pane_blocks(ctx, side):
    """a scene pane's blocks as a person meets them, below what a head held at the pane's top covers: the foot of that
    held row below the pane's visible top (0 where its corner stands beside its column), the first block meeting the view
    below it, and every block near the view, each its first position and its top"""
    return ctx.js('''((id) => { const pane = document.getElementById(id), art = pane && pane.querySelector(':scope > article.dtext'), c = pane && pane.querySelector(':scope > .corner');
      if (!art || !c) return null;
      const y0 = pane.getBoundingClientRect().top + pane.clientTop, held = c.classList.contains('head') ? c.getBoundingClientRect().bottom - y0 : 0;
      const blocks = [...art.querySelectorAll('.run > .sp, .run > .withheld')].map((e) => { const q = e.getBoundingClientRect(); return {pos: Number(e.dataset.pos), top: q.top - y0, bottom: q.bottom - y0, h: q.height}; })
        .filter((b) => b.h > 0 && b.bottom > -200 && b.top < pane.clientHeight + 200);
      return {held, first: blocks.find((b) => b.bottom > held + 0.5 && b.top < pane.clientHeight) || null, blocks: blocks.map((b) => ({pos: b.pos, top: b.top}))}; })(%s)''' % json.dumps('scene' + side.upper()))


def corner_opens(ctx, r, side='a'):
    """A COMPACT CORNER OPENS WHOLE ON ITS ACT (FP-26): a pane's corner standing compact — a click on its state's glyph
    opens it whole where it stands, its state in its words, whole wide over what stands beside it, the pane's text not
    moved, and a click on it opened closes it; Enter and Space at the glyph, the corner's stop, do the same as the
    platform activates the button, the focus kept on the act — its state's words, expanded, while it stands opened (FP-20).
    Its figures"""
    pane = 'scene' + side.upper()
    read = '''((id) => { const p = document.getElementById(id), c = p && p.querySelector(':scope > .corner'), a = p && p.querySelector(':scope > article.dtext'); if (!c || !a) return null;
      const st = c.querySelector('.st'), g = c.querySelector('.glyph'), q = (g || c).getBoundingClientRect(), b = a.getBoundingClientRect(), k = c.getBoundingClientRect();
      return {form: c.classList.contains('head') ? 'head' : c.classList.contains('compact') ? 'compact' : 'whole', open: c.classList.contains('open'), glyph: !!g, st: st ? st.textContent : null,
              w: k.width, text: [b.left, b.right], x: q.left + q.width / 2, y: q.top + q.height / 2, hits: !!g && document.elementFromPoint(q.left + q.width / 2, q.top + q.height / 2) === g}; })(%s)''' % json.dumps(pane)
    shut = ctx.js(read)
    if shut and shut['hits']:
        ctx.drv.mouse(shut['x'], shut['y'])
        ctx.frames(2)
    opened = ctx.js(read)
    if opened and opened['open']:
        ctx.drv.mouse(opened['x'], opened['y'])
        ctx.frames(2)
    closed = ctx.js(read)
    still = bool(shut and opened and closed) and all(abs(v['text'][0] - shut['text'][0]) <= MEASURE_TOL_PX and abs(v['text'][1] - shut['text'][1]) <= MEASURE_TOL_PX for v in (opened, closed))
    r.check(bool(shut) and shut['form'] == 'compact' and not shut['open'] and shut['glyph'] and shut['hits'] and bool(opened) and opened['open'] and not opened['glyph'] and bool(opened['st'])
            and opened['w'] > shut['w'] + MEASURE_TOL_PX and bool(closed) and not closed['open'] and closed['glyph'] and still,
            f'pane {side.upper()}\'s corner standing compact: a click on its state\'s glyph opens it whole where it stands — its state in its words, whole wide over what stands beside it, the pane\'s text not moved — and a click on it opened closes it (FP-26)',
            {'compact': shut, 'opened': opened, 'closed': closed})
    # the corner's stop focused, as Tab lands on it, and the act the focus stands on in the corner after a key
    stop = '''((id) => { const c = document.querySelector('#' + id + ' > .corner'), s = c && [...c.querySelectorAll('button')].find((b) => b.getAttribute('tabindex') === '0');
      if (s) s.focus(); return s && document.activeElement === s ? {whole: s.matches('[data-whole]'), glyph: s.matches('.glyph'), expanded: s.getAttribute('aria-expanded')} : null; })(%s)''' % json.dumps(pane)
    on = '''((id) => { const c = document.querySelector('#' + id + ' > .corner'), e = document.activeElement;
      return !!c && !!e && c.contains(e) && e.tagName === 'BUTTON' ? {whole: e.matches('[data-whole]'), glyph: e.matches('.glyph'), expanded: e.getAttribute('aria-expanded')} : null; })(%s)''' % json.dumps(pane)
    keyed = {}
    for name, key in (('Enter', 'Enter'), ('Space', ' ')):
        focused = ctx.js(stop)
        ctx.drv.key(key)
        ctx.frames(2)
        entered, at_open = ctx.js(read), ctx.js(on)
        ctx.drv.key(key)
        ctx.frames(2)
        left, at_shut = ctx.js(read), ctx.js(on)
        r.check(focused == {'whole': True, 'glyph': True, 'expanded': 'false'} and bool(entered) and entered['open'] and bool(entered['st']) and not entered['glyph']
                and at_open == {'whole': True, 'glyph': False, 'expanded': 'true'} and bool(left) and not left['open'] and left['glyph'] and at_shut == {'whole': True, 'glyph': True, 'expanded': 'false'},
                f'pane {side.upper()}\'s corner, its stop the glyph that opens it whole: {name} at it opens it whole, the focus kept on the act — its state\'s words, expanded — and {name} again closes it, the focus back on the glyph (FP-20, FP-26)',
                {'stop': focused, 'entered': entered, 'on_open': at_open, 'left': left, 'on_shut': at_shut})
        keyed[name] = {'opened': at_open, 'closed': at_shut}
    ctx.js('document.getElementById(%s).focus()' % json.dumps(pane))
    return {'glyph': shut and shut['st'], 'whole': opened and opened['st'], 'keyed': keyed}


def scene_measure_holds(ctx, r):
    """THE SCENE'S MEASURE (issue #436's design decision, its reading scene's part; FP-12, FP-26): the scene on the first
    edition and the draft it windows, both panes fitted once — the measure narrowing, never the face. At the run's window
    both panes at the reading size READING_PX, each pane's line a whole count of its face's average advance, the same in
    both, narrowed to HEAD_CH or more and short of the full measure, each corner compact on its pane's outer side, one gap
    from its text, the column against its pane's inner edge, its column's edge between them, where the bands and lines
    leave the pane beyond its signs (foundations §2.5, §3.1; issue #151); its glyph's click, and Enter and Space at the
    glyph, opening it whole (`corner_opens`). At a window SCENE_WIDE_PX wide the full measure, MEASURE_CH, each corner whole beside it on the
    outer side and room left past them, the column against the inner edge still. At a window SCENE_HEAD_PX wide, where
    beside its compact corner a pane keeps fewer than HEAD_CH characters, both corners at their documents' heads, across
    their columns' text and edge, both texts beginning at one depth below them, the measure the most characters the pane
    holds beside the edge alone, at the reading size; both panes scrolled, each first row held where it stood; ↓ in pane A
    bringing the next block's top to the held row's foot, never under it. The first block in view at the run's window is
    first in view at each window after it. While the window is changed the plane under the scene stands at the far band,
    where the view reads nothing (M-PUMP's `pump`), so the run's later cases meet the page as the scene's check found it;
    the window, the camera and the scene are put back as they stood. Its figures"""
    ctx.leap(DOC, WINDOW[0])
    ctx.js('window.__skep.scene.open(%s, %s)' % (json.dumps(DOC), json.dumps(WINDOW[2])))
    ctx.settle()
    ctx.frames(3)
    run = pane_columns(ctx)
    opened = corner_opens(ctx, r)
    ctx.frames(2)
    firsts = {'run': {s: (pane_blocks(ctx, s) or {}).get('first') for s in 'ab'}}
    landing, box = ctx.camera(), ctx.js('window.__skep.boxOf(%s)' % json.dumps(DOC))
    # the plane parked at the far band: a document's box half the band's lower edge wide
    ctx.set_view(box['x'] + box['w'] / 2, box['y'] + box['h'] / 2, ctx.js('window.__skep.constants.LOD_FAR_LO / 2 / window.__skep.constants.DOC_W'))
    asked = ctx.js('window.__skep.bridge.calls().length')
    was = ctx.resize(SCENE_WIDE_PX, run['vh'])
    try:
        ctx.settle()
        ctx.frames(2)
        wide = pane_columns(ctx)
        firsts['wide'] = {s: (pane_blocks(ctx, s) or {}).get('first') for s in 'ab'}
        band = ctx.js('window.__skep.view.lod().name')
        ctx.resize(SCENE_HEAD_PX, run['vh'])
        ctx.settle()
        ctx.frames(2)
        head = pane_columns(ctx)
        firsts['head'] = {s: (pane_blocks(ctx, s) or {}).get('first') for s in 'ab'}
        reads = ctx.js('window.__skep.bridge.calls().length') - asked
        # a scroll of 150 px: past the 100 px the held row's check asks, and short of the first edition's end, so ↓ has a next
        # block to bring up below the window run
        ctx.js('for (const id of ["sceneA", "sceneB"]) document.getElementById(id).scrollTop += 150')
        ctx.frames(3)
        scrolled = pane_columns(ctx)
        before = pane_blocks(ctx, 'a') or {}
        ctx.js('document.getElementById("sceneA").focus()')
        ctx.drv.key('ArrowDown')
        ctx.settle()
        ctx.frames(2)
        after = pane_blocks(ctx, 'a') or {}
    finally:
        ctx.resize(*was)
        ctx.set_view(landing['x'], landing['y'], landing['scale'])
        ctx.js('window.__skep.scene.close()')
        ctx.frames(2)
    back = ctx.js('[window.innerWidth, window.innerHeight]')
    sides = (('a', 'pane A'), ('b', 'pane B'))
    both = lambda v: bool(v['a'] and v['b'])
    windows = (('run', run), ('wide', wide), ('head', head))

    def cpl(c):
        """a column's line in its face's average advance"""
        return c['text']['w'] / c['ch'] if c and c['ch'] else None

    def whole_counts(v):
        """each pane's line a whole count of its face's average advance, the two alike"""
        ws = [cpl(v[s]) for s, _ in sides]
        return both(v) and all(w is not None and abs(w - round(w)) <= MEASURE_CH_TOL for w in ws) and max(ws) - min(ws) <= 2 * MEASURE_CH_TOL

    def room(c):
        """the width a pane's content box holds for its text: its own, less its corner and the gap"""
        return c['content']['right'] - c['content']['left'] - c['corner']['w'] - c['gap']

    def edged(v):
        """each column against its pane's inner edge, its column's edge between them: pane A's edge on its text's right ending at
        its content's right edge, pane B's on its text's left starting at its left edge"""
        a, b = v['a'], v['b']
        return both(v) and abs(a['edge']['right'] - EDGE_EM * a['edge']['font']) <= MEASURE_TOL_PX and a['edge']['left'] <= MEASURE_TOL_PX and abs(b['edge']['left'] - EDGE_EM * b['edge']['font']) <= MEASURE_TOL_PX and b['edge']['right'] <= MEASURE_TOL_PX \
            and abs(a['box']['right'] - a['content']['right']) <= MEASURE_TOL_PX and abs(b['box']['left'] - b['content']['left']) <= MEASURE_TOL_PX

    def outside(v, form):
        """each corner in `form` on its pane's outer side, one gap from its text, inside the pane's content box"""
        a, b = v['a'], v['b']
        return both(v) and a['corner']['form'] == form and b['corner']['form'] == form \
            and abs(a['corner']['right'] + a['gap'] - a['text']['left']) <= MEASURE_TOL_PX and a['corner']['left'] >= a['content']['left'] - MEASURE_TOL_PX \
            and abs(b['text']['right'] + b['gap'] - b['corner']['left']) <= MEASURE_TOL_PX and b['corner']['right'] <= b['content']['right'] + MEASURE_TOL_PX

    def picked(v, keys):
        return {name: v[s] and {k: v[s][k] for k in keys} for s, name in sides}

    sizes = {k: [v[s] and v[s]['edge']['font'] for s, _ in sides] for k, v in windows}
    r.check(all(both(v) for _, v in windows) and all(f is not None and abs(f - READING_PX) <= 1e-6 for fs in sizes.values() for f in fs),
            f'the scene: both panes at the reading size, {READING_PX} px, at the run\'s {run["vw"]} px window, at a {SCENE_WIDE_PX} px one and at a {SCENE_HEAD_PX} px one — the face never set smaller to fit (FP-12, FP-26)',
            sizes)
    r.check(wide['vw'] == SCENE_WIDE_PX and head['vw'] == SCENE_HEAD_PX and band == 'far' and reads == 0 and back == [run['vw'], run['vh']],
            f'the window set {SCENE_WIDE_PX} px, then {SCENE_HEAD_PX} px wide with the plane under the scene at the far band, the page asking the board nothing while it stood so, and the window put back at the run\'s size after it',
            {'wide': [wide['vw'], wide['vh']], 'head': [head['vw'], head['vh']], 'band': band, 'reads': reads, 'back': back})
    chars = {k: {name: cpl(v[s]) and round(cpl(v[s]), 3) for s, name in sides} for k, v in windows}
    lo, hi = MEASURE_CH
    r.check(whole_counts(run) and all(HEAD_CH - MEASURE_CH_TOL <= cpl(run[s]) <= hi - 1 + MEASURE_CH_TOL for s, _ in sides) and outside(run, 'compact') and edged(run),
            f'at the run\'s {run["vw"]} px window, too narrow for the full measure beside a whole corner: each corner compact on its pane\'s outer side, one gap from its text, and the measure narrowed — a whole count of its face\'s average advance, the same in both panes, {HEAD_CH} or more and short of {hi} — each column against its pane\'s inner edge, its column\'s edge between them, {MEASURE_TOL_PX} px either way',
            {'characters': chars['run'], **picked(run, ('content', 'box', 'text', 'edge', 'corner', 'gap'))})
    r.check(whole_counts(wide) and all(lo - MEASURE_CH_TOL <= cpl(wide[s]) <= hi + MEASURE_CH_TOL for s, _ in sides) and outside(wide, 'whole') and edged(wide)
            and all(room(wide[s]) > wide[s]['box']['w'] + MEASURE_TOL_PX for s, _ in sides),
            f'at a {SCENE_WIDE_PX} px window: the full measure — a whole count of its face\'s average advance, {lo}–{hi}, the same in both panes — each corner whole on its pane\'s outer side, one gap from its text, room left past them, each column against its pane\'s inner edge',
            {'characters': chars['wide'], **picked(wide, ('content', 'box', 'text', 'edge', 'corner', 'gap'))})

    def across(c):
        """a corner at its document's head across its column's text and its edge, above the text, the text one band of rows
        or more below the pane's content top"""
        return c['corner']['form'] == 'head' and abs(c['corner']['left'] - c['box']['left']) <= MEASURE_TOL_PX and abs(c['corner']['right'] - c['box']['right']) <= MEASURE_TOL_PX \
            and c['box']['depth'] - c['content']['top'] >= (c['corner']['bottom'] - c['corner']['top']) - MEASURE_TOL_PX

    def holds(c, compact):
        """the measure the room beside the edge alone: the most whole characters the pane's content box holds beside the
        column's edge, fewer than HEAD_CH beside the compact corner"""
        w = c['content']['right'] - c['content']['left']
        return c['box']['w'] <= w + MEASURE_TOL_PX and w - c['box']['w'] < c['ch'] + MEASURE_TOL_PX and (w - compact - c['gap'] - EDGE_EM * c['edge']['font']) / c['ch'] < HEAD_CH

    compact = run['a'] and run['a']['corner']['w']
    r.check(whole_counts(head) and both(head) and all(across(head[s]) and holds(head[s], compact) for s, _ in sides) and abs(head['a']['box']['depth'] - head['b']['box']['depth']) <= MEASURE_TOL_PX
            and edged(head),
            f'at a {SCENE_HEAD_PX} px window, where beside its compact corner a pane keeps fewer than {HEAD_CH} characters: both corners at their documents\' heads, across their columns\' text and edge, both texts beginning at one depth below them, and the measure the most characters each pane holds beside the edge alone — its column against its inner edge',
            {'characters': chars['head'], 'compact_corner': compact, **picked(head, ('content', 'box', 'text', 'edge', 'corner', 'gap'))})
    held = both(head) and both(scrolled) and all(scrolled[s]['scroll'] > head[s]['scroll'] + 100 and abs(scrolled[s]['corner']['top'] - head[s]['corner']['top']) <= MEASURE_TOL_PX for s, _ in sides)
    r.check(held, f'at a {SCENE_HEAD_PX} px window both panes scrolled: each head\'s first row held where it stood, the text passing under it',
            {name: {'scroll': [head[s] and head[s]['scroll'], scrolled[s] and scrolled[s]['scroll']], 'corner_top': [head[s] and head[s]['corner']['top'], scrolled[s] and scrolled[s]['corner']['top']]} for s, name in sides})
    want = next((b for b in (before.get('blocks') or []) if b['top'] > (before.get('held') or 0) + 1), None)
    landed = want and next((b for b in (after.get('blocks') or []) if b['pos'] == want['pos']), None)
    r.check(bool(want) and bool(landed) and after.get('held', 0) > 0 and abs(landed['top'] - after['held']) <= 1,
            f'at a {SCENE_HEAD_PX} px window ↓ in pane A brings the next block\'s top to the foot of the head\'s held row, a pixel either way — never under it',
            {'held': [before.get('held'), after.get('held')], 'next': want, 'landed': landed})
    kept = {k: {s: v[s] and v[s]['pos'] for s in 'ab'} for k, v in firsts.items()}
    r.check(all(kept['run'][s] is not None and kept['wide'][s] == kept['run'][s] and kept['head'][s] == kept['run'][s] for s in 'ab'),
            f'the first block in view at the run\'s window is first in view at {SCENE_WIDE_PX} px and at {SCENE_HEAD_PX} px, below a held head\'s row: each refit keeps the reader\'s place', kept,
            xfail='#545')
    return {'window': {'run': [run['vw'], run['vh']], 'wide': [wide['vw'], wide['vh']], 'head': [head['vw'], head['vh']]},
            'characters': chars, 'corners': {k: [v[s] and v[s]['corner']['form'] for s, _ in sides] for k, v in windows},
            'character_px': run['a'] and run['a']['ch'], 'pane_px': sizes, 'opened': opened, 'first_in_view': kept, 'band_while_wide': band, 'reads_while_wide': reads}


def scene_holds(ctx, r):
    """THE READING SCENE's checks: opened on the first edition and the draft it windows, nothing held, then as a far end
    naming the draft whole, the window run held; its measure at the run's window and a wide one, its panes read and never
    clicked; then from the versions list of an edition with two members, its last paragraph held, read side by side with
    its latest member; its figures"""
    seen = {}
    ctx.leap(DOC, WINDOW[0])
    ctx.js('window.__skep.scene.open(%s, %s)' % (json.dumps(DOC), json.dumps(WINDOW[2])))
    ctx.settle()
    ctx.frames(3)
    v = scene_level(ctx)
    r.check(bool(v) and v['level']['a'] == WINDOW[0] and v['level']['b'] is not None, 'the scene on the window and its origin, nothing held: the ends set level are the window run\'s first position and its counterpart in the origin', v and v['level'])
    level_holds(r, 'the scene on the window and its origin', v)
    # the window run's band: both its ends at the lines set level, in view; every run a band
    ties = ctx.js('window.__skep.scene.ties()')
    seen['origin'] = {'level': v and v['level'], 'ties': ties_hold(r, 'the scene on the window and its origin', ties, 2),
                      'runs': every_run_banded(r, 'the scene on the window and its origin', v, ties), 'measured': ctx.js('window.__skep.scene.measured()')}
    ctx.js('window.__skep.scene.close()')
    ctx.frames(2)
    seen['whole'] = scene_whole_holds(ctx, r)
    seen['measure'] = scene_measure_holds(ctx, r)
    seen['marks'] = scene_marks_hold(ctx, r)
    # the versions list, a paragraph past the document's first held: "read side by side" with the latest member sets that paragraph level
    # with what the member holds of it. An edition no later case reads: the member's text, once loaded, stands over its document's box
    ctx.leap(VERSIONED, None)
    doc = ctx.js('window.__skep.model.doc(%s)' % json.dumps(VERSIONED))
    para = [b for b in doc['blocks'] if b['kind'] == 'para' and b['pos'] > 1 and not b['text'].startswith('#')][-1]
    ctx.js('window.__skep.cards.versions(%s, %d)' % (json.dumps(VERSIONED), para['pos']))
    ctx.settle()
    ctx.frames(2)
    rows = ctx.js('''[...document.querySelectorAll('#overlay .rows li:not(.head)')].map((li) => [...li.children].map((e) => { const q = e.getBoundingClientRect(); return {item: e.dataset.run || e.className, y: q.top, h: q.height}; }))''')
    split = [row for row in rows if len(row) < 3 or max(c['y'] for c in row) >= min(c['y'] + c['h'] for c in row)]
    r.check(len(rows) == doc['members'] and not split, 'the versions list: each member one row — its read act, its date, what it holds of the passage and its side-by-side act share one line', {'rows': rows, 'members': doc['members']})
    seen['versions_rows'] = [[round(c['y'], 1) for c in row] for row in rows]
    # each row's date (issue #22's design decision: "show each version's publish date on its row. Say 'published' once, at
    # the list's head"): the day the board's own `doc_metadata` of the member dates it, in the page's one form of a date
    ages = [ctx.daemon_op({'op': 'doc_metadata', 'doc': '%s.%d' % (VERSIONED, k)}) for k in range(1, (doc['members'] or 0) + 1)]
    dates = ctx.js('''(async (ages) => { const {dated, t} = await import("./strings.js");
      return {shown: [...document.querySelectorAll('#overlay .rows.versions li:not(.head)')].map((li) => { const d = li.querySelector('.date'); return d ? d.textContent : null; }),
              want: ages.map(dated), heads: [...document.querySelectorAll('#overlay .rows.versions li.head')].map((h) => h.textContent), published: t('F.published')}; })(%s)''' % json.dumps([{'at': a.get('at'), 'time': a.get('time'), 'from': a.get('time_from')} for a in ages]))
    r.check(bool(dates['shown']) and dates['shown'] == dates['want'] and dates['heads'] == [dates['published']],
            'the versions list: each row carries the day the board\'s own read of its member dates it, and "published" stands once, at the list\'s head (issue #22)',
            dict(dates, members=doc['members'], board=[{k: a.get(k) for k in ('at', 'time', 'time_from')} for a in ages]))
    seen['versions_dates'] = {'shown': dates['shown'], 'board': [a.get('time') for a in ages]}
    # the board ends this chain at its head (issue #184's design decision: "End proved"): the head's read act alone carries the
    # latest version's mark, a shape named in words, and no line stands at the list's open end
    head = ctx.js('''(async () => { const {t} = await import("./strings.js");
      return {marked: [...document.querySelectorAll('#overlay .rows.versions [data-run^="read"]')].map((b) => !!b.querySelector('.latest')),
              name: (document.querySelector('#overlay .rows.versions .latest') || {getAttribute: () => null}).getAttribute('aria-label'), want: t('L.versions.latest'),
              open: !!document.querySelector('#overlay .open-end')}; })()''')
    r.check(head['marked'] == [False] * (doc['members'] - 1) + [True] and head['name'] == head['want'] and not head['open'],
            'the versions list of a chain the board ended at its head: the head\'s read act alone carries the latest version\'s mark, named in words, and no line stands at the open end (issue #184)', dict(head, members=doc['members'], ended=doc.get('ended')))
    seen['versions_head'] = head
    ctx.js('document.querySelector(%s).click()' % json.dumps('#overlay [data-run="beside%d"]' % doc['members']))
    ctx.js('new Promise((res) => { const t0 = performance.now(); const tick = () => (window.__skep.scene.isOpen() || performance.now() - t0 > 10000 ? res(true) : setTimeout(tick, 50)); tick(); })')
    ctx.settle()
    ctx.frames(3)
    v = scene_level(ctx)
    # the counterpart, from the runs the scene reports: the first run that holds part of the paragraph, at the paragraph's first position it holds
    run = v and next((p for p in sorted(v['pairs'], key=lambda p: p['u1']) if p['u1'] < para['pos'] + para['width'] and para['pos'] < p['u1'] + p['width']), None)
    want = run and {'a': max(para['pos'], run['u1']), 'b': run['u2'] + max(para['pos'], run['u1']) - run['u1']}
    r.check(bool(v) and run is not None and want['a'] == para['pos'] and v['level'] == want, 'from the versions list, the paragraph held: the first pane\'s end is the held paragraph\'s first position, and the latest member\'s is its counterpart in the run that holds it, never the first pair\'s', {'level': v and v['level'], 'want': want})
    level_holds(r, 'the versions list\'s read side by side', v)
    # a member that holds all of its edition shares it as one run, from its first line above both panes: its band held at their visible tops
    ties = ctx.js('window.__skep.scene.ties()')
    seen['versions'] = {'level': v and v['level'], 'ties': ties_hold(r, 'the versions list\'s read side by side', ties, 0), 'runs': every_run_banded(r, 'the versions list\'s read side by side', v, ties)}
    # the version statement's click cue is the plane's corner's, whose act it is (K-57): a pane's corner is shown, not acted on
    corner = ctx.js('''(() => { const cue = (sel) => [...document.querySelectorAll(sel)].map((e) => { const s = getComputedStyle(e); return {cursor: s.cursor, line: s.textDecorationLine}; });
      return {pane: cue('.pane .corner .version'), plane: cue('#corners .corner .version')}; })()''')
    r.check(bool(corner['pane']) and all(c['cursor'] != 'pointer' and 'underline' not in c['line'] for c in corner['pane']), 'no click cue at a pane\'s corner: its version statement takes neither the pointer cursor nor the underline', corner['pane'])
    r.check(bool(corner['plane']) and all(c['cursor'] == 'pointer' and 'underline' in c['line'] for c in corner['plane']), 'the plane\'s corner keeps its version statement\'s click cue: the pointer cursor and the dotted underline', corner['plane'])
    pane_click_holds(ctx, r, 'the corner\'s version statement', '#sceneA .corner .version')
    seen['versions']['corner'] = corner
    ctx.js('window.__skep.scene.close()')
    ctx.frames(2)
    # back on the plane at the edition, its member's text loaded: the box both share holds one article, the version it shows
    # (issue #154's design decision: "The box shows one version") — at the plain address, the edition's
    ctx.leap(VERSIONED, None)
    member = '%s.%d' % (VERSIONED, doc['members'])
    mounted = ctx.js('window.__skep.mountedAddrs()')
    r.check([a for a in (VERSIONED, member) if a in mounted] == [VERSIONED], 'back on the plane at the edition\'s plain address after reading its latest member beside it, its box holds one article, the edition\'s, never the member\'s over it (issue #154)',
            {'mounted': mounted, 'shown': ctx.js('window.__skep.go.shownIn(%s)' % json.dumps(VERSIONED))})
    return seen


# the documents of the claimant's first grid that cite FAR_LEAP, which the plane draws: a scene on one and FAR_LEAP draws its citation
CITERS = ['1.0.1.0.4', '1.0.1.0.14', '1.0.1.0.20', BEAMED]


def scene_kept_holds(ctx, r):
    """A TIE IS MEASURED ON THE TEXT ITS PANES WERE SET WITH (issue #160's design decision: "no tie is ever drawn over text
    it was not measured on"): the scene on a citer of FAR_LEAP and FAR_LEAP, the citation drawn as a line between the
    panes, its end that names a document whole — FAR_LEAP, or the citer, whichever its slots name so — that whole
    document: the line meeting its pane's facing edge, and that edge drawn whole in the link's colour as the end, from
    the pane's visible top to its bottom, as the scene opens and with that pane scrolled (issue #59's design decision:
    "Wherever the reader scrolls, they stay inside it"); then, in one evaluation, the gate's door
    `model.invalidate` drops what the model held of both documents — their text and the citer's links, telling no
    reader — and the re-level act is clicked: the scene, told nothing, sets the two ends level at once and draws every
    line it drew, each end on the passage it stood on — the whole one still its pane's facing edge — at that passage's
    line in its pane or at the pane's edge where that line has left it. Both are read whole again and the scene ended
    after; its figures"""
    tried, lines, citer = [], [], None
    for c in CITERS:
        ctx.js('window.__skep.scene.open(%s, %s)' % (json.dumps(c), json.dumps(FAR_LEAP)))
        wait_for(ctx, 'window.__skep.scene.isOpen()')
        lines = [t for t in ctx.js('window.__skep.scene.ties()') if t['kind'] == 'link']
        tried.append([c, len(lines)])
        if lines:
            citer = c
            break
        ctx.js('window.__skep.scene.close()')
        ctx.frames(2)
    r.check(citer is not None, f'a scene on a citer of {FAR_LEAP} and {FAR_LEAP} draws its citation as a line between the panes', tried)
    if citer is None:
        return {'tried': tried}
    edged = whole_edges_hold(ctx, r, f'the scene on {citer} and {FAR_LEAP}', lines)
    torn = ctx.js('''((a, b) => { const S = window.__skep;
      S.model.invalidate(a); S.model.invalidate(b);
      document.querySelector('#scenebar [data-relevel]').click();
      return {links: S.model.doc(a).links.length, blocks: S.model.doc(b).blocks.length, updating: S.scene.updating(), ties: S.scene.ties()}; })(%s, %s)''' % (json.dumps(citer), json.dumps(FAR_LEAP)))
    after = [t for t in torn['ties'] if t['kind'] == 'link']
    ends = lambda ts: sorted((t['link'], t['a']['pos'], t['a']['width'], t['b']['pos'], t['b']['width']) for t in ts)
    r.check(torn['links'] == 0 and torn['blocks'] == 0 and not torn['updating'] and ends(after) == ends(lines),
            f'the model dropping what it held of {citer} and {FAR_LEAP}, while the scene stands told nothing: the re-level, clicked, sets the ends level at once and draws every line it drew, each end on the passage it stood on — the ties measured on the text and the links the panes were set with, never the model\'s now (issue #160)',
            {'links_now': torn['links'], 'far_blocks_now': torn['blocks'], 'updating': torn['updating'], 'before': ends(lines), 'after': ends(after)})
    figures = {'citer': citer, 'tried': tried, 'lines': ends(after), 'edges': edged, 'ties': ties_hold(r, f'the scene on {citer} and {FAR_LEAP}, the model dropping both', after, 1, band=False)}
    ctx.js('window.__skep.scene.close()')
    ctx.js('window.__skep.model.loadWhole(%s)' % json.dumps(citer))
    ctx.js('window.__skep.model.loadWhole(%s)' % json.dumps(FAR_LEAP))
    ctx.settle()
    ctx.frames(2)
    return figures


def wait_for(ctx, cond, s=10):
    """wait until a condition the page answers holds, `s` seconds at most — an act a click made is no promise the driver
    can await — then until the page settles"""
    ctx.js('new Promise((res) => { const t0 = performance.now(); const tick = () => ((%s) || performance.now() - t0 > %d ? res(true) : setTimeout(tick, 50)); tick(); })' % (cond, s * 1000))
    ctx.settle()
    ctx.frames(3)


def click_on(ctx, selector, text=None):
    """a person's click on the first element the selector names — the one whose text is `text`, where given — at its
    middle, dispatched at engine level; whether the element is what lies under the pointer there. None where no element
    answers"""
    at = ctx.js('''((sel, text) => { const e = [...document.querySelectorAll(sel)].find((x) => text == null || x.textContent === text); if (!e) return null;
      const q = e.getBoundingClientRect(), x = q.left + q.width / 2, y = q.top + q.height / 2, hit = document.elementFromPoint(x, y);
      return {x, y, hits: !!hit && (hit === e || e.contains(hit))}; })(%s, %s)''' % (json.dumps(selector), json.dumps(text)))
    if at:
        ctx.drv.mouse(at['x'], at['y'])
    return at


def lit_at(addr):
    """the page's condition: the arrival mark lit in `addr`"""
    return '(() => { const a = window.__skep.go.arrival(); return !!a && a.addr === %s; })()' % json.dumps(addr)


def arrival_holds(ctx, r, name, carried, stood=None):
    """the arrival a carried passage's landing lit (foundations §2.3's carry rule: "what of it the landing's text holds
    marked there"), or the light Back or Forward across the carry lit at the end it landed on (issue #152): no link
    named, the run it stands at holding the text of the stretch of the passage it re-projects —
    `carried`, the document and the positions [lo, hi) of that stretch, from the fixtures; outlined on its lines that
    stand, every rect it outlines inside the landing's article, the first line of the run it stands at — its line rect
    read from the article's own text, or, where the run's last line stands in no part, the line its first character
    opens, which the outline begins at — among them and inside the visible view below the one line, or, where the landing
    is made in place (a version move: issue #154's design decision, "the passage keeps its line on screen"), at `stood`,
    the line the passage's first line stood on before the move, DRIFT_TOL_PX either way; its figures"""
    a = ctx.js('window.__skep.arrivalAnchors()')
    doc, lo, hi = carried
    want = ctx.js('window.__skep.model.text(%s, %d, %d)' % (json.dumps(doc), lo, hi))
    at = next((x for x in (a or {}).get('runs') or [] if x['pos'] == a['pos']), None)
    got = ctx.js('window.__skep.model.text(%s, %d, %d)' % (json.dumps(a['addr']), at['pos'], at['pos'] + at['width'])) if at else None
    r.check(bool(a) and a['link'] is None and bool(want) and got == want, f'{name}: the landing marks the carried passage where the text landed in holds it — the run the arrival stands at holds the passage\'s own words, no link named',
            {'arrival': a and {k: a[k] for k in ('addr', 'pos', 'runs', 'link')}, 'want': want and want[:80], 'got': got and got[:80]})
    top = ctx.js("document.getElementById('line').getBoundingClientRect().bottom")
    vp = ctx.js('window.__skep.view.viewport()')
    view = {'x': 0, 'y': top, 'w': vp['VW'], 'h': vp['VH'] - top}
    outline, art = (a or {}).get('outline') or [], (a or {}).get('article')
    rects = lambda pos, width: [q for q in ctx.js('window.__skep.spanRects(%s, %d, %d)' % (json.dumps(a['addr']), pos, width)) or [] if q['w'] > 0 and q['h'] > 0]
    whole = rects(at['pos'], at['width']) if at else []
    first = whole[0] if whole else (next(iter(rects(at['pos'], 1)), None) if at else None)
    opens = (lambda o: rect_like(first, o)) if whole else (lambda o: all(abs(first[k] - o[k]) <= ANCHOR_TOL_PX for k in ('x', 'y', 'h')))
    where = (lambda q: inside(q, view)) if stood is None else (lambda q: abs(q['y'] - stood['y']) <= DRIFT_TOL_PX)
    r.check(bool(outline) and art is not None and all(inside(o, art) for o in outline) and first is not None and any(opens(o) for o in outline) and where(first),
            f'{name}: the arrival is outlined on its span\'s lines that stand, every one inside the landing\'s article, the first line of the run it stands at among them and '
            + ('inside the visible view' if stood is None else 'where the passage\'s first line stood before the move, which lands in place (issue #154)'),
            {'lines': len(outline), 'first': first, 'whole': bool(whole), 'article': art, 'view': view, 'stood': stood})
    return {'arrival': a and {k: a[k] for k in ('addr', 'pos', 'runs')}, 'lines': len(outline)}


def first_in_view(ctx, addr):
    """the first block of a mounted article, in its order, whose box meets the visible view below the one line — read
    here from the article's own elements, apart from the page's rule; None where none does"""
    return ctx.js('''((sel) => { const top = document.getElementById('line').getBoundingClientRect().bottom, p = window.__skep.view.viewport();
      const e = [...document.querySelectorAll(sel)].find((x) => { const q = x.getBoundingClientRect(); return q.width > 0 && q.height > 0 && q.bottom > top && q.top < p.VH && q.right > 0 && q.left < p.VW; });
      return e ? Number(e.dataset.pos) : null; })(%s)''' % json.dumps('#domlayer article[data-addr="%s"] .run > .sp' % addr))


def carried_holds(ctx, r):
    """THE CARRY's checks (foundations §2.3: every move from a passage to another arrangement of the same material
    carries it, re-projected at the landing and marked there; P43): the source act on the window paragraph's "who wrote
    this?" card, a click on the window run's key in its column's edge — Back from its landing lighting the run where the carry was made
    and Forward lighting it at the landing again (issue #152) — the latest member's read act in the versions list
    holding a paragraph, and in the list the corner's act opens with nothing selected, which holds the first span in
    view; the carry into a text that holds none of the passage faced at the landing; its figures"""
    seen = {}
    ctx.esc()
    ctx.leap(DOC, WINDOW[0])
    block = next(b for b in ctx.js('window.__skep.model.doc(%s).blocks' % json.dumps(DOC)) if b['pos'] <= WINDOW[0] < b['pos'] + b['width'])
    run = (max(block['pos'], WINDOW[0]), min(block['pos'] + block['width'], WINDOW[0] + WINDOW[1]))
    # the source act on the card: the paragraph holding the window run's start asked over whole, its stretch of the run marked in the source
    ctx.js('window.__skep.cards.wrote(%s, %d)' % (json.dumps(DOC), WINDOW[0]))
    ctx.settle()
    ctx.frames(2)
    at = click_on(ctx, '#overlay [data-run^="src"]', WINDOW[2])
    r.check(bool(at) and at['hits'], 'the "who wrote this?" card offers the window run\'s source, and it is what lies under the pointer', at)
    wait_for(ctx, lit_at(WINDOW[2]))
    seen['source_act'] = arrival_holds(ctx, r, 'the source act on "who wrote this?"', (DOC, run[0], run[1]))
    # a click on the window run's key heading its origin's statement in its column's edge: the whole run, marked in the
    # source (issue #304)
    ctx.leap(DOC, WINDOW[0])
    ctx.frames(2)
    key = '#corners .edge-sign[data-addr="%s"][data-origin="%s"] .src-key' % (DOC, WINDOW[2])
    at = click_on(ctx, key)
    r.check(bool(at) and at['hits'], 'the window run\'s key in its column\'s edge is what lies under the pointer', at)
    wait_for(ctx, lit_at(WINDOW[2]))
    seen['source_key'] = arrival_holds(ctx, r, 'a click on the window run\'s key', (DOC, WINDOW[0], WINDOW[0] + WINDOW[1]))
    land, line = ctx.js('window.__skep.go.landing()'), ctx.js('window.__skep.landingLine()')
    r.check(line is None and bool(land) and land['said'] is None, 'the window run carried whole into its source: all of it in one piece — the outline alone, no line (issue #153)',
            {'said': land and land['said'], 'line': line})
    # Back from the key's landing lights the run where the carry was made, in the first edition, and Forward lights it in
    # the draft again — each placed where its text holds the run's bytes now (issue #152)
    ctx.js('window.__skep.go.back()')
    wait_for(ctx, lit_at(DOC))
    seen['source_key_back'] = arrival_holds(ctx, r, 'Back from the key\'s landing (issue #152)', (DOC, WINDOW[0], WINDOW[0] + WINDOW[1]))
    ctx.js('window.__skep.go.forward()')
    wait_for(ctx, lit_at(WINDOW[2]))
    seen['source_key_forward'] = arrival_holds(ctx, r, 'Forward to the key\'s landing again (issue #152)', (DOC, WINDOW[0], WINDOW[0] + WINDOW[1]))
    # the versions list holding a paragraph: the latest member's read act marks it in the member
    ctx.leap(VERSIONED, None)
    doc = ctx.js('window.__skep.model.doc(%s)' % json.dumps(VERSIONED))
    member = '%s.%d' % (VERSIONED, doc['members'])
    para = next(b for b in doc['blocks'] if b['kind'] == 'para' and b['pos'] > 1 and not b['text'].startswith('#'))
    stood = line_of(ctx, VERSIONED, para['pos'])['line']
    ctx.js('window.__skep.cards.versions(%s, %d)' % (json.dumps(VERSIONED), para['pos']))
    ctx.settle()
    ctx.frames(2)
    at = click_on(ctx, '#overlay [data-run="read%d"]' % doc['members'])
    r.check(bool(at) and at['hits'], 'the versions list offers its latest member\'s read act, and it is what lies under the pointer', at)
    wait_for(ctx, lit_at(member))
    seen['versions_list'] = arrival_holds(ctx, r, 'the versions list\'s read act, a paragraph held', (VERSIONED, para['pos'], para['pos'] + para['width']), stood)
    # the corner's act with nothing selected, the edition's first blocks risen past the one line: the list holds the first
    # span in view (§2.3: "the selection, else the first span in view"), never the document's first block. The act is
    # taken by Enter at the version statement, the corner's stop (K-57), the platform activating its button as a click does
    ctx.leap(VERSIONED, None)
    rects = ctx.js('''[...document.querySelectorAll(%s)].map((e) => { const q = e.getBoundingClientRect(); return {pos: Number(e.dataset.pos), bottom: q.bottom, left: q.left}; })''' % json.dumps('#domlayer article[data-addr="%s"] .run > .sp' % VERSIONED))
    line = ctx.js("document.getElementById('line').getBoundingClientRect().bottom")
    # the blocks standing in the article's first column, down it: the ones the view rises past
    col = [x for x in rects if abs(x['left'] - rects[0]['left']) <= 0.5] if rects else []
    last = col[-1]['pos'] if col else None
    above = [x for x in col if x['pos'] < (last or 0)]
    cam = ctx.camera()
    if above:
        ctx.set_view(cam['x'], cam['y'] + (above[-1]['bottom'] - line + 12) / cam['scale'], cam['scale'])
    held = first_in_view(ctx, VERSIONED)
    stood = line_of(ctx, VERSIONED, held)['line'] if held is not None else None
    sel = ctx.js('window.__skep.selection()')
    r.check(held is not None and held != doc['blocks'][0]['pos'] and not (sel and sel['addr'] in (VERSIONED, member)), 'the edition viewed with its first blocks risen past the one line, nothing selected in it: the first span in view is a later paragraph', {'first_in_view': held, 'selection': sel})
    ctx.js('document.getElementById("walk-" + window.__skep.mirror.index()).focus({preventScroll: true})')
    ctx.frames(1)
    ctx.drv.key('Tab')
    ctx.frames(2)
    on = ctx.js('''(() => { const e = document.activeElement, c = e && e.closest ? e.closest('#corners [data-corner]') : null;
      return c ? {corner: c.dataset.corner || null, act: e !== c && e.tagName === 'BUTTON' ? e.className.split(' ')[0] : null} : null; })()''')
    r.check(on == {'corner': VERSIONED, 'act': 'version'}, 'Tab from the plane\'s stop reaches the edition\'s corner on its version statement, the corner\'s stop (K-57)', on)
    ctx.drv.key('Enter')
    wait_for(ctx, 'document.querySelector(%s) !== null' % json.dumps('#overlay [data-run="read%d"]' % doc['members']))
    at = click_on(ctx, '#overlay [data-run="read%d"]' % doc['members'])
    r.check(bool(at) and at['hits'], 'the list the corner\'s act opens offers the latest member\'s read act, and it is what lies under the pointer', at)
    wait_for(ctx, lit_at(member))
    b = next((x for x in doc['blocks'] if x['pos'] == held), None)
    seen['corner'] = dict(arrival_holds(ctx, r, 'the corner\'s list, nothing selected', (VERSIONED, b['pos'], b['pos'] + b['width']) if b else (VERSIONED, 0, 0), stood), first_in_view=held)
    # the carry into a text that holds none of the passage: the first edition's opening paragraph carried into the draft
    # it windows — the landing at the draft's first block, unmarked, faced in the dead end's words with no act
    own = next(x for x in ctx.js('window.__skep.model.doc(%s).blocks' % json.dumps(DOC)) if x['kind'] == 'para' and x['pos'] + x['width'] <= WINDOW[0])
    ctx.js('window.__skep.go.leapTo(%s, null, %s)' % (json.dumps(WINDOW[2]), json.dumps({'carry': {'addr': DOC, 'pos': own['pos'], 'width': own['width']}})))
    ctx.settle()
    ctx.frames(2)
    words = ctx.js('import("./strings.js").then(({t}) => t("F.floating", {D: %s}))' % json.dumps(WINDOW[2]))
    face, entry = ctx.overlay_shown(), ctx.js('(() => { const t = window.__skep.trail(); return t.entries[t.cursor]; })()')
    first = ctx.js('window.__skep.model.doc(%s).blocks[0].pos' % json.dumps(WINDOW[2]))
    r.check(ctx.js('window.__skep.go.arrival()') is None and entry['addr'] == WINDOW[2] and entry['pos'] == first and ctx.js('window.__skep.overlay().id') == 'face:floating' and words in face['text'] and face['acts'] == 0,
            'a carried passage the text landed in holds none of: the landing at its first block, unmarked, faced "its passage is not in ⟨D⟩\'s current text" with no act',
            {'arrival': ctx.js('window.__skep.go.arrival()'), 'entry': {k: entry[k] for k in ('addr', 'pos', 'width')}, 'first_block': first, 'face': face, 'want': words})
    seen['empty'] = {'carried': [own['pos'], own['width']], 'landing': entry['pos'], 'face': face['text'][:80]}
    ctx.esc()
    seen['part'] = part_holds(ctx, r)
    return seen


def part_holds(ctx, r):
    """THE LINE's checks (issue #153's design decision: "Mark what's held and say the rest in a line"): a passage straddling
    the window run's start — the first edition's PART_LEAD positions before it and as many of the run's — carried into the
    draft the run windows, which holds the run's half of it alone: the arrival outlined on that half, its words the run's;
    the landing's state part, the line that stands led by "Only part of the text you were reading is in ⟨D⟩'s current
    text", offering to read it side by side with the first edition, which holds it whole, and no version — the draft has
    none; standing at the text's edge beside the landing — past the right edge of the outline's first line, its top that
    line's — inside the visible view below the one line, meeting no line of the outline and not the overlay; the next act
    takes it down — the next landing; its figures"""
    ctx.leap(DOC, WINDOW[0])
    lo = WINDOW[0] - PART_LEAD
    ctx.js('window.__skep.go.leapTo(%s, null, %s)' % (json.dumps(WINDOW[2]), json.dumps({'carry': {'addr': DOC, 'pos': lo, 'width': 2 * PART_LEAD}})))
    wait_for(ctx, lit_at(WINDOW[2]))
    held = arrival_holds(ctx, r, 'a passage the draft holds part of (issue #153)', (DOC, WINDOW[0], WINDOW[0] + PART_LEAD))
    land, line = ctx.js('window.__skep.go.landing()'), ctx.js('window.__skep.landingLine()')
    words = ctx.js('import("./strings.js").then(({t, opening}) => opening("L.held.part", {subject: t("L.held.reading"), where: t("L.held.current", {D: %s})}))' % json.dumps(WINDOW[2]))
    said = (land or {}).get('said') or {}
    r.check(said.get('state') == 'part' and bool(line) and bool(words) and line['words'].startswith(words) and not line['covered'] and line['acts'] == ['beside'],
            'the landing says only part of the passage carried is in the draft, in a line that stands — its sentences opening "Only part of the text you were reading is in ⟨D⟩\'s current text" — offering it side by side with the first edition (issue #153; style S1)',
            {'said': said, 'line': line, 'want': words})
    top = ctx.js("document.getElementById('line').getBoundingClientRect().bottom")
    vp = ctx.js('window.__skep.view.viewport()')
    view = {'x': 0, 'y': top, 'w': vp['VW'], 'h': vp['VH'] - top}
    a = ctx.js('window.__skep.arrivalAnchors()') or {}
    outline = a.get('outline') or []
    first = next(iter([q for q in ctx.js('window.__skep.spanRects(%s, %d, 1)' % (json.dumps(a.get('addr') or WINDOW[2]), a.get('pos') or 0)) or [] if q['w'] > 0 and q['h'] > 0]), None)
    over = ctx.js('(() => { const o = document.getElementById("overlay"); if (!o.classList.contains("on")) return null; const q = o.getBoundingClientRect(); return {x: q.left, y: q.top, w: q.width, h: q.height}; })()')
    rect = (line or {}).get('rect')
    beside = bool(rect) and bool(first) and bool(outline) and rect['x'] >= max(o['x'] + o['w'] for o in outline if abs(o['y'] - first['y']) <= ANCHOR_TOL_PX + 1) - ANCHOR_TOL_PX and abs(rect['y'] - first['y']) <= ANCHOR_TOL_PX + 1
    r.check(beside and inside(rect, view) and not any(meets(rect, o) for o in outline) and not (over and meets(rect, over)),
            'the line stands at the text\'s edge beside the landing, its top the first held line\'s, inside the visible view, meeting no line of the outline and not the overlay (issue #153)',
            {'line': rect, 'first': first, 'outline': outline[:4], 'overlay': over, 'view': view})
    ctx.leap(DOC, WINDOW[0])
    gone = ctx.js('window.__skep.landingLine()')
    r.check(gone is None, 'the next landing takes the line down with the outline (issue #153)', gone)
    return {'held': held, 'said': said, 'line': rect}


def pieces_view(ctx, addr):
    """an arrival as the page shows it: its runs and the run the landing stands at, by index (`go.landing`), the line as it
    stands — its words, its acts, its rect and the labels set for the other runs (`landingLine`) — the outline the canvas drew,
    each rect with the run it outlines (`arrivalAnchors`), the mirror's descriptions (`go.described`), the visible view below
    the one line, the camera, the em `addr` stands at, and the trail's cursor and length"""
    return ctx.js('''((a) => { const S = window.__skep, l = S.go.landing(), m = S.arrivalAnchors(), t = S.trail(), c = S.view.camera(), p = S.view.viewport();
      const top = document.getElementById('line').getBoundingClientRect().bottom;
      return {landing: l && {addr: l.addr, pos: l.pos, current: l.current, runs: l.pieces ? l.pieces.runs.map((r) => ({pos: r.pos, width: r.width, piece: r.piece})) : null},
              runs: m && m.runs, outline: m ? m.outline : [], line: S.landingLine(), described: S.go.described(),
              view: {x: 0, y: top, w: p.VW, h: p.VH - top}, camera: c, em: S.fold(a).fs * c.scale, cursor: t.cursor, entries: t.entries.length}; })(%s)''' % json.dumps(addr))


def passage_of(ctx, addr, runs):
    """the passage two runs of a text's own bytes hold, by identity — from the first's first byte to the second's last, where
    the text's held image places both in one I-space, in its order — read by the page's identity hook; None where it does not"""
    ids = [ctx.js('window.__skep.model.identity(%s, %d, %d)' % (json.dumps(addr), x['pos'], x['width'])) or [] for x in runs]
    if not all(ids) or len({i['prefix'] for xs in ids for i in xs}) != 1 or ids[1][0]['ordinal'] <= ids[0][-1]['ordinal']:
        return None
    return {'prefix': ids[0][0]['prefix'], 'ordinal': ids[0][0]['ordinal'], 'width': ids[1][-1]['ordinal'] + ids[1][-1]['width'] - ids[0][0]['ordinal']}


def pieces_hold(ctx, r):
    """THE RUNS (issue #158's design decision; FP-21), at 1440 × 900 and at NARROW_PX: the longest edition's first paragraph's
    head and its last's — farther apart than a view — landed in through the gate's door naming the two runs and the passage
    they hold by identity: the landing at piece 1, its line "piece 1 of 2 · only part of the passage" with the step's acts
    first, the mirror's descriptions every run's label; both runs outlined — the second out of the visible view too — and
    both again with the edition framed whole below its reading scale; Mod+G steps to piece 2 at the reading size, its line in
    view, the line its label, both runs still outlined and the trail untouched; one Mod+[ returns where the door was made, at
    its view; Mod+] reads the arrival again from the text it reaches (issue #297), and the edition holds the passage the door
    named whole — its bytes run unbroken from the first run to the second's end — so its one piece stands outlined alone,
    at the view the reader left, the walk on the line they left it on. Then two runs of the first edition both in view: the other
    run's label at the text's edge beside its first line, inside the visible view, meeting no outlined line and not the line;
    its figures"""
    seen = {}
    longest, _, _ = ctx.longest_edition()
    r.check(longest is not None, 'the runs: the longest edition the claimant\'s index lists')
    if longest is None:
        return seen
    words = ctx.js('import("./strings.js").then(({t}) => ({one: t("L.piece", {k: 1, n: 2}), two: t("L.piece", {k: 2, n: 2}), part: t("L.piece.part")}))')
    mine = lambda k, view: [o for o in view['outline'] if o.get('run') == k]
    for size in ((1440, 900), (NARROW_PX, 700)):
        name = '%d × %d' % size
        was = ctx.resize(*size)
        ctx.leap(longest)
        paras = [b for b in ctx.js('window.__skep.model.doc(%s).blocks' % json.dumps(longest)) if b['kind'] == 'para' and b['width'] > 24 and not b['text'].startswith('#')]
        runs = [{'pos': paras[0]['pos'], 'width': 12}, {'pos': paras[-1]['pos'], 'width': 12}] if len(paras) > 1 else []
        passage = passage_of(ctx, longest, runs) if runs else None
        r.check(passage is not None, f'the runs, {name}: two runs of the longest edition\'s own bytes, its first paragraph\'s head and its last\'s', {'runs': runs, 'passage': passage})
        if passage is None:
            ctx.resize(*was)
            continue
        departed, view0 = ctx.js('window.__skep.trail().cursor'), ctx.camera()
        ctx.js('window.__skep.go.leapTo(%s, %d, %s)' % (json.dumps(longest), runs[0]['pos'], json.dumps({'runs': runs, 'passage': passage})))
        ctx.settle()
        ctx.frames(3)
        v = pieces_view(ctx, longest)
        land, line = v['landing'] or {}, v['line'] or {}
        r.check(land.get('current') == 0 and [x['piece'] for x in land.get('runs') or []] == [1, 2] and line.get('words') == words['one'] + ' · ' + words['part'] and (line.get('acts') or [])[:2] == ['next', 'previous'],
                f'the runs, {name}: the landing at piece 1, its line "piece 1 of 2 · only part of the passage", the step\'s acts first', {'landing': land, 'line': line})
        r.check([x['words'] for x in (v['described'] or {}).get('runs') or []] == [words['one'], words['two']], f'the runs, {name}: every run\'s label its item\'s description in the mirror', v['described'])
        r.check(bool(mine(0, v)) and bool(mine(1, v)) and all(inside(o, v['view']) for o in mine(0, v)) and not any(meets(o, v['view']) for o in mine(1, v)),
                f'the runs, {name}: both outlined at the landing — piece 1 in the visible view, piece 2 out of it, farther than a view away, outlined all the same',
                {'piece1': mine(0, v)[:3], 'piece2': mine(1, v)[:3], 'view': v['view']})
        # the edition framed whole below its reading scale: both runs outlined in view
        f, vp = ctx.js('window.__skep.fold(%s)' % json.dumps(longest)), ctx.js('window.__skep.view.viewport()')
        o = f['outline']
        ctx.set_view(o['x'] + o['w'] / 2, o['y'] + o['h'] / 2, 0.85 * min(vp['VW'] / o['w'], v['view']['h'] / o['h']))
        far = pieces_view(ctx, longest)
        r.check(far['em'] < 8 and bool(mine(0, far)) and bool(mine(1, far)) and all(meets(q, far['view']) for q in mine(0, far) + mine(1, far)),
                f'the runs, {name}: the edition framed whole at its em {far["em"]:.2f}, below its reading scale: both runs outlined in view (issue #158: "Zooming out then shows all of them")',
                {'em': far['em'], 'piece1': mine(0, far)[:2], 'piece2': mine(1, far)[:2]})
        ctx.set_view(v['camera']['x'], v['camera']['y'], v['camera']['scale'])
        # the step: Mod+G
        ctx.drv.key('g', mods=('Meta',))
        ctx.settle()
        ctx.frames(3)
        s = pieces_view(ctx, longest)
        sl = s['line'] or {}
        r.check((s['landing'] or {}).get('current') == 1 and sl.get('words') == words['two'] + ' · ' + words['part'] and abs(s['em'] - READING_PX) < 1e-3
                and bool(mine(1, s)) and any(inside(q, s['view']) for q in mine(1, s)) and bool(mine(0, s)) and (s['cursor'], s['entries']) == (v['cursor'], v['entries']),
                f'the runs, {name}: Mod+G steps to piece 2 — the camera there at the reading size, its line in view, the line its label, both runs still outlined, the trail untouched',
                {'landing': s['landing'], 'line': sl.get('words'), 'em': s['em'], 'piece2': mine(1, s)[:2], 'trail': [s['cursor'], s['entries'], v['cursor'], v['entries']]})
        # one Back: where the door was made
        ctx.drv.key('[', code='BracketLeft', mods=('Meta',))
        ctx.settle()
        ctx.frames(3)
        b = pieces_view(ctx, longest)
        r.check(b['cursor'] == departed and same_view(b['camera'], view0), f'the runs, {name}: one Mod+[ returns to where the reader departed, at the view they left', {'cursor': [b['cursor'], departed], 'camera': [b['camera'], view0]})
        ctx.drv.key(']', code='BracketRight', mods=('Meta',))
        ctx.settle()
        ctx.frames(3)
        fw = pieces_view(ctx, longest)
        whole = [{'pos': runs[0]['pos'], 'width': runs[1]['pos'] + runs[1]['width'] - runs[0]['pos']}]
        walk = ctx.js('window.__skep.view.focus()') or {}
        r.check(fw['runs'] == whole and fw['line'] is None and (fw['landing'] or {}).get('runs') is None and bool(mine(0, fw)) and not mine(1, fw)
                and same_view(fw['camera'], s['camera']) and (walk.get('kind'), walk.get('pos')) == ('block', runs[1]['pos']),
                f'the runs, {name}: Mod+] reads the arrival again from the text it reaches — the passage the door named, every byte from the first run to the end of the second, stands whole there: its one piece outlined alone, no labels and no line — the camera at the view the reader left and the walk on the line they left it on (issue #297)',
                {'runs': fw['runs'], 'want': whole, 'landing': fw['landing'], 'line': (fw['line'] or {}).get('words'), 'camera': [fw['camera'], s['camera']], 'walk': walk})
        seen[name] = {'doc': longest, 'runs': runs, 'stepped_em': round(s['em'], 3), 'framed_em': round(far['em'], 3)}
        ctx.resize(*was)
    # two runs both in view, in the first edition's own bytes before its window run, their first lines in one column four body
    # lines apart or more, so the label beside the second never stacks with the line beside the first (O-LAND's `stacks`):
    # the other run's label at the text's edge
    ctx.leap(DOC, None)
    paras = [b for b in ctx.js('window.__skep.model.doc(%s).blocks' % json.dumps(DOC)) if b['kind'] == 'para' and b['width'] > 24 and b['pos'] + 12 < WINDOW[0]]
    fs = ctx.js('window.__skep.fold(%s).fs' % json.dumps(DOC))
    lined = [(b, ctx.js('window.__skep.centreOf(%s, %d)' % (json.dumps(DOC), b['pos']))) for b in paras]
    apart = next((b for b, c in lined[1:] if abs(c['x'] - lined[0][1]['x']) < 1e-6 and c['y'] - lined[0][1]['y'] >= 4 * LINE_RATIO * fs), None) if lined else None
    runs = [{'pos': paras[0]['pos'], 'width': 12}, {'pos': apart['pos'], 'width': 12}] if apart else []
    passage = passage_of(ctx, DOC, runs) if runs else None
    r.check(passage is not None, 'the runs in view: two typed lines of the first edition\'s own bytes, their first lines in one column four body lines apart or more', {'runs': runs})
    if passage is not None:
        ctx.js('window.__skep.go.leapTo(%s, %d, %s)' % (json.dumps(DOC), runs[0]['pos'], json.dumps({'runs': runs, 'passage': passage})))
        ctx.settle()
        ctx.frames(3)
        v = pieces_view(ctx, DOC)
        line = v['line'] or {}
        labels = line.get('labels') or []
        first = next(iter([q for q in ctx.js('window.__skep.spanRects(%s, %d, 1)' % (json.dumps(DOC), runs[1]['pos'])) or [] if q['w'] > 0 and q['h'] > 0]), None)
        lab = labels[0] if len(labels) == 1 else None
        edge = max((o['x'] + o['w'] for o in mine(1, v) if first and abs(o['y'] - first['y']) <= ANCHOR_TOL_PX + 1), default=None)
        r.check(bool(lab) and lab['runs'] == [1] and lab['words'] == words['two'] and bool(first) and edge is not None and lab['rect']['x'] >= edge - ANCHOR_TOL_PX
                and abs(lab['rect']['y'] - first['y']) <= ANCHOR_TOL_PX + 1 and inside(lab['rect'], v['view']) and not any(meets(lab['rect'], q) for q in v['outline']) and not meets(lab['rect'], line['rect']),
                'the runs in view: piece 2\'s label, "piece 2 of 2", at the text\'s edge level with its first line, past the text, inside the visible view, meeting no outlined line and not the line',
                {'labels': labels, 'first': first, 'edge': edge, 'line': line.get('rect')})
        seen['in_view'] = {'runs': runs, 'labels': labels}
    ctx.leap(DOC, WINDOW[0])
    return seen


def box_of(ctx, addr):
    """a document's box as the page stands: the version it shows (N-GO's `shownIn`), the articles and the corners standing in
    it, the version statement of the corner of the version shown, the one line's address and its version marker, the walk,
    the camera, the band and the trail"""
    return ctx.js('''((a) => { const S = window.__skep, ours = (x) => x === a || x.startsWith(a + '.'), shown = S.go.shownIn(a), f = S.view.focus();
      const v = document.querySelector(`#corners [data-corner="${shown}"] .version`), m = document.querySelector('#line .marker');
      return {shown, mounted: S.mountedAddrs().filter(ours), corners: [...document.querySelectorAll('#corners [data-corner]')].map((e) => e.dataset.corner).filter(ours),
              version: v ? v.textContent : null, address: S.line().address, marker: m ? {lit: m.classList.contains('lit'), title: m.title} : null,
              focus: f && {kind: f.kind, addr: f.addr, pos: f.pos}, cam: S.view.camera(), lod: S.view.lod().name, trail: S.trail()}; })(%s)''' % json.dumps(addr))


def line_of(ctx, addr, pos):
    """the first line rect on screen of the text at a position of a document's mounted article — at a byte the article
    sets no glyph for (a block's separator), the line of the last character before it, the line that holds the position —
    and the article's em on screen"""
    return ctx.js('''((a, p) => { const S = window.__skep, m = S.mounted(a), rect = (k) => (S.spanRects(a, k, 1) || []).find((x) => x.w > 0 && x.h > 0) || null;
      let q = null; for (let k = p; !q && k >= Math.max(1, p - 16); k--) q = rect(k);
      return {line: q, em: m ? m.fs * S.view.camera().scale : null}; })(%s, %d)''' % (json.dumps(addr), pos))


# every frame from here on sampled until stopped: how many were drawn, and in how many the camera flew
FLY = '''(() => { const g = window.__gateFly = {frames: 0, flew: 0, stop: false};
  const tick = () => { if (g.stop) return; g.frames++; if (window.__skep.view.flying()) g.flew++; requestAnimationFrame(tick); }; requestAnimationFrame(tick); })()'''
FLOWN = '(() => { window.__gateFly.stop = true; return {frames: window.__gateFly.frames, flew: window.__gateFly.flew}; })()'


def same_view(a, b):
    """two cameras alike, a millionth either way"""
    return all(abs(a[k] - b[k]) <= 1e-6 * max(1.0, abs(b[k])) for k in ('x', 'y', 'scale'))


def lacking_of(ctx, addr, member):
    """the first stretch of a document's text a version of it holds none of, and the position in that version the page's
    rule keeps its line at (SC's `nearest`): the end of the shared stretch before it, else the start of the one after it,
    the nearer to the stretch's start, the one before on a tie — decided here from the harness's own reads of the board
    (each one's extent, and `compare` of the two whole), apart from the page's; None where the version holds all of it"""
    def extent(a):
        ans = ctx.daemon_op({'op': 'retrieve_doc_v_span_set', 'doc': a})
        return next((int(x['width'].split('.')[-1]) for x in ans.get('set') or [] if x['start'].startswith('1.')), None)
    e0, e1 = extent(addr), extent(member)
    if not e0 or not e1:
        return None
    ans = ctx.daemon_op({'op': 'compare', 'rho1': [{'doc': addr, 'spans': [{'start': '1.1', 'width': '0.%d' % e0}]}], 'rho2': [{'doc': member, 'spans': [{'start': '1.1', 'width': '0.%d' % e1}]}]})
    pairs = sorted((int(p['u1']['ordinal']), int(p['u2']['ordinal']), int(p['width'])) for p in ans.get('pairs') or [] if p['u1']['subspace'] == '1' and p['u2']['subspace'] == '1')
    at, gap = 1, None
    for u1, _, w in pairs:
        if u1 > at:
            gap = (at, u1)
            break
        at = max(at, u1 + w)
    if gap is None and at <= e0:
        gap = (at, e0 + 1)
    if gap is None:
        return None
    lo, hi = gap
    before = next(((u2 + lo - 1 - u1, 1) for u1, u2, w in pairs if u1 <= lo - 1 < u1 + w), None)
    after = next(((u2, hi - lo) for u1, u2, w in pairs if u1 >= hi), None)
    near = min((c for c in (before, after) if c), key=lambda c: c[1], default=None)
    return {'lo': lo, 'hi': hi, 'at': near[0] if near else 1, 'pairs': len(pairs)}


def passage_at(doc, at, n):
    """a passage of a document's held text: `n` bytes from the start of the first word past position `at`, inside the
    block holding it — its block, its position and its width; None where no such block or word stands"""
    for b in doc['blocks']:
        if b['kind'] != 'para' or not (b['pos'] <= at < b['pos'] + b['width']):
            continue
        text, c = b['text'], 0
        while c < len(b['text']) and len(text[:c].encode('utf8')) < at - b['pos']:
            c += 1
        j = text.find(' ', c) + 1
        if j <= 0 or len(text[j:].encode('utf8')) < n:
            return None
        pos = b['pos'] + len(text[:j].encode('utf8'))
        return {'block': b['pos'], 'pos': pos, 'width': len(text[j:].encode('utf8')[:n].decode('utf8', 'ignore').encode('utf8'))}
    return None


def version_holds(ctx, r):
    """THE VERSION MOVE (issue #154's design decision: "Version moves land in place"; "The box shows one version"): the
    edition with two members at its plain address, its box showing its trunk head; then
    (a) the versions list holding a passage both versions hold, version 1's read act pressed: no frame flies, the
    passage's first line stands at the height it stood at on screen, at its em, in version 1's text; the box shows version 1 alone —
    its article and its corner, the corner reading "version 1 of n" — the one line naming the version's address, its marker
    lit, and the trail one entry on, at the passage's counterpart; the list standing through the move, read again at
    version 1, its read act the current one;
    (b) Mod+- until mid scale, the box's article down: it still shows version 1, its one label the version's address past the region's prefix,
    the mirror listing the box once, by the version; its history strip marking every member the model counted, version 1
    held in the window mark, closed at both ends — its edges and member 1's tick in their own colours on the canvas as
    drawn — and the last member in the head's triangle where the board ended the chain there (issue #241); Mod+= as many
    times back: the box, the line and the camera as they were, the trail unmoved;
    (c) Mod+[: the trunk head again, its article and corner alone, at the view the move left, the passage's line where it
    stood, the marker unlit; Mod+]: version 1 again, at the view Back left; then a click on the box at mid scale, as a
    person clicks a document there: the teleport lands in version 1, the box still pinned;
    (d) the first stretch of the trunk's text version 1 holds none of — decided from the harness's own reads of the board —
    held by the list and version 1's read act pressed: the box shows version 1, nothing outlined, the list standing and
    the dead end's face below it saying the passage is not in version 1, and the line holding the counterpart of the nearest shared position stands
    where the stretch's first line stood; unmeasured where version 1 holds all of the trunk's text.
    The edition is left at its plain address; its figures"""
    seen = {}
    m1 = VERSIONED + '.1'
    ctx.esc()
    ctx.leap(VERSIONED, None)
    doc = ctx.js('window.__skep.model.doc(%s)' % json.dumps(VERSIONED))
    n = doc['members'] or 0
    at0 = box_of(ctx, VERSIONED)
    r.check(n >= 2 and at0['shown'] == VERSIONED and at0['mounted'] == [VERSIONED] and at0['corners'] == [VERSIONED] and bool(at0['marker']) and not at0['marker']['lit'],
            'the edition at its plain address: its box shows the trunk head, the edition\'s article and corner alone, the one line\'s version marker unlit (issue #154)',
            {k: at0[k] for k in ('shown', 'mounted', 'corners', 'marker')} | {'members': n})
    # (a) in place: a passage both versions hold — forty bytes from the word that starts past the trunk's six hundredth
    # position, inside its block
    para = passage_at(doc, 600, 40)
    r.check(para is not None, 'the edition holds a passage of forty bytes past its six hundredth position, for the version move', [[b['pos'], b['width']] for b in doc['blocks']][:20])
    if para is None:
        return seen
    ctx.view_at(VERSIONED, para['pos'])
    before, cam0, t0 = line_of(ctx, VERSIONED, para['pos']), ctx.camera(), ctx.js('window.__skep.trail()')
    ctx.js('window.__skep.cards.versions(%s, %d, %d)' % (json.dumps(VERSIONED), para['pos'], para['width']))
    wait_for(ctx, 'document.querySelector(%s) !== null' % json.dumps('#overlay [data-run="read1"]'))
    ctx.js(FLY)
    at = click_on(ctx, '#overlay [data-run="read1"]')
    wait_for(ctx, lit_at(m1))
    ctx.frames(3)
    fly = ctx.js(FLOWN)
    a = ctx.js('window.__skep.go.arrival()')
    after = line_of(ctx, m1, a['pos']) if a else None
    words = lambda addr, pos: ctx.js('window.__skep.model.text(%s, %d, %d)' % (json.dumps(addr), pos, pos + 40))
    at1 = box_of(ctx, VERSIONED)
    newest = at1['trail']['entries'][at1['trail']['cursor']]
    r.check(bool(at) and at['hits'], 'the versions list holding the passage offers version 1\'s read act, and it is what lies under the pointer', at)
    r.check(fly['frames'] > 0 and fly['flew'] == 0, 'version 1\'s read act lands in place: no frame of the move flies (issue #154)', fly)
    kept = bool(a) and a['addr'] == m1 and bool(before['line']) and bool(after and after['line']) and words(m1, a['pos']) == words(VERSIONED, para['pos'])
    r.check(kept and abs(after['line']['y'] - before['line']['y']) <= DRIFT_TOL_PX and abs(after['em'] - before['em']) <= 1e-6 * before['em'],
            f'the passage keeps its line on screen: its first line in version 1\'s text — the same words — stands at the height it stood at in the trunk head\'s, {DRIFT_TOL_PX} px either way, at its em (issue #154)',
            {'arrival': a and {k: a[k] for k in ('addr', 'pos')}, 'before': before, 'after': after, 'words': [words(VERSIONED, para['pos']), a and words(m1, a['pos'])]})
    r.check(at1['shown'] == m1 and at1['mounted'] == [m1] and at1['corners'] == [m1] and at1['version'] == ctx.js('import("./strings.js").then(({t}) => t("F.version-of", {k: 1, n: %d}))' % n),
            'the box shows version 1 alone: its article and its corner, which reads "version 1 of %d" (issue #154)' % n, {k: at1[k] for k in ('shown', 'mounted', 'corners', 'version')})
    title = ctx.js('import("./strings.js").then(({t}) => t("L.version", {k: 1}))')
    r.check(at1['address']['doc'] == m1 and at1['address']['text'].split(' › ')[:3] == ['1', '1.0.1', m1] and at1['marker'] == {'lit': True, 'title': title},
            'the one line names the version\'s address, its version marker lit (issue #154; foundations §3.2)', {'address': at1['address'], 'marker': at1['marker']})
    r.check(at1['trail']['cursor'] == t0['cursor'] + 1 and newest['addr'] == m1 and bool(a) and newest['pos'] == a['pos'],
            'the move takes one trail entry, at the passage\'s counterpart in version 1 (issue #154)', {'cursor': [t0['cursor'], at1['trail']['cursor']], 'newest': {k: newest.get(k) for k in ('addr', 'pos')}})
    ctx.settle()
    ctx.frames(2)
    listed = ctx.js('''(() => { const o = window.__skep.overlay(), b = document.querySelector('#overlay [data-run="read1"]');
      return {id: o.id, notice: o.notice ? o.notice.id : null, current: b ? b.getAttribute('aria-current') : null}; })()''')
    r.check(listed['id'] == 'versions:' + VERSIONED and listed['current'] == 'true' and listed['notice'] is None,
            'the versions list stands through the move, read again at version 1 — its read act the current one — with no face left below it (issue #266)', listed)
    seen['in_place'] = {'para': para['pos'], 'counterpart': a and a['pos'], 'fly': fly, 'line': [before['line'], after and after['line']], 'list': listed}
    # (b) zoomed out to mid scale, the box drawn on the canvas, its article down, and in again: the version stands
    ctx.esc()
    ours = lambda x: x == VERSIONED or x.startswith(VERSIONED + '.')
    drawn = lambda: ctx.js('window.__skep.view.lod().name') == 'mid' and not [x for x in ctx.js('window.__skep.mountedAddrs()') if ours(x)]
    out = 0
    while out < 14 and not drawn():
        ctx.drv.key('-', code='Minus', mods=('Meta',))
        ctx.settle()
        ctx.frames(2)
        out += 1
    ctx.frames(3)
    mid = box_of(ctx, VERSIONED)
    labels = [l for l in ctx.js('window.__skep.labels()') if l['kind'] == 'doc' and ours(l['place'])]
    left = [o for o in ctx.js('window.__skep.labelsLeftOut()') if o['kind'] == 'doc' and ours(o['place'])]
    sibs = [s['addr'] for s in ctx.js('window.__skep.mirror.siblings()') if s['addr'] and ours(s['addr'])]
    r.check(mid['lod'] == 'mid' and mid['shown'] == m1 and mid['trail']['cursor'] == at1['trail']['cursor'] and len(mid['trail']['entries']) == len(at1['trail']['entries']),
            'Mod+- until mid scale, the box drawn on the canvas: it still shows version 1, and the trail does not move — a zoom changes no box\'s version (issue #154)', {'presses': out, 'lod': mid['lod'], 'shown': mid['shown'], 'mounted': mid['mounted']})
    short = m1[len('1.0.1'):]
    r.check(([l['place'] for l in labels] == [m1] and (address_line(labels[0]) or {}).get('text') == short) or (not labels and {o['place'] for o in left} == {m1}),
            'at mid the box carries one label, its version\'s address past the region\'s prefix, "%s": it marks the version the box holds (issue #154)' % short,
            {'labels': [[l['place'], [x['text'] for x in l['lines']]] for l in labels], 'left_out': [[o['place'], o['reason']] for o in left]})
    r.check(sibs == [m1] and bool(mid['focus']) and mid['focus']['addr'] == m1, 'at mid the walk stands on the box by the version it shows, and the mirror lists the box once, by that version (issue #154)',
            {'siblings': sibs, 'focus': mid['focus']})
    # the box's history strip as the last frame drew it, and the canvas's own pixels at its window's edges and member 1's tick
    strip = ctx.js('''((a) => { const s = window.__skep.strips().find((x) => x.doc === a); if (!s) return null;
      const c = document.getElementById('plane'), k = c.width / c.clientWidth, g = c.getContext('2d'), w = s.window;
      const px = (x, y) => [...g.getImageData(Math.floor(x * k), Math.floor(y * k), 1, 1).data].slice(0, 3);
      return {...s, pixels: w && {start: px(w.x + 1, w.y + w.h / 2), end: px(w.x + w.w - 1, w.y + w.h / 2), tick: px(s.rect.x + 2, s.rect.y + s.rect.h / 2)}}; })(%s)''' % json.dumps(VERSIONED))
    chain = ctx.js('window.__skep.model.doc(%s)' % json.dumps(VERSIONED))
    reg = ctx.js('import("./plane/register.js").then(({WINDOW, COL}) => ({ink: WINDOW.ink, land: COL.land}))')
    rgb = lambda h: [int(h[i:i + 2], 16) for i in (1, 3, 5)]
    near_rgb = lambda a, b: bool(a) and all(abs(x - y) <= 3 for x, y in zip(a, b))
    want = {'place': m1, 'doc': VERSIONED, 'n': chain['members'], 'held': 1, 'head': chain['members'] if chain['ended'] else None, 'open': False}
    got = strip and {k: strip[k] for k in want}
    pixels = (strip or {}).get('pixels') or {}
    r.check(got == want and (chain['members'] or 0) >= 2 and near_rgb(pixels.get('start'), rgb(reg['ink'])) and near_rgb(pixels.get('end'), rgb(reg['ink'])) and near_rgb(pixels.get('tick'), rgb(reg['land'])),
            'at mid the box\'s history strip marks its %s members, version 1 held in the window mark closed at both ends — its edges and member 1\'s tick in their own colours on the canvas — and the last member in the head\'s triangle where the board ended the chain there (issue #241)' % chain['members'],
            {'strip': got, 'want': want, 'pixels': pixels, 'rect': strip and strip['rect'], 'window': strip and strip['window'], 'ink': reg})
    seen['strip'] = {'strip': got, 'pixels': pixels}
    for _ in range(out):
        ctx.drv.key('=', code='Equal', mods=('Meta',))
        ctx.settle()
        ctx.frames(2)
    ctx.frames(3)
    near = box_of(ctx, VERSIONED)
    r.check(near['shown'] == m1 and near['mounted'] == [m1] and near['address']['doc'] == m1 and bool(near['marker']) and near['marker']['lit'] and same_view(near['cam'], at1['cam'])
            and near['trail']['cursor'] == at1['trail']['cursor'],
            'Mod+= as many times back: the camera where it stood, the box showing version 1, its article mounted, the line naming it, the trail unmoved (issue #154)',
            {'cam': [at1['cam'], near['cam']], 'shown': near['shown'], 'mounted': near['mounted'], 'address': near['address']['text']})
    seen['zoom'] = {'presses': out, 'labels': [[l['place'], [x['text'] for x in l['lines']]] for l in labels], 'siblings': sibs}
    # (c) Back across the versions, and Forward again
    cam_back = ctx.camera()
    ctx.drv.key('[', code='BracketLeft', mods=('Meta',))
    ctx.settle()
    ctx.frames(3)
    b = box_of(ctx, VERSIONED)
    again = line_of(ctx, VERSIONED, para['pos'])
    r.check(b['shown'] == VERSIONED and b['mounted'] == [VERSIONED] and b['corners'] == [VERSIONED] and same_view(b['cam'], cam0) and b['trail']['cursor'] == at1['trail']['cursor'] - 1
            and bool(b['marker']) and not b['marker']['lit'] and bool(again['line']) and abs(again['line']['y'] - before['line']['y']) <= DRIFT_TOL_PX,
            'Mod+[ restores the trunk head and the view the move left: its article and corner alone, the passage\'s line where it stood, the marker unlit (issue #154)',
            {'shown': b['shown'], 'mounted': b['mounted'], 'cam': [cam0, b['cam']], 'line': [before['line'], again['line']], 'marker': b['marker']})
    ctx.drv.key(']', code='BracketRight', mods=('Meta',))
    ctx.settle()
    ctx.frames(3)
    f = box_of(ctx, VERSIONED)
    r.check(f['shown'] == m1 and f['mounted'] == [m1] and same_view(f['cam'], cam_back) and f['trail']['cursor'] == at1['trail']['cursor'] and bool(f['marker']) and f['marker']['lit'],
            'Mod+] returns to version 1 at the view Back left (issue #154)', {'shown': f['shown'], 'mounted': f['mounted'], 'cam': [cam_back, f['cam']]})
    seen['back'] = {'cam_left': cam0, 'back': b['cam'], 'forward': f['cam']}
    # a click on the box at mid scale, as a person clicks a document there: the teleport lands on the version it shows
    out = 0
    while out < 14 and not drawn():
        ctx.drv.key('-', code='Minus', mods=('Meta',))
        ctx.settle()
        ctx.frames(2)
        out += 1
    ctx.frames(3)
    under = ctx.js('''(() => { const p = window.__skep.view.viewport(), x = p.VW / 2, y = p.VH / 2, e = document.elementFromPoint(x, y); return {x, y, plane: !!e && e.id === 'plane'}; })()''')
    before_click = ctx.js('window.__skep.trail()')
    if under['plane']:
        ctx.drv.mouse(under['x'], under['y'])
        ctx.settle()
        ctx.frames(3)
    c = box_of(ctx, VERSIONED)
    top = c['trail']['entries'][c['trail']['cursor']]
    r.check(under['plane'] and c['lod'] == 'near' and c['shown'] == m1 and c['mounted'] == [m1] and c['trail']['cursor'] == before_click['cursor'] + 1 and top['addr'] == m1 and bool(c['marker']) and c['marker']['lit'],
            'a click on the box at mid scale teleports to the version it shows: the landing at reading scale in version 1, the box still pinned there, its entry version 1\'s (issue #154)',
            {'under': under, 'presses': out, 'lod': c['lod'], 'shown': c['shown'], 'mounted': c['mounted'], 'newest': {k: top.get(k) for k in ('addr', 'pos')}})
    seen['click'] = {'presses': out, 'landed': {k: top.get(k) for k in ('addr', 'pos')}}
    # (d) a passage version 1 holds none of
    ctx.esc()
    ctx.leap(VERSIONED, None)
    gap = lacking_of(ctx, VERSIONED, m1)
    if gap is None:
        r.note('the version move over a passage the version lacks is unmeasured on this board: version 1 holds all of the trunk head\'s text; go.test.js holds the rule')
        seen['lacking'] = 'unmeasured'
    else:
        ctx.view_at(VERSIONED, gap['lo'])
        held = line_of(ctx, VERSIONED, gap['lo'])
        ctx.js('window.__skep.cards.versions(%s, %d, %d)' % (json.dumps(VERSIONED), gap['lo'], gap['hi'] - gap['lo']))
        wait_for(ctx, 'document.querySelector(%s) !== null' % json.dumps('#overlay [data-run="read1"]'))
        at = click_on(ctx, '#overlay [data-run="read1"]')
        wait_for(ctx, 'window.__skep.go.shownIn(%s) === %s && (window.__skep.overlay().notice || {}).id === "face:floating"' % (json.dumps(VERSIONED), json.dumps(m1)))
        ctx.settle()
        ctx.frames(3)
        face = ctx.js('(() => { const n = window.__skep.overlay().notice; return {id: n ? n.id : null, text: n ? n.text : "", acts: document.querySelectorAll("#notice [data-run]").length}; })()')
        said = ctx.js('import("./strings.js").then(({t}) => t("F.floating.member", {k: 1}))')
        landed, nowhere = box_of(ctx, VERSIONED), ctx.js('window.__skep.go.arrival()')
        stood = line_of(ctx, m1, gap['at'])
        entry = landed['trail']['entries'][landed['trail']['cursor']]
        r.check(bool(at) and at['hits'] and ctx.js('window.__skep.overlay().id') == 'versions:' + VERSIONED and face['id'] == 'face:floating' and said in face['text'] and face['acts'] == 0
                and landed['shown'] == m1 and landed['mounted'] == [m1] and nowhere is None,
                'a passage version 1 holds none of, carried by its read act: the box shows version 1, nothing outlined, the versions list standing and the dead end\'s face below it saying "%s", offering no act (issues #154, #266)' % said,
                {'gap': gap, 'face': face, 'overlay': ctx.js('window.__skep.overlay().id'), 'shown': landed['shown'], 'arrival': nowhere})
        r.check(bool(held['line']) and bool(stood['line']) and abs(stood['line']['y'] - held['line']['y']) <= DRIFT_TOL_PX and entry['addr'] == m1 and entry['pos'] == gap['at'],
                f'the nearest shared position\'s counterpart in version 1 keeps the line the passage stood on, {DRIFT_TOL_PX} px either way, and the move\'s entry stands there (issue #154)',
                {'gap': gap, 'held': held['line'], 'stood': stood['line'], 'entry': {k: entry.get(k) for k in ('addr', 'pos')}})
        seen['lacking'] = {'gap': gap, 'face': face['text'][:80]}
        ctx.esc()
    ctx.leap(VERSIONED, None)
    return seen


def chrome_holds(ctx, r):
    """THE CHROME's checks: the LEAP box's columns — each row's go, among its rows a trail entry carrying the longest label
    a place has (a document's first line, up to 200 characters), and the "open beside" a row naming another document
    offers past it; the opaque chrome over the plane; its figures"""
    ctx.leap(FAR_LEAP)
    ctx.leap(DOC, WINDOW[0])
    ctx.js('window.__skep.leap.open()')
    ctx.frames(2)
    cells = ctx.js('''[...document.querySelectorAll('#leaphits .hit')].map((h) => [...(h.querySelector('.go') || h).children].map((c) => { const q = c.getBoundingClientRect();
      return {x: q.left, w: q.width, row: h.getBoundingClientRect().width, over: c.scrollWidth - c.clientWidth, chars: c.textContent.length}; }))''')
    whole = len(cells) >= 3 and all(len(row) == 3 for row in cells)
    ragged = {i: [round(row[i]['x'], 2) for row in cells] for i in range(3) if whole and max(row[i]['x'] for row in cells) - min(row[i]['x'] for row in cells) > LABEL_TOL_PX}
    r.check(whole and not ragged, f'the LEAP box: its rows share their columns — each column\'s cells start at one x, {LABEL_TOL_PX} px either way', {'rows': len(cells), 'cells': [len(row) for row in cells], 'ragged': ragged})
    acts = ctx.js('''[...document.querySelectorAll('#leaphits [data-beside]')].map((b) => { const q = b.getBoundingClientRect(), g = b.closest('.hit').querySelector('.go').getBoundingClientRect();
      return {x: q.left, go: g.right}; })''')
    r.check(bool(acts) and all(a['x'] >= a['go'] - LABEL_TOL_PX for a in acts) and max(a['x'] for a in acts) - min(a['x'] for a in acts) <= LABEL_TOL_PX,
            f'the LEAP box: each row\'s "open beside" stands in a column of its own past the row\'s go, at one x across the rows that offer it, {LABEL_TOL_PX} px either way (issue #332)', acts)
    longest = max((c['chars'] for row in cells for c in row), default=0)
    over = [[i, j, c['over']] for i, row in enumerate(cells) for j, c in enumerate(row) if c['over'] > 1]
    narrow = [[i, round(row[1]['w'], 1), round(row[1]['row'], 1)] for i, row in enumerate(cells) if whole and row[1]['w'] < row[1]['row'] / 4]
    r.check(whole and longest >= 100 and not over and not narrow, 'the LEAP box: no cell\'s text runs past its column, and the title\'s column keeps a quarter of the row or more — a label of a hundred characters or more among the rows',
            {'longest_cell_chars': longest, 'overflowing': over[:6], 'narrow_titles': narrow[:6]})
    # an address in a row is exact (issue #23's design decision: "The address is never truncated or greyed"): at the full ink, on one line
    ids = ctx.js('''(() => { const ink = getComputedStyle(document.body).color;
      return [...document.querySelectorAll('#leaphits .id')].map((e) => ({text: e.textContent, ink: getComputedStyle(e).color, full: ink, lines: e.getClientRects().length})); })()''')
    grey = [x for x in ids if x['ink'] != x['full']]
    broken = [x for x in ids if x['lines'] != 1]
    r.check(bool(ids) and not grey and not broken, 'the LEAP box: every address in its rows stands at the full ink, never greyed, on one line, never broken (issue #23)',
            {'addresses': len(ids), 'greyed': grey[:4], 'broken': broken[:4]})
    ctx.js('window.__skep.leap.close()')
    ctx.frames(1)
    alpha = ctx.js(r'''(() => { const a = (sel) => { const e = document.querySelector(sel); if (!e) return null;
        const m = getComputedStyle(e).backgroundColor.match(/rgba?\(([^)]+)\)/), p = m ? m[1].split(',').map(Number) : [];
        return p.length === 4 ? p[3] : p.length === 3 ? 1 : 0; };
      return {leap: a('#leap'), scene: a('#scene'), line: a('#line'), mirror: a('#mirror'), corner: a('#corners .corner')}; })()''')
    thin = {k: x for k, x in alpha.items() if x != 1}
    r.check(not thin, 'the chrome over the plane is opaque — the LEAP box, the scene, the one line, the mirror and a corner: no text the plane holds shows through', alpha)
    return {'leap_rows': len(cells), 'leap_columns': [round(c['w'], 1) for c in cells[0]] if cells else None, 'alpha': alpha}


def lead_handoff(ctx, r):
    """THE CONTENTS LINE'S HAND-OFF (issue #23's design decision: "Set it at the head of the first column, where those words will
    stand when the text mounts ... Mounting then moves no word"): the camera over the first edition's first column, brought in
    from far out to BELOW_MOUNT_EM, where its article stands nowhere and its label is the canvas's — its first line's first word
    starts, and its line is centred, where its article mounted at ABOVE_MOUNT_EM sets that word: the first character of its first
    typed line, in world units, HANDOFF_TOL_PX on screen either way; its figures"""
    first = ctx.js('window.__skep.centreOf(%s, null)' % json.dumps(DOC))
    lo = ctx.js('window.__skep.scaleFor(%s, "em", %s)' % (json.dumps(DOC), BELOW_MOUNT_EM))
    hi = ctx.js('window.__skep.scaleFor(%s, "em", %s)' % (json.dumps(DOC), ABOVE_MOUNT_EM))
    ctx.set_view(first['x'], first['y'], lo / 4)
    ctx.frames(2)
    ctx.set_view(first['x'], first['y'], lo)
    ctx.settle()
    ctx.frames(3)
    WORLD = '''((r) => { const c = window.__skep.view.camera(), p = window.__skep.view.viewport();
      return r && {x: (r.x - p.VW / 2) / c.scale + c.x, y: (r.y + r.h / 2 - p.VH / 2) / c.scale + c.y}; })'''
    below = ctx.js('''((doc) => { const l = window.__skep.labels().find((x) => x.kind === 'doc' && x.place === doc && !x.held);
      const first = l && l.lines.find((x) => !x.runs.every((q) => q.face === 'ident'));
      return {mounted: window.__skep.mountedAddrs().includes(doc), text: first ? first.text : null, at: first ? %s(first.rect) : null}; })(%s)''' % (WORLD, json.dumps(DOC)))
    ctx.set_view(first['x'], first['y'], hi)
    ctx.settle()
    ctx.frames(3)
    above = ctx.js('''((doc) => { const art = document.querySelector(`#domlayer article.dtext[data-addr="${doc}"]`);
      const b = art && art.querySelector('.sp.blk-para'), w = b && document.createTreeWalker(b, NodeFilter.SHOW_TEXT);
      for (let n = w && w.nextNode(); n; n = w.nextNode()) { const i = n.data.search(/\\S/); if (i < 0) continue;
        const q = document.createRange(); q.setStart(n, i); q.setEnd(n, i + 1); const x = q.getBoundingClientRect();
        return {mounted: true, char: n.data[i], at: %s({x: x.left, y: x.top, w: x.width, h: x.height})}; }
      return {mounted: !!art, char: null, at: null}; })(%s)''' % (WORLD, json.dumps(DOC)))
    ok = bool(below['at'] and above['at']) and not below['mounted'] and above['mounted']
    dx = abs(below['at']['x'] - above['at']['x']) * hi if ok else None
    dy = abs(below['at']['y'] - above['at']['y']) * hi if ok else None
    r.check(ok and dx <= HANDOFF_TOL_PX and dy <= HANDOFF_TOL_PX and bool(below['text']) and below['text'][0] == above['char'],
            f'the hand-off: below the mount, the first edition\'s label\'s first line starts with the first word its article, mounted above it, sets there — where that word starts and level with its line, {HANDOFF_TOL_PX} px either way on screen (issue #23)',
            {'below': below, 'above': above, 'dx_px': dx, 'dy_px': dy})
    return {'below': below, 'above': above, 'dx_px': dx, 'dy_px': dy}


def address_dots(ctx, r):
    """AN ADDRESS'S DOTS STAND APART (issue #23's design decision: "never set below the size at which its dots stay distinct"):
    a long address set as a label sets it — at the page's address size and weight, in the identifier's face as shipped — drawn on
    a canvas of the case's own: every dot one island of ink inside its own character's cell, touching no digit, and DOT_GAP_PX or
    more blank columns between it and the characters either side; its figures"""
    text = '1.0.1.0.1049578.12'
    v = ctx.js('''(async (text) => {
      const A = window.__skep.address(), font = `${A.weight} ${A.px}px "Atkinson Hyperlegible Mono"`;
      await document.fonts.load(font);
      const c = document.createElement('canvas'); c.width = 400; c.height = 40;
      const g = c.getContext('2d'); g.font = font; g.textBaseline = 'middle'; g.fillStyle = '#000'; g.fillText(text, 10, 20);
      const d = g.getImageData(0, 0, c.width, c.height).data, ink = [];
      for (let x = 0; x < c.width; x++) { let a = 0; for (let y = 0; y < c.height; y++) a = Math.max(a, d[(y * c.width + x) * 4 + 3]); ink.push(a > 64); }
      const islands = []; let s = -1;
      ink.forEach((on, x) => { if (on && s < 0) s = x; if (!on && s >= 0) { islands.push([s, x]); s = -1; } });
      // each character's cell along the run: the face's one advance from where the run starts
      const adv = g.measureText(text).width / text.length;
      return {px: A.px, weight: A.weight, islands, adv, x0: 10, loaded: document.fonts.check(font)};
    })(%s)''' % json.dumps(text))
    dots = []
    for i, ch in enumerate(text):
        if ch != '.':
            continue
        left, right = v['x0'] + i * v['adv'], v['x0'] + (i + 1) * v['adv']
        k = next((j for j, (a, b) in enumerate(v['islands']) if left <= (a + b) / 2 < right), None)
        own = k is not None and v['islands'][k][0] >= left - 1 and v['islands'][k][1] <= right + 1
        gaps = [v['islands'][k][0] - v['islands'][k - 1][1] if k else None, v['islands'][k + 1][0] - v['islands'][k][1] if k is not None and k + 1 < len(v['islands']) else None] if k is not None else [None, None]
        dots.append({'at': i, 'own': own, 'gaps': gaps})
    apart = [x for x in dots if not (x['own'] and all(g is not None and g >= DOT_GAP_PX for g in x['gaps']))]
    r.check(v['loaded'] and v['px'] >= MIN_LABEL_PX and bool(dots) and not apart,
            f'an address at the size and weight a label sets it at — {v["px"]} px, {v["weight"]}, in the shipped identifier face — keeps every dot apart: each of its {len(dots)} dots an island of ink inside its own character\'s cell, {DOT_GAP_PX} px or more of blank between it and the characters either side (issue #23)',
            {'px': v['px'], 'weight': v['weight'], 'dots': dots, 'loaded': v['loaded']})
    return {'px': v['px'], 'weight': v['weight'], 'dots': len(dots), 'min_gap_px': min((g for x in dots for g in x['gaps'] if g is not None), default=None)}


LINE_LABEL_JS = '''((probes) => { const b = document.querySelector('#line button.address'), lab = b && b.querySelector('.label'), part = b && b.closest('.address-part');
  if (!b || !lab || !part) return null;
  const q = (e) => { const x = e.getBoundingClientRect(); return {x: x.left, y: x.top, w: x.width, h: x.height}; }, box = lab.getBoundingClientRect(), words = [];
  const w = document.createTreeWalker(lab, NodeFilter.SHOW_TEXT), range = document.createRange();
  for (let n = w.nextNode(); n; n = w.nextNode()) for (const m of n.data.matchAll(/\\S+/g)) {
    range.setStart(n, m.index); range.setEnd(n, m.index + m[0].length); const rs = [...range.getClientRects()];
    if (rs.length) words.push({word: m[0], top: rs[0].top, right: Math.max(...rs.map((x) => x.right)), lines: rs.length}); }
  // the widths the label's words would take, in its face at its size, set apart from it
  const widths = probes.map((t) => { const e = document.createElement('span'); e.textContent = t; e.style.cssText = 'position:absolute;visibility:hidden;white-space:pre';
    e.style.font = getComputedStyle(lab).font; document.body.appendChild(e); const x = e.getBoundingClientRect().width; e.remove(); return x; });
  return {button: q(part), label: q(lab), text: lab.textContent, words, place: q(b.querySelector('b')), slot: q(part.querySelector('.slot')), marker: q(part.querySelector('.marker')),
          vw: window.innerWidth, address: window.__skep.line().address, widths}; })'''


def two_words(lead):
    """the shortest cut of a lead a label may set (issue #23): its words up to its LEAD_WORDS-th word holding a letter or a figure,
    and the ellipsis; None where it holds fewer"""
    ws, n = lead.split(' '), 0
    for i, w in enumerate(ws):
        n += 1 if re.search(r'\w', w) else 0
        if n == LEAD_WORDS:
            return ' '.join(ws[:i + 1]) + '…' if i + 1 < len(ws) else None
    return None


def line_label_holds(ctx, r):
    """THE ONE LINE'S LABEL (issue #23's design decision: "exact fields first, each followed by its label. When room runs short,
    labels give way before fields"): landed at the reading size in an edition of the claimant's whose first line's two first words
    fit the room the address segment leaves its label, the segment's document field is followed by its label — the page's lead for
    it, whole or cut on a word — then its position; in a window LINE_NARROW_PX wide the label gives way a whole word at a time —
    every word it shows whole inside it — while every field stands whole inside the address part and the window; its figures"""
    places = ctx.js('window.__skep.model.places()')
    tried, chosen, wide, lead = [], None, None, ''
    for doc in [DOC] + [p['doc'] for p in places if p['account'] == account_of(DOC) and not p.get('system') and p['kind'] == 'edition' and len((p['label'] or '').split()) >= 3][:10]:
        ctx.leap(doc, None)
        ctx.js('new Promise((r) => setTimeout(r, 300))')
        lead = ctx.js('window.__skep.firstLine(%s).lead' % json.dumps(doc))
        two = two_words(lead or '')
        v = ctx.js('%s(%s)' % (LINE_LABEL_JS, json.dumps([lead or '', two or ''])))
        tried.append({'doc': doc, 'lead': lead, 'shown': v and v['text'], 'room': v and v['label']['w'], 'whole': v and v['widths'][0], 'two': two and v and v['widths'][1]})
        # the label as the rule asks for it: none where neither the lead whole nor its two first words fit its room
        if v and not v['text'] and v['widths'][0] > v['label']['w'] and (not two or v['widths'][1] > v['label']['w']):
            continue
        chosen, wide = doc, v
        break
    shown = wide and wide['text']
    r.check(bool(chosen) and bool(shown) and word_cut(shown, lead) and wide['place']['x'] + wide['place']['w'] <= wide['label']['x'] + LABEL_TOL_PX
            and wide['label']['x'] + wide['label']['w'] <= wide['slot']['x'] + LABEL_TOL_PX,
            'the one line: the document\'s field followed by its label — its lead, whole or cut on a word — then its position; where its two first words do not fit the room its segment leaves it, none (issue #23)',
            {'chosen': chosen, 'tried': tried, 'line': wide and {k: wide[k] for k in ('label', 'place', 'slot', 'text')}})
    if not chosen:
        return {'tried': tried}
    was = ctx.resize(LINE_NARROW_PX, 900)
    try:
        ctx.settle()
        ctx.leap(chosen, None)
        ctx.js('new Promise((r) => setTimeout(r, 300))')
        narrow = ctx.js('%s([])' % LINE_LABEL_JS)
    finally:
        ctx.resize(*was)
    ctx.settle()
    within = lambda a, b: a['x'] >= b['x'] - LABEL_TOL_PX and a['x'] + a['w'] <= b['x'] + b['w'] + LABEL_TOL_PX
    fields = bool(narrow) and all(within(narrow[k], narrow['button']) and narrow[k]['x'] + narrow[k]['w'] <= narrow['vw'] + LABEL_TOL_PX for k in ('place', 'slot', 'marker'))
    top = narrow['label']['y'] if narrow else 0
    on = [x for x in (narrow or {}).get('words', []) if abs(x['top'] - top) <= 2]
    cut = [x for x in on if x['lines'] > 1 or x['right'] > narrow['label']['x'] + narrow['label']['w'] + LABEL_TOL_PX]
    gave = bool(narrow) and bool(wide) and narrow['label']['w'] < wide['label']['w'] - LABEL_TOL_PX
    r.check(fields and not cut and gave,
            f'a {LINE_NARROW_PX} px window: the line\'s document label gives way first, a whole word at a time — every word it shows whole inside it — and every field stands whole inside the address part and the window (issues #23, #310)',
            {'wide_label_w': wide and wide['label']['w'], 'narrow': narrow and {k: narrow[k] for k in ('button', 'label', 'place', 'slot', 'marker', 'vw')}, 'shown': [x['word'] for x in on], 'cut': cut})
    return {'chosen': chosen, 'lead': lead, 'shown': shown, 'narrow_shown': [x['word'] for x in on], 'narrow_label_w': narrow and narrow['label']['w'], 'tried': tried}

def walk_holds(ctx, r):
    """A WALK'S FOLDED MOMENT (issue #182's design decision: "Dismissing it changes how much room it takes, never whether it
    is there … It never yields when the line runs short"): a label box owed an answer raised through the gate's door as the
    shell's event raises one, over nothing standing — whole, its face standing; Esc folds it into its segment of the one
    line, naming the walk and its step and that it waits on the reader, its face gone and the shell told nothing. In a
    window WALK_PX wide, too narrow for the line's every part in one row, the segment stands whole inside the line, the
    acting-as segment before it inside the line too, the line taking another row (issues #310, #445); its act unfolds the
    moment, the focus on its first words, and Esc folds it again. The moment is the gate's own, which no walk waits on and
    the next case's fresh page leaves behind; its figures"""
    walk, step = 'gate-182', 'name this device'
    m = {'id': 'gate-moment-182', 'kind': 'label', 'data': {'title': step, 'statements': [], 'default': None}, 'walk': walk, 'board': None, 'answerable': True}
    ctx.js('window.__skep.leap.close()')
    ctx.js('window.__skep.dismiss()')
    ctx.js('window.__skep.scene.close()')
    ctx.js('document.activeElement && document.activeElement.blur && document.activeElement.blur()')
    ctx.frames(2)
    n0 = len(ctx.js('window.__skep.bridge.calls()'))
    ctx.js('window.__skep.moments.raise(%s)' % json.dumps(m))
    ctx.frames(2)
    whole = ctx.js('window.__skep.overlay()')
    ctx.esc()
    words = '%s · %s — waits on you' % (walk, step)
    folded = ctx.js('window.__skep.moments.folded()')
    r.check(whole['id'] == 'moment:gate-moment-182' and ctx.js('window.__skep.overlay()')['id'] is None and folded == [{'key': walk + '|', 'words': words}],
            'a walk\'s moment raised over nothing stands whole; Esc folds it into its segment, naming the walk and its step and that it waits on the reader (issue #182)',
            {'raised': whole['id'], 'folded': folded})
    was = ctx.resize(WALK_PX, 900)
    try:
        ctx.js('new Promise((r) => setTimeout(r, 300))')  # the line redraws on its own cadence, every 120 ms
        seen = ctx.js('''(() => { const line = document.getElementById('line'), q = (e) => { if (!e) return null; const b = e.getBoundingClientRect();
            return {left: b.left, right: b.right, width: b.width, over: e.scrollWidth - e.clientWidth, text: e.textContent}; };
          return {line: q(line), walk: q(line.querySelector('.seg.walk')), acting: q(line.querySelector('.seg.acting')), layout: window.__skep.line().layout}; })()''')
        line, seg, acting = seen['line'], seen['walk'], seen['acting']
        r.check(bool(seg) and seg['text'] == words and seg['over'] <= 0 and seg['right'] <= line['right'] + 0.5
                and bool(acting) and acting['over'] <= 1 and acting['right'] <= line['right'] + 0.5 and len((seen.get('layout') or {}).get('rows') or []) > 1,
                f'a {WALK_PX} px window, short of room: the walk\'s segment stands whole inside the one line, its words uncut, the acting-as segment before it inside the line too, the line taking another row (issues #182: "It never yields when the line runs short", #310, #445)',
                seen)
        ctx.js("document.querySelector('#line .seg.walk').click()")
        ctx.frames(2)
        unfolded = ctx.js('({id: window.__skep.overlay().id, first: !!document.activeElement && document.activeElement.classList.contains("moment-words"), folded: window.__skep.moments.folded()})')
        r.check(unfolded['id'] == 'moment:gate-moment-182' and unfolded['first'] and unfolded['folded'] == [],
                'the segment\'s act unfolds the moment, the focus on its first words, its segment gone (issue #182: "Unfolding moves focus to the face\'s first words")', unfolded)
        ctx.esc()
    finally:
        ctx.resize(*was)
    calls = [c['name'] for c in ctx.js('window.__skep.bridge.calls()')[n0:]]
    r.check('answer' not in calls and 'cancel' not in calls and ctx.js('window.__skep.moments.folded()') == [{'key': walk + '|', 'words': words}],
            'folded, unfolded and folded again, the moment told the shell nothing — no answer, no cancel — and stands folded', sorted(set(calls)))
    return {'window': WALK_PX, 'line': seen['line'], 'walk': seen['walk'], 'acting': seen['acting']}


# the one line as it stands (`line_rows_hold`; the guest case's): its rect and the window's width, its acts and the address
# part's fields — each whole inside the line and the window or not — the segments cut short and those past the window's
# edge, the layout it holds, and whether its acts stand first in its first row
LINE_PARTS_JS = '''(() => { const line = document.getElementById('line'), q = (e) => { const b = e.getBoundingClientRect(); return {x: b.left, y: b.top, w: b.width, h: b.height}; };
  const L = q(line), vw = window.innerWidth;
  const inside = (b) => b.w > 0 && b.h > 0 && b.x >= -0.5 && b.x + b.w <= vw + 0.5 && b.x >= L.x - 0.5 && b.x + b.w <= L.x + L.w + 0.5 && b.y >= L.y - 0.5 && b.y + b.h <= L.y + L.h + 0.5;
  const btn = line.querySelector('button.seg.address'), part = btn && btn.closest('.address-part');
  const els = {back: line.querySelector('[data-act=back]'), forward: line.querySelector('[data-act=forward]'), trail: line.querySelector('[data-act=trail]'), signin: line.querySelector('[data-act=signin]'),
               address: btn, place: btn && btn.querySelector('b'), board: part && part.querySelector('.board'), fold: line.querySelector('button.fold'),
               strip: line.querySelector('button.slot[data-act=strip]'), marker: part && part.querySelector('.marker')};
  const fields = {};
  for (const [k, e] of Object.entries(els)) fields[k] = e ? {inside: inside(q(e)), text: e.textContent, rect: q(e)} : null;
  const segs = [...line.querySelectorAll('.seg')].map((e) => ({cls: e.className, over: e.scrollWidth - e.clientWidth, rect: q(e), text: e.textContent.slice(0, 60)}));
  const first = line.querySelector('.row > :first-child');
  return {line: L, vw, fields, cut: segs.filter((x) => x.over > 1), past: segs.filter((x) => x.rect.x + x.rect.w > vw + 0.5 || x.rect.x < -0.5),
          layout: window.__skep.line().layout, actsFirst: !!first && first.classList.contains('acts') && first.parentElement === line.firstElementChild}; })()'''

# the one line's acting-as segment as a person meets it (`line_rows_hold`): its element, its act and its accessible label,
# its words and the lines its fields stand on, whether it stands inside the window, how far its words run past its box,
# whether the platform's focus stands on it, the layout's form for it, and its key's glyphs — each hidden from the
# accessibility tree or not, and the words it holds
LINE_ACTING_JS = '''(() => { const a = document.querySelector('#line .seg.acting'); if (!a) return null; const b = a.getBoundingClientRect();
  const lines = new Set([...a.querySelectorAll('.field')].map((f) => Math.round(f.getBoundingClientRect().top))).size;
  return {tag: a.tagName.toLowerCase(), act: a.dataset.act || null, label: a.getAttribute('aria-label'), text: a.textContent, lines,
          inside: b.width > 0 && b.left >= -0.5 && b.right <= window.innerWidth + 0.5, over: a.scrollWidth - a.clientWidth, focused: document.activeElement === a,
          form: (window.__skep.line().layout || {}).form, glyphs: [...a.querySelectorAll('svg')].map((g) => ({hidden: g.getAttribute('aria-hidden') === 'true', text: g.textContent}))}; })()'''

# the one line's daemon segment as a person meets it (`line_rows_hold`): its words, whether it stands inside the window, how
# far its words run past its box, the line boxes its words take, and the segments of the line past the window's edge
LINE_DAEMON_JS = '''(() => { const e = document.querySelector('#line .seg.daemon'), vw = window.innerWidth; if (!e) return null; const b = e.getBoundingClientRect(), w = e.querySelector('[data-string]');
  const past = [...document.querySelectorAll('#line .seg')].filter((x) => { const q = x.getBoundingClientRect(); return q.right > vw + 0.5 || q.left < -0.5; }).map((x) => x.className);
  return {text: e.textContent, inside: b.width > 0 && b.left >= -0.5 && b.right <= vw + 0.5, over: e.scrollWidth - e.clientWidth, lines: w ? w.getClientRects().length : 0, past, layout: window.__skep.line().layout}; })()'''


def acting_ax(ctx):
    """the one line's acting-as segment as the AX tree holds it, where CDP answers the tree: its node's role and name, and
    whether its key's glyph stands for anything there — a node of its own the tree does not ignore; None where CDP does not
    answer"""
    ax = ctx.drv.ax_tree()
    if 'error' in ax:
        return None
    by_dom = {n['backendDOMNodeId']: n for n in ax.get('nodes', []) if 'backendDOMNodeId' in n}

    def node(selector):
        """the AX node of the element a selector names, by its backend DOM node id; None where none stands"""
        obj = ctx.drv.call('Runtime.evaluate', {'expression': 'document.querySelector(%s)' % json.dumps(selector)})['result']
        if not obj.get('objectId'):
            return None
        try:
            return by_dom.get(ctx.drv.call('DOM.describeNode', {'objectId': obj['objectId']})['node']['backendNodeId'])
        finally:
            ctx.drv.call('Runtime.releaseObject', {'objectId': obj['objectId']})
    seg, glyph = node('#line .seg.acting'), node('#line .seg.acting svg')
    return {'role': ((seg or {}).get('role') or {}).get('value'), 'name': ((seg or {}).get('name') or {}).get('value'), 'glyph_shown': bool(glyph) and not glyph.get('ignored')}


# each of the one line's parts, and whether the element found at the centre of what of it the window shows is inside it
# (`line_rows_hold`)
LINE_HITS_JS = '''(() => [...document.querySelectorAll('#line .row > :not(.sep)')].map((p) => { const b = p.getBoundingClientRect(), x = (Math.max(b.left, 0) + Math.min(b.right, window.innerWidth)) / 2, y = b.top + b.height / 2;
  const hit = document.elementFromPoint(x, y); return {part: p.className, at: [x, y], found: !!hit && p.contains(hit), hit: hit ? (hit.id || hit.className || hit.tagName) : null}; }))()'''


def line_rows_hold(ctx, r):
    """THE ONE LINE SHORT OF ROOM (issue #310's design decision: "The line never clips … The line's acts … stand first …
    An address wider than a row folds the levels between its board and its deepest level into one mark"; issue #445's:
    "The whole short segment is one act that opens the full form … A field wider than a row wraps between words"): the
    acting-as segment's words read whole in the window the case opens in; then in each window LINE_ROWS_PX wide, landed at
    the window run's position in the first edition, the line stands on the step and the rows its layout holds — folded in
    the narrowest — and every act, the board's field, the document's field, the strip and the marker stand whole inside
    the line and the window, no segment of it cut short; every segment stands inside the window; the acting-as segment
    stands compact, its act a button whose accessible label and AX name are those whole words, its key's glyph hidden and
    standing for nothing in the AX tree, and Enter at the act opens those words inside the window, uncut, the focus kept
    on the act; the strip's act there shows its readout inside the window; the board's writes halted through the gate's
    door, the halted form's words stand whole inside the window, broken between them, every segment inside the window,
    and lifted they go; and with the LEAP box open, then with a reading scene open, then with the trail's list opened
    from the line's act, each of the line's parts is the element found at the centre of what of it the window shows, none
    standing over it. Its figures"""
    figures = {}
    ctx.leap(DOC, WINDOW[0])
    ctx.js('new Promise((r) => setTimeout(r, 300))')  # the line redraws on its own cadence, every 120 ms
    wide = ctx.js(LINE_ACTING_JS) or {}
    whole = wide.get('text') if wide.get('form') == 0 and wide.get('tag') == 'span' else None
    r.check(bool(whole), 'the window the case opens in: the acting-as segment whole, no act (issue #445)', wide)
    halted = ctx.js('(async () => (await import("./strings.js")).t("F.daemon.notebook.halted"))()')
    was = ctx.resize(LINE_ROWS_PX[0], 900)
    try:
        for w in LINE_ROWS_PX:
            ctx.resize(w, 900)
            ctx.settle()
            ctx.leap(DOC, WINDOW[0])
            ctx.js('new Promise((r) => setTimeout(r, 300))')  # the line redraws on its own cadence, every 120 ms
            v = ctx.js(LINE_PARTS_JS)
            f, lay = v['fields'], v.get('layout') or {}
            need = ['back', 'forward', 'trail', 'address', 'place', 'strip', 'marker'] + (['board', 'fold'] if lay.get('step') == 4 else [])
            missing = [k for k in need if not (f.get(k) or {}).get('inside')]
            folded = lay.get('step') == 4 and bool(f.get('board')) and f['board']['text'].startswith('1') and bool(f.get('fold')) and (f.get('place') or {}).get('text', '').endswith(DOC)
            r.check(v['actsFirst'] and not missing and not v['cut'] and (folded if w == LINE_ROWS_PX[-1] else lay.get('step') == 3),
                    f'a {w} px window: the one line on its layout\'s step {lay.get("step")} in {len(lay.get("rows") or [])} rows — its acts first, every act, the board\'s field, the document\'s field, the strip and the marker whole inside the line and the window, no segment cut short{", the account folded into its mark" if w == LINE_ROWS_PX[-1] else ""} (issue #310)',
                    {'layout': lay, 'missing': missing, 'cut': v['cut'], 'fields': {k: x and {'inside': x['inside'], 'text': x['text'][:40]} for k, x in f.items()}, 'line': v['line']})
            r.check(not v['past'], f'a {w} px window: every segment of the one line inside the window (issues #310, #445)', {'past': v['past'], 'vw': v['vw']})
            act, ax = ctx.js(LINE_ACTING_JS), acting_ax(ctx)
            named = bool(act) and bool(whole) and act['tag'] == 'button' and act['act'] == 'acting' and act['label'] == whole and act['text'] != whole and act['inside'] and act['over'] <= 1
            hidden = bool(act) and all(g['hidden'] and not g['text'].strip() for g in act['glyphs'])
            if ax is None:
                r.note(f'a {w} px window: Accessibility.getFullAXTree did not answer; the acting-as segment\'s act read from the DOM alone')
            r.check(named and hidden and (ax is None or (ax['role'] == 'button' and ax['name'] == whole and not ax['glyph_shown'])),
                    f'a {w} px window: the acting-as segment compact — "{(act or {}).get("text", "")}" — its act a button the AX tree names by the words it shows whole, its key\'s glyph hidden and standing for nothing there (issue #445: "Assistive technology reads the whole form, never the glyph")',
                    {'act': act, 'ax': ax, 'whole': whole})
            ctx.js("(() => { const b = document.querySelector('#line [data-act=acting]'); if (b) b.focus({preventScroll: true}); })()")
            ctx.drv.key('Enter')
            ctx.frames(2)
            unfolded = ctx.js(LINE_ACTING_JS)
            ctx.js('window.__skep.lineAct()')
            ctx.js('document.activeElement && document.activeElement.blur && document.activeElement.blur()')
            ctx.frames(2)
            r.check(bool(unfolded) and unfolded['text'] == whole and unfolded['act'] == 'acting' and unfolded['inside'] and unfolded['over'] <= 1 and unfolded['focused'],
                    f'a {w} px window: Enter at the act opens the acting-as segment\'s whole form inside the window, uncut, the focus kept on the act (issue #445: "The whole short segment is one act that opens the full form")',
                    {'opened': unfolded, 'whole': whole})
            ctx.js("document.querySelector('#line button.slot[data-act=strip]') && document.querySelector('#line button.slot[data-act=strip]').click()")
            ctx.frames(2)
            readout = ctx.js('''(() => { const e = document.querySelector('#line .seg.transient[data-string="strip"]'); if (!e) return null; const b = e.getBoundingClientRect();
              return {text: e.textContent, inside: b.width > 0 && b.left >= -0.5 && b.right <= window.innerWidth + 0.5 && b.bottom <= document.getElementById('line').getBoundingClientRect().bottom + 0.5, over: e.scrollWidth - e.clientWidth}; })()''')
            ctx.js('window.__skep.lineAct()')
            ctx.frames(2)
            r.check(bool(readout) and readout['inside'] and readout['over'] <= 1 and readout['text'].startswith('position %d' % WINDOW[0]),
                    f'a {w} px window: the strip\'s act shows the position\'s readout, whole inside the line and the window (issue #310: "its readout opens on the strip\'s act")', readout)
            ctx.js('window.__skep.halt(true)')
            ctx.js('new Promise((r) => setTimeout(r, 300))')
            halt = ctx.js(LINE_DAEMON_JS)
            ctx.js('window.__skep.halt(false)')
            ctx.js('new Promise((r) => setTimeout(r, 300))')
            lifted = ctx.js("!document.querySelector('#line .seg.daemon')")
            r.check(bool(halt) and halt['text'] == halted and halt['inside'] and halt['over'] <= 1 and not halt['past'] and lifted,
                    f'a {w} px window: the board\'s writes halted, its halted form\'s words stand whole inside the window over {(halt or {}).get("lines")} line boxes, every segment inside the window; the halt lifted, they go (issue #445: "A field wider than a row wraps between words")',
                    {'halt': halt, 'lifted': lifted})
            covered = {}
            ctx.js('window.__skep.leap.open()')
            ctx.frames(2)
            covered['leap'] = ctx.js(LINE_HITS_JS)
            ctx.js('window.__skep.leap.close()')
            ctx.frames(2)
            ctx.js('window.__skep.scene.open(%s, %s)' % (json.dumps(VERSIONED + '.1'), json.dumps(VERSIONED)))
            wait_for(ctx, 'window.__skep.scene.isOpen()')
            opened = ctx.js('window.__skep.scene.isOpen()')
            covered['scene'] = ctx.js(LINE_HITS_JS) if opened else None
            ctx.js('window.__skep.scene.close()')
            ctx.frames(2)
            ctx.js("document.querySelector('#line [data-act=trail]') && document.querySelector('#line [data-act=trail]').click()")
            ctx.frames(2)
            listed = ctx.js('window.__skep.overlay().id') == 'trail-list'
            covered['trail'] = ctx.js(LINE_HITS_JS) if listed else None
            ctx.esc()
            under = {k: [x for x in hits if not x['found']] for k, hits in covered.items() if hits is not None}
            r.check(opened and all(covered.values()) and not any(under.values()),
                    f'a {w} px window: with the LEAP box open, then a reading scene, then the trail\'s list opened from the line\'s act, each of the one line\'s parts is the element found at its own centre — none stands over the line\'s rows (issues #310, #475)',
                    {'scene_opened': opened, 'trail_listed': listed, 'covered': under, 'parts': len(covered.get('leap') or [])})
            figures[w] = {'layout': lay, 'acting': act and act['text'], 'acting_opened_lines': unfolded and unfolded['lines'], 'readout': readout and readout['text'][:60],
                          'halt_lines': halt and halt['lines']}
    finally:
        ctx.resize(*was)
        ctx.settle()
    return figures


# the rect of each element the selectors name, in their order, and the window's (`panels_hold`)
RECTS_JS = '''((sels) => ({window: {x: 0, y: 0, w: window.innerWidth, h: window.innerHeight},
  rects: sels.flatMap((s) => [...document.querySelectorAll(s)].map((e) => { const b = e.getBoundingClientRect(); return {sel: s, x: b.left, y: b.top, w: b.width, h: b.height}; }))}))'''


def panels_hold(ctx, r):
    """THE PANELS IN A NARROW WINDOW (FP-26): in each window LINE_ROWS_PX wide, landed at the window run's position in the
    first edition — the LEAP box opened stands whole inside the window, its input too, and the address cell of every row
    and each row's "open beside" stand whole across it; a walk key made there, the ring drawn, the mirror stands opaque
    and whole inside the window below the one line, clear of the walk's element's box; and Mod+F
    there opens the find box whole inside the window, Esc closing it. Its figures: each panel's left and right edges in
    each window"""
    figures = {}
    seen = lambda q: {k: round(v, 1) for k, v in q.items() if k in ('x', 'w')}
    was = ctx.resize(LINE_ROWS_PX[0], 900)
    try:
        for w in LINE_ROWS_PX:
            ctx.resize(w, 900)
            ctx.settle()
            ctx.leap(DOC, WINDOW[0])
            ctx.js('window.__skep.leap.open()')
            ctx.frames(2)
            leap = ctx.js('%s(["#leap", "#leapq", "#leaphits .hit > .go > :first-child", "#leaphits [data-beside]"])' % RECTS_JS)
            ctx.js('window.__skep.leap.close()')
            ctx.frames(2)
            box = [q for q in leap['rects'] if q['sel'] in ('#leap', '#leapq')]
            cells = [q for q in leap['rects'] if q['sel'].endswith(':first-child')]
            acts = [q for q in leap['rects'] if q['sel'].endswith('[data-beside]')]
            win = leap['window']
            past = [q for q in box if not (q['w'] > 0 and inside(q, win))] + [q for q in cells + acts if q['x'] < -LABEL_TOL_PX or q['x'] + q['w'] > win['w'] + LABEL_TOL_PX]
            r.check(len(box) == 2 and bool(cells) and not past,
                    f'a {w} px window: the LEAP box opened stands whole inside the window, its input too, and the address cell of each of its {len(cells)} rows and each of its {len(acts)} "open beside" whole across it (FP-26)',
                    {'past': [dict(seen(q), sel=q['sel']) for q in past[:6]], 'box': [dict(seen(q), sel=q['sel']) for q in box], 'rows': len(cells), 'acts': len(acts), 'vw': win['w']})
            ctx.drv.key('ArrowDown')
            ctx.settle()
            ctx.frames(2)
            mirror = ctx.js('''(() => { const m = document.getElementById('mirror'), e = document.activeElement;
              return {ring: window.__skep.focus().ring, shown: m.classList.contains('shown'), held: !!e && m.contains(e), box: window.__skep.view.ringBox(),
                      opacity: getComputedStyle(m).opacity, top: document.getElementById('line').getBoundingClientRect().bottom}; })()''')
            m = ctx.js('%s(["#mirror"])' % RECTS_JS)
            mq, rb = m['rects'][0], mirror['box']
            clear = not rb or not (mq['x'] < rb['x'] + rb['w'] and rb['x'] < mq['x'] + mq['w'] and mq['y'] < rb['y'] + rb['h'] and rb['y'] < mq['y'] + mq['h'])
            r.check(mirror['ring'] and mirror['shown'] and mirror['held'] and mirror['opacity'] == '1' and mq['w'] > 0 and inside(mq, m['window']) and mq['y'] >= mirror['top'] and clear,
                    f'a {w} px window: a walk key made at the landing, the ring drawn, the mirror stands opaque and whole inside the window below the one line, clear of the walk\'s element\'s box (FP-26; issue #559)',
                    {'mirror': dict(mirror, **seen(mq), y=mq['y'], h=mq['h']), 'vw': m['window']['w']})
            ctx.drv.key('f', mods=('Meta',))
            ctx.js('new Promise((res) => { const t0 = performance.now(); const tick = () => { const s = window.__skep.find.stands(); return (s && !s.reading) || performance.now() - t0 > 15000 ? res(true) : setTimeout(tick, 50); }; tick(); })')
            ctx.frames(2)
            find = ctx.js('%s(["#find"])' % RECTS_JS)
            opened = ctx.js('window.__skep.find.isOpen()')
            ctx.drv.key('Escape')
            ctx.frames(2)
            closed = not ctx.js('window.__skep.find.isOpen()')
            fq = find['rects'][0]
            r.check(opened and closed and fq['w'] > 0 and inside(fq, find['window']),
                    f'a {w} px window: Mod+F at the first edition opens the find box whole inside the window, and Esc closes it (FP-26)',
                    {'find': seen(fq), 'opened': opened, 'closed': closed, 'vw': find['window']['w']})
            figures[w] = {'leap': seen(box[0]) if box else None, 'leap_rows': len(cells), 'mirror': seen(mq), 'find': seen(fq)}
    finally:
        ctx.resize(*was)
        ctx.js('document.activeElement && document.activeElement.blur && document.activeElement.blur()')
        ctx.settle()
    return figures


# how much shorter than the trail's list, in px, the room below the one line is made (`overlay_room_holds`): the list
# measured in a window 900 px tall, the window then set so that the room — from 6 px below the line's bottom edge to 6 px
# above the window's foot — is this much shorter than the list
ROOM_SHORT_PX = 60

# the overlay as it stands (`overlay_room_holds`): its id, its rect, its scroll's height and its view's, the one line's
# bottom edge, the window's height, its rows and the one the focus stands on
OVERLAY_ROOM_JS = '''(() => { const o = document.getElementById('overlay'), q = o.getBoundingClientRect(), rows = [...o.querySelectorAll('[data-run^="j"]')];
  return {id: window.__skep.overlay().id, top: q.top, bottom: q.bottom, h: q.height, scroll: o.scrollHeight, client: o.clientHeight,
          line: document.getElementById('line').getBoundingClientRect().bottom, vh: window.innerHeight, rows: rows.length, at: rows.indexOf(document.activeElement)}; })()'''

# the overlay's row the focus stands on as a person sees it (`overlay_room_holds`): its rect, whether it stands inside the
# window, each scroller between it and the overlay — the overlay too — whose view does not hold it whole, and whether
# the element found at its centre is inside it
ROW_SEEN_JS = '''(() => { const o = document.getElementById('overlay'), a = document.activeElement, rows = [...o.querySelectorAll('[data-run^="j"]')], i = rows.indexOf(a);
  if (i < 0) return null; const q = a.getBoundingClientRect(), clipped = [];
  for (let s = a.parentElement; s && o.contains(s); s = s.parentElement) {
    if (getComputedStyle(s).overflowY === 'visible') continue;
    const b = s.getBoundingClientRect(), top = b.top + s.clientTop;
    if (q.top < top - 0.5 || q.bottom > top + s.clientHeight + 0.5) clipped.push({el: s.id || s.className, top, bottom: top + s.clientHeight, scrolled: s.scrollTop});
  }
  const hit = document.elementFromPoint(q.left + q.width / 2, q.top + q.height / 2);
  return {at: i, last: rows.length - 1, rect: {y: q.top, h: q.height}, inside: q.top >= -0.5 && q.bottom <= window.innerHeight + 0.5, clipped,
          found: !!hit && a.contains(hit), hit: hit ? (hit.id || hit.className || hit.tagName) : null}; })()'''


def overlay_room_holds(ctx, r):
    """AN OVERLAY TALLER THAN THE ROOM BELOW THE ONE LINE (FP-26, FP-20): in a window 1440 px wide, then LINE_ROWS_PX[-1]
    px wide — the one line on several rows — landed at the window run's position in the first edition, the trail's list
    Mod+Y opens in a window 900 px tall is measured; then in a window short enough that the room below the line is
    ROOM_SHORT_PX less than that, the list Mod+Y opens stands with its top below the line's bottom edge and its bottom
    inside the window, scrolling inside itself; and ↓ made from its newest row to its last brings that row into view —
    whole inside every scroller holding it and the window, the element found at its centre inside it. Its figures: the
    list's height in the tall window, and in the short one the window's height, the room, the list's height and its
    rows"""
    figures = {}
    was = ctx.resize(1440, 900)
    try:
        for w in (1440, LINE_ROWS_PX[-1]):
            ctx.resize(w, 900)
            ctx.settle()
            ctx.leap(DOC, WINDOW[0])
            ctx.drv.key('y', mods=('Meta',))
            ctx.settle()
            ctx.frames(2)
            tall = ctx.js(OVERLAY_ROOM_JS)
            ctx.esc()
            if tall['id'] != 'trail-list':
                r.check(False, f'a {w} px window 900 px tall: Mod+Y opens the trail\'s list', tall)
                continue
            vh = int(tall['line'] + 12 + tall['h'] - ROOM_SHORT_PX)
            ctx.resize(w, vh)
            ctx.settle()
            ctx.drv.key('y', mods=('Meta',))
            ctx.settle()
            ctx.frames(2)
            short = ctx.js(OVERLAY_ROOM_JS)
            room = short['vh'] - short['line'] - 12
            r.check(short['id'] == 'trail-list' and tall['h'] - room >= ROOM_SHORT_PX - 20 and short['top'] >= short['line'] - LABEL_TOL_PX
                    and short['bottom'] <= short['vh'] + LABEL_TOL_PX and short['scroll'] > short['client'],
                    f'a {w} px window {vh} px tall, the room below the one line {round(room)} px for a list {round(tall["h"])} px tall: the trail\'s list Mod+Y opens stands with its top below the line\'s bottom edge and its bottom inside the window, scrolling inside itself (issue #481)',
                    {'tall': tall, 'short': short, 'room': room})
            for _ in range(short['rows'] + 2):
                if ctx.js(OVERLAY_ROOM_JS)['at'] >= short['rows'] - 1:
                    break
                ctx.drv.key('ArrowDown')
            ctx.frames(2)
            seen = ctx.js(ROW_SEEN_JS)
            ctx.esc()
            r.check(bool(seen) and seen['at'] == seen['last'] and seen['inside'] and not seen['clipped'] and seen['found'],
                    f'a {w} px window {vh} px tall: ↓ made from the list\'s newest row to its last brings that row into view, whole inside every scroller holding it and the window, the element at its centre inside it (FP-20; issue #481)',
                    seen)
            figures[w] = {'list_900': round(tall['h'], 1), 'window_h': vh, 'room': round(room, 1), 'list': round(short['h'], 1), 'rows': short['rows']}
    finally:
        ctx.resize(*was)
        ctx.js('document.activeElement && document.activeElement.blur && document.activeElement.blur()')
        ctx.settle()
    return figures


# what `leap_room_holds` types in the LEAP box: every address in the owner's account begins with it, so the list runs to its
# limit of rows, more than it shows in any window
LEAP_LIST_TEXT = '1.0.1.0.'
# the room below the one line's bottom edge in `leap_room_holds`' short window, in px: the window 260 px tall where the line
# stands on one row
LEAP_SHORT_ROOM_PX = 231
# the gap above the rows' list, in px: the margin the box sets above it
LEAP_GAP_PX = 6

# the LEAP box as it stands (`leap_room_holds`): whether it is open with the focus in its input, the one line's bottom edge,
# the window's height, the box's edges, its input's height and the gap above the rows' list, the list's scroll and view,
# its rows, and the row chosen as a person sees it — its place in the list, its edges from the top of the list's view,
# its height, and whether the element found at the middle of its part in view is inside it
LEAP_ROOM_JS = """(() => { const input = document.getElementById('leapq'), list = document.getElementById('leaphits'), b = document.getElementById('leap').getBoundingClientRect();
  const q = input.getBoundingClientRect(), n = document.getElementById('leapnote').getBoundingClientRect(), l = list.getBoundingClientRect(), from = l.top + list.clientTop;
  const rows = [...list.children], row = list.querySelector('[aria-selected="true"]');
  let chosen = null;
  if (row) { const c = row.getBoundingClientRect(), hit = document.elementFromPoint(c.left + c.width / 2, c.top + Math.min(c.height, list.clientHeight) / 2);
    chosen = {at: rows.indexOf(row), top: c.top - from, bottom: c.bottom - from, h: c.height, found: !!hit && row.contains(hit), hit: hit ? (hit.id || hit.className || hit.tagName) : null}; }
  return {open: window.__skep.leap.isOpen(), held: document.activeElement === input, line: document.getElementById('line').getBoundingClientRect().bottom, vh: window.innerHeight,
          top: b.top, bottom: b.bottom, input: q.height, gap: l.top - (n.height ? n.bottom : q.bottom), scroll: list.scrollHeight, view: list.clientHeight, scrolled: list.scrollTop, rows: rows.length, chosen}; })()"""


def leap_chosen_seen(s):
    """does the row chosen stand whole in the list's view — a row taller than the view its top on the view's — the element
    found at its middle inside it?"""
    c = s['chosen']
    return bool(c) and c['found'] and c['top'] >= -LABEL_TOL_PX and (c['bottom'] <= s['view'] + LABEL_TOL_PX or (c['h'] > s['view'] and c['top'] <= LABEL_TOL_PX))


def leap_room_holds(ctx, r):
    """THE LEAP BOX IN A SHORT WINDOW AND ITS ROW CHOSEN (FP-26): in a window 1440 px wide, then LINE_ROWS_PX[-1] px wide — the
    one line on several rows — and 900 px tall, ↓ made down a list longer than its view brings each row into view, its last
    whole in the list and found at its middle; a new list typed stands at its first row, and the box closed and opened again
    at the top of its list, no row chosen. In a window short enough that the box cannot stand at its full height the box
    stands below the line and inside the window, its input as tall and the gap above its rows as in the tall window, its
    list the part that gave way and scrolling inside itself; the shortening keeps the row chosen in view, and ↓ made down a
    new list there brings its last row into view. Its figures: the window's height and the list's view in each window"""
    figures = {}
    state = lambda: ctx.js(LEAP_ROOM_JS)

    def typed(text):
        ctx.js('(() => { document.getElementById("leapq").value = ""; })()')
        ctx.drv.ime(text)
        ctx.frames(2)
        return state()

    def to_last():
        """↓ made until the list's last row is the one chosen; the box as it then stands"""
        s = state()
        for _ in range(s['rows'] + 2):
            if s['chosen'] and s['chosen']['at'] >= s['rows'] - 1:
                break
            ctx.drv.key('ArrowDown')
            s = state()
        ctx.frames(2)
        return state()

    was = ctx.resize(1440, 900)
    try:
        for w in (1440, LINE_ROWS_PX[-1]):
            ctx.resize(w, 900)
            ctx.settle()
            ctx.js('window.__skep.leap.open()')
            ctx.frames(2)
            tall = typed(LEAP_LIST_TEXT)
            r.check(tall['open'] and tall['held'] and tall['scroll'] > tall['view'] and bool(tall['chosen']) and tall['chosen']['at'] == 0 and tall['scrolled'] == 0,
                    f'a {w} px window 900 px tall: {LEAP_LIST_TEXT} typed in the LEAP box lists more than its list shows, the first row chosen at the list\'s top (what the next checks stand on)', tall)
            last = to_last()
            r.check(last['chosen']['at'] == last['rows'] - 1 and leap_chosen_seen(last),
                    f'a {w} px window 900 px tall: ↓ made down the LEAP box\'s list leaves its last row whole in the list\'s view, the element at its middle inside it (issue #511)', last)
            ctx.js('document.getElementById("leapq").select()')
            ctx.drv.key('e')
            ctx.frames(2)
            retyped = state()
            r.check(retyped['scroll'] > retyped['view'] and bool(retyped['chosen']) and retyped['chosen']['at'] == 0 and retyped['scrolled'] == 0 and leap_chosen_seen(retyped),
                    f'a {w} px window 900 px tall: a list typed after ↓ stands at its first row, chosen and in view (issue #511)', retyped)
            scrolled = to_last()['scrolled']
            ctx.drv.key('Escape')
            ctx.frames(2)
            ctx.js('window.__skep.leap.open()')
            ctx.frames(2)
            again = state()
            r.check(scrolled > 0 and again['open'] and again['chosen'] is None and again['scrolled'] == 0 and again['scroll'] > again['view'],
                    f'a {w} px window 900 px tall: the box closed at the foot of its list and opened again stands at the top of a list longer than its view, no row chosen (issue #511)', {'scrolled_before': scrolled, 'again': again})
            typed(LEAP_LIST_TEXT)
            to_last()
            vh = math.ceil(tall['line']) + LEAP_SHORT_ROOM_PX
            ctx.resize(w, vh)
            ctx.settle()
            ctx.frames(2)
            short = state()
            r.check(short['open'] and short['held'] and short['top'] >= short['line'] - LABEL_TOL_PX and short['bottom'] <= short['vh'] + LABEL_TOL_PX
                    and short['view'] < tall['view'] and short['scroll'] > short['view'] and abs(short['input'] - tall['input']) <= LABEL_TOL_PX
                    and abs(short['gap'] - LEAP_GAP_PX) <= LABEL_TOL_PX and abs(tall['gap'] - LEAP_GAP_PX) <= LABEL_TOL_PX,
                    f'a {w} px window {vh} px tall: the LEAP box stands below the one line and inside the window, its input as tall and the gap above its rows {LEAP_GAP_PX} px as in the tall window, its list giving way and scrolling inside itself (issue #511)',
                    {'tall': tall, 'short': short})
            r.check(bool(short['chosen']) and short['chosen']['at'] == short['rows'] - 1 and leap_chosen_seen(short),
                    f'a {w} px window shortened to {vh} px: the row chosen stands in view of the list\'s shorter view (issue #511)', short)
            typed(LEAP_LIST_TEXT)
            low = to_last()
            r.check(low['chosen']['at'] == low['rows'] - 1 and leap_chosen_seen(low),
                    f'a {w} px window {vh} px tall: ↓ made down a new list leaves its last row whole in the list\'s view, the element at its middle inside it (issue #511)', low)
            ctx.drv.key('Escape')
            ctx.frames(2)
            figures[w] = {'window_h': vh, 'list_900': tall['view'], 'list': short['view'], 'rows': short['rows']}
    finally:
        ctx.js('window.__skep.leap.close()')
        ctx.resize(*was)
        ctx.js('document.activeElement && document.activeElement.blur && document.activeElement.blur()')
        ctx.settle()
    return figures


def trail_view(ctx):
    """the plane's canvas along the segment between the trail's two newest entries, as far as the segment runs on screen
    inside the first edition's box, TRAIL_INSET_PX inside its edges, the disc about every entry's point left out: the
    pixels read, and those that are not the box's ground as P-REG gives it"""
    return ctx.js('''(async () => {
      const R = await import('./plane/register.js');
      const S = window.__skep, c = S.view.camera(), p = S.view.viewport(), t = S.trail(), n = t.entries.length;
      if (n < 2) return null;
      const scr = (v) => ({x: (v.x - c.x) * c.scale + p.VW / 2, y: (v.y - c.y) * c.scale + p.VH / 2});
      const a = scr(t.entries[n - 2].view), b = scr(t.entries[n - 1].view), pips = t.entries.map((e) => scr(e.view));
      const q = S.boxOf(%s), box = {x: (q.x - c.x) * c.scale + p.VW / 2, y: (q.y - c.y) * c.scale + p.VH / 2, w: q.w * c.scale, h: q.h * c.scale};
      const x0 = Math.max(0, box.x + %s), x1 = Math.min(p.VW, box.x + box.w - %s), y0 = Math.max(0, box.y + %s), y1 = Math.min(p.VH, box.y + box.h - %s);
      const cv = document.getElementById('plane'), k = cv.width / p.VW, img = cv.getContext('2d').getImageData(0, 0, cv.width, cv.height).data;
      const ground = [1, 3, 5].map((i) => parseInt(R.COL.doc.slice(i, i + 2), 16));
      const len = Math.hypot(b.x - a.x, b.y - a.y), ux = (b.x - a.x) / len, uy = (b.y - a.y) / len;
      let read = 0, other = 0; const off = [];
      for (let s = 0; s <= len; s += 0.5) for (let o = -%s; o <= %s; o += 0.5) {
        const x = a.x + ux * s - uy * o, y = a.y + uy * s + ux * o;
        if (x < x0 || x >= x1 || y < y0 || y >= y1 || pips.some((e) => Math.hypot(x - e.x, y - e.y) < %s)) continue;
        const i = (Math.floor(y * k) * cv.width + Math.floor(x * k)) * 4;
        read++;
        if (img[i] !== ground[0] || img[i + 1] !== ground[1] || img[i + 2] !== ground[2]) { other++; if (off.length < 8) off.push({x: Math.round(x), y: Math.round(y), rgb: [img[i], img[i + 1], img[i + 2]]}); }
      }
      return {a, b, box, ground, read, other, off};
    })()''' % (json.dumps(DOC), TRAIL_INSET_PX, TRAIL_INSET_PX, TRAIL_INSET_PX, TRAIL_INSET_PX, TRAIL_STRIP_PX, TRAIL_STRIP_PX, PIP_CLEAR_PX))


def trail_holds(ctx, r):
    """THE TRAIL's check: two consecutive entries in the first edition at two views, the camera at the newer, the
    article mounted over the box; its figures"""
    ctx.leap(DOC, 1)
    ctx.leap(DOC, WINDOW[0])
    v = trail_view(ctx)
    mounted = DOC in ctx.js('window.__skep.mountedAddrs()')
    r.check(bool(v) and mounted and v['read'] >= 100 and not v['other'],
            f'the trail: no path runs between its pips — along the segment between two consecutive entries in the first edition, a {2 * TRAIL_STRIP_PX:g} px strip inside its box and {PIP_CLEAR_PX} px clear of every entry\'s point, the canvas under the mounted article holds the box\'s ground alone',
            {'mounted': mounted, 'read': v and v['read'], 'other': v and v['other'], 'off': v and v['off'], 'segment': v and [v['a'], v['b']], 'box': v and v['box']})
    return {'read': v and v['read'], 'other': v and v['other']}


def stub_view(ctx):
    """the mid connections the last frame drew beside the projection's places, read in the page apart from the canvas's
    set: the visible view below the one line; the place holding FAR_LEAP at the camera's scale — its outline (issue #15:
    a document's place on the plane is its columns), or the mark of
    the continuation holding it (P-LOD's `residueDepth`, P-PROJ's `withinContinuation`) — whether its centre stands in
    that view and whether its cell meets the view the frame draws (the viewport padded by 80 px); each document standing
    whole, its box's centre in view, that a link joins to FAR_LEAP — drawn at either of the two, LK's `draws` — with the
    links its own links name that join it to a document the plane draws and that place holds, each drawn at either of its
    two documents; each connection's places' centres and whether each stands in view;
    the box's ground and the plane's own, and the plane canvas's pixel at each stub's triangle's centroid beside the hue
    and alpha of the last stub drawn whose triangle holds it"""
    return ctx.js('''(async () => {
      const P = await import('./plane/projection.js'), D = await import('./plane/lod.js'), A = await import('./model/address.js'), R = await import('./plane/register.js');
      const S = window.__skep, c = S.view.camera(), p = S.view.viewport(), top = document.getElementById('line').getBoundingClientRect().bottom;
      const view = {x: 0, y: top, w: p.VW, h: p.VH - top};
      const pad = {x0: (-80 - p.VW / 2) / c.scale + c.x, y0: (-80 - p.VH / 2) / c.scale + c.y, x1: (p.VW / 2 + 80) / c.scale + c.x, y1: (p.VH / 2 + 80) / c.scale + c.y};
      const held = D.residueDepth(c.scale).held;
      const placeOf = (doc) => (P.withinContinuation(doc, held) ? A.accountOf(doc) + ':' + held : doc);
      const cell = (place) => { const i = place.indexOf(':'); return i < 0 ? S.fold(place).outline : P.continuationCell(place.slice(0, i), Number(place.slice(i + 1))); };
      const centre = (place) => { const b = cell(place); return {x: (b.x + b.w / 2 - c.x) * c.scale + p.VW / 2, y: (b.y + b.h / 2 - c.y) * c.scale + p.VH / 2}; };
      const seen = (q) => q.x >= view.x && q.x <= view.x + view.w && q.y >= view.y && q.y <= view.y + view.h;
      const indexed = new Set(S.model.places().filter((q) => !q.system).map((q) => q.doc));
      const drawable = (doc) => { if (indexed.has(doc)) return true; const d = S.model.doc(doc); return d.from >= 0 || !!d.meta || d.refused === 'withheld'; };
      const docOf = (e) => (e.doc ? A.documentOf(e.doc) || e.doc : null);
      const joins = (l) => [[l.from, l.to], [l.to, l.from]].flatMap(([ends, others]) => ends.filter((e) => !e.whole && e.ordinal != null && e.doc)
        .flatMap((e) => others.map(docOf).filter((y) => y && y !== e.doc).map((y) => [e.doc, y])));
      /** the passage links a document's links name that join it to a document `to` admits, each drawn at either of its two documents (LK's `draws`) */
      const joining = (doc, to) => S.model.doc(doc).links.filter((la) => { const l = S.model.link(la); return !!l && S.links.classify(la) === 'passage'
        && joins(l).some(([x, y]) => (x === doc || y === doc) && to(x === doc ? y : x) && (S.links.draws(la, x) || S.links.draws(la, y))); });
      const far = placeOf(%s);
      const citers = [...indexed].filter((doc) => placeOf(doc) === doc && seen(centre(doc)) && joining(doc, (f) => f === %s).length)
        .map((doc) => ({doc, links: joining(doc, (f) => drawable(f) && placeOf(f) === far)}));
      const cv = document.getElementById('plane'), k = cv.width / p.VW, img = cv.getContext('2d').getImageData(0, 0, cv.width, cv.height).data;
      const px = (q) => { const i = (Math.floor(q.y * k) * cv.width + Math.floor(q.x * k)) * 4; return [img[i], img[i + 1], img[i + 2]]; };
      const rgb = (hex) => [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16));
      const holds = (q, t) => { const s = (a, b) => (b.x - a.x) * (q.y - a.y) - (b.y - a.y) * (q.x - a.x); const d = [s(t[0], t[1]), s(t[1], t[2]), s(t[2], t[0])]; return d.every((x) => x >= 0) || d.every((x) => x <= 0); };
      const drawn = S.connections(), tris = drawn.filter((x) => x.stub).map((x) => x.stub);
      const conns = drawn.map((x) => {
        const ca = centre(x.a), cb = centre(x.b), t = x.stub && x.stub.triangle;
        const at = t ? {x: (t[0].x + t[1].x + t[2].x) / 3, y: (t[0].y + t[1].y + t[2].y) / 3} : null;
        const over = at ? tris.filter((u) => holds(at, u.triangle)).pop() : null;
        return {a: x.a, b: x.b, count: x.count, label: x.label ?? null, stub: x.stub, in_a: seen(ca), in_b: seen(cb), centre_a: ca, centre_b: cb, centroid: at, pixel: at ? px(at) : null,
                ink: over ? rgb(over.hue) : null, ink_alpha: over ? over.alpha : null};
      });
      const there = centre(far);
      return {view, held, far, far_centre: there, far_in_view: seen(there), far_drawn: P.intersects(cell(far), pad), citers, conns, grounds: [rgb(R.COL.doc), rgb(R.COL.bg)]};
    })()''' % (json.dumps(FAR_LEAP), json.dumps(FAR_LEAP)))


def stub_holds(ctx, r):
    """THE STUB's checks at mid scale, the camera over the first edition at S3's mid-extents (its box 90 px): the
    citations of FAR_LEAP, an edition the index lists, from the documents standing whole in view — the place holding it
    out of view, so nothing the frame draws stands there; its figures, among them the stubs met on the visible view's top
    border — none where nothing at this view is bound above it, camera.test.js then holding that rule alone"""
    ctx.view_doc_px(DOC, 90)
    v = stub_view(ctx)
    view, far, conns, citers = v['view'], v['far'], v['conns'], v['citers']
    pair = {cit['doc']: next((c for c in conns if {c['a'], c['b']} == {cit['doc'], far}), None) for cit in citers}
    unbound = [doc for doc, c in pair.items() if not (c and c['stub'] and c['stub']['toward'] == far)]
    r.check(bool(citers) and not v['far_in_view'] and not v['far_drawn'] and not unbound,
            f'mid scale: every document standing whole in view that a link joins to {FAR_LEAP} — drawn at either of the two — the place holding {FAR_LEAP} ({far}) out of view, and out of the view the frame draws, is joined to that place by a connection ending in a stub bound for it',
            {'far': far, 'far_centre': v['far_centre'], 'far_drawn': v['far_drawn'], 'citers': [cit['doc'] for cit in citers], 'unbound': unbound,
             'connections': [[c['a'], c['b'], c['count'], bool(c['stub'])] for c in conns][:12]})
    stubs = [c for c in conns if c['stub']]
    x0, y0 = view['x'] + STUB_INSET_PX, view['y'] + STUB_INSET_PX
    x1, y1 = view['x'] + view['w'] - STUB_INSET_PX, view['y'] + view['h'] - STUB_INSET_PX
    def near(c):
        """the centre of the place in view a stub's stroke leaves"""
        return c['centre_a'] if c['in_a'] else c['centre_b']
    def at_start(c):
        """does the stub's stroke leave the view's inset at its start — the centre of the place in view standing nearer the
        border than STUB_INSET_PX — where P-CAM's `edgeStub` cuts it at that start, no room between it and the border"""
        d, q = near(c), c['stub']['cut']
        return not (x0 <= d['x'] <= x1 and y0 <= d['y'] <= y1) and abs(q['x'] - d['x']) <= STUB_TOL_PX and abs(q['y'] - d['y']) <= STUB_TOL_PX
    def on_border(q):
        return x0 - STUB_TOL_PX <= q['x'] <= x1 + STUB_TOL_PX and y0 - STUB_TOL_PX <= q['y'] <= y1 + STUB_TOL_PX and min(abs(q['x'] - x0), abs(q['x'] - x1), abs(q['y'] - y0), abs(q['y'] - y1)) <= STUB_TOL_PX
    off_border = [[c['a'], c['b'], c['stub']['cut']] for c in stubs if not (on_border(c['stub']['cut']) or at_start(c))]
    r.check(bool(stubs) and not off_border, f'every stub\'s cut lies {STUB_INSET_PX} px inside the visible view\'s border — the viewport below the one line — {STUB_TOL_PX} px either way; at its start where the place in view\'s centre itself stands nearer the border than that', {'off': off_border[:6], 'view': view, 'at_start': [[c['a'], c['b']] for c in stubs if at_start(c)]})
    def bearing(c):
        """the angle, in degrees, between the stub's cut and the true bearing from the place in view's centre to the other's"""
        d, f = (c['centre_a'], c['centre_b']) if c['in_a'] else (c['centre_b'], c['centre_a'])
        q = c['stub']['cut']
        a1, a2 = math.atan2(q['y'] - d['y'], q['x'] - d['x']), math.atan2(f['y'] - d['y'], f['x'] - d['x'])
        return abs(math.degrees(math.atan2(math.sin(a1 - a2), math.cos(a1 - a2))))
    angles = {(c['a'], c['b']): (0.0 if at_start(c) else bearing(c)) for c in stubs}
    askew = {'%s|%s' % k: a for k, a in angles.items() if a > STUB_BEARING_DEG}
    r.check(bool(stubs) and not askew, f'every stub stands on the true bearing: its cut on the ray from the centre of the place in view to the centre of the place it is bound for, as the projection gives them, within {STUB_BEARING_DEG}° — a cut at its start on no ray to measure', askew)
    miscount = [{'doc': cit['doc'], 'count': pair[cit['doc']] and pair[cit['doc']]['count'], 'links': cit['links']} for cit in citers if not (pair[cit['doc']] and cit['links'] and pair[cit['doc']]['count'] == len(cit['links']))]
    r.check(bool(citers) and not miscount, 'each such document\'s connection to that place counts the links joining it to a document the plane draws and the place holds, each drawn at either of its two documents (LK\'s `draws`), each once', miscount)
    uncarried = [{'doc': cit['doc'], 'links': len(cit['links']), 'carries': pair[cit['doc']] and pair[cit['doc']]['label']} for cit in citers
                 if (pair[cit['doc']] and pair[cit['doc']]['label']) != (str(len(cit['links'])) if len(cit['links']) >= 2 else None)]
    r.check(any(len(cit['links']) >= 2 for cit in citers) and not uncarried, 'each such document\'s stub carries that count on its stroke where it holds two links or more — the numeral of those links — and none where it holds one',
            {'uncarried': uncarried, 'citers': {cit['doc']: len(cit['links']) for cit in citers}})
    wrong = [{'a': c['a'], 'b': c['b'], 'in_a': c['in_a'], 'in_b': c['in_b'], 'stub': c['stub'] and c['stub']['toward']} for c in conns
             if (c['in_a'] != c['in_b']) != bool(c['stub']) or (c['stub'] and c['stub']['toward'] != (c['b'] if c['in_a'] else c['a']))]
    r.check(bool(stubs) and not wrong, 'every connection with one place in the visible view and the other out of it, and no other, ends in a stub bound for the place out of view: none is bound for a place in view', wrong[:6])
    def inked(c):
        """is the plane's pixel at the stub's centroid the triangle drawn last over it: its hue at full alpha, else neither ground"""
        pix, ink = c['pixel'], c['ink']
        return bool(pix and ink) and (all(abs(pix[i] - ink[i]) <= STUB_INK_TOL for i in range(3)) if c['ink_alpha'] == 1 else pix not in v['grounds'])
    unseen = [{'a': c['a'], 'b': c['b'], 'centroid': c['centroid'], 'pixel': c['pixel'], 'hue': c['ink'], 'alpha': c['ink_alpha']} for c in stubs if not inked(c)]
    r.check(bool(stubs) and not unseen, 'every stub\'s triangle is drawn over the boxes at the view\'s border: the plane\'s pixel at its centroid is the hue of the last triangle drawn there, at full alpha, and neither the box\'s ground nor the plane\'s at less', {'unseen': unseen[:6], 'grounds': v['grounds']})
    top = [[c['a'], c['b'], c['stub']['cut']] for c in stubs if abs(c['stub']['cut']['y'] - y0) <= STUB_TOL_PX]
    return {'connections': len(conns), 'stubs': [[c['a'], c['b'], c['count'], c['label'], c['stub']['cut'], round(angles[(c['a'], c['b'])], 4), c['pixel']] for c in stubs],
            'far': far, 'held': v['held'], 'citers': {cit['doc']: len(cit['links']) for cit in citers},
            'top_border': top or 'unmeasured: no stub at this view is bound above the visible view\'s top'}


def measure_view(ctx):
    """THE MEASURE as a person meets it (issue #15: every document set at one line length): each mounted article's
    columns, each one's width in its face's average advance as the case probes it in one of its paragraphs
    (`ADVANCE_JS`: a run of the weighed sample, whose box rounds to the engine's grid no more than a single glyph's
    does) — at the layout size"""
    return ctx.js('''(() => { const S = window.__skep, out = [], advance = %s;
      for (const a of S.mountedAddrs()) {
        const m = S.mounted(a), art = document.querySelector(`#domlayer article.dtext[data-addr="${a}"]`);
        if (!m || !art) continue;
        const s = S.view.camera().scale / m.lay, para = art.querySelector('.run > p.sp'), ch = para ? advance(para, s) : null;
        const cols = [...art.querySelectorAll('.col')].map((c) => c.getBoundingClientRect().width / s);
        out.push({addr: a, ch, columns: cols.length, cpl: ch ? cols.map((w) => Math.round((w / ch) * 1000) / 1000) : null});
      }
      return out; })()''' % ADVANCE_JS)


def measure_holds(r, name, v):
    """every mounted column at the measure: a whole count of its face's average advance, in the design's 60–66, one for
    every column of every article"""
    cpl = [c for a in v for c in (a['cpl'] or [])]
    off = [a for a in v if not a['cpl'] or any(not (MEASURE_CH[0] - MEASURE_CH_TOL <= c <= MEASURE_CH[1] + MEASURE_CH_TOL) or abs(c - round(c)) > MEASURE_CH_TOL for c in a['cpl'])]
    r.check(bool(cpl) and not off and max(cpl) - min(cpl) <= 2 * MEASURE_CH_TOL,
            f'{name}: every mounted column sets the measure — {MEASURE_CH[0]}–{MEASURE_CH[1]} of its face\'s average advance as the case probes it, a whole count, one measure for every column of every article',
            {'articles': v[:8], 'off': off[:4]})
    return {'articles': len(v), 'columns': len(cpl), 'cpl': sorted(set(round(c, 3) for c in cpl))}


def hold_holds(ctx, r):
    """THE PASSAGE IN VIEW KEEPS ITS PLACE (issue #15: "when a document re-sets while in view, the passage in view keeps
    its place and size on screen"): a document whose links' symbols re-break its lines — the first edition, else the
    first of the documents its citations reach and the longest edition whose reveal moves a paragraph in its room, found
    by setting the symbols and taking them off — at em 12.5, the last paragraph they move under the view's centre, its
    links revealed to their symbols: the line under the view's centre stands where it stood on screen, DRIFT_TOL_PX either
    way, at its em; its figures. Where no such document reveals a moved paragraph on this board the check is left
    unmeasured, and the figures say so: layer.test.js holds the rule over the page's own fold"""
    longest, _, _ = ctx.longest_edition()
    candidates = [DOC] + [s['far'] for s in ctx.js('window.__skep.links.shown(%s)' % json.dumps(DOC)) if s['far']] + ([longest] if longest else [])
    tried = []
    for doc in dict.fromkeys(candidates):
        ctx.leap(doc)
        blocks = [b for b in ctx.js('window.__skep.model.doc(%s).blocks' % json.dumps(doc)) if b['kind'] == 'para' and b['text'].strip()]
        if not blocks or not ctx.js('window.__skep.links.shown(%s).length' % json.dumps(doc)):
            tried.append([doc, 'no link drawn'])
            continue
        ctx.view_doc_em(doc, 12.5)
        places = lambda: [ctx.js('window.__skep.centreOf(%s, %d)' % (json.dumps(doc), b['pos'])) for b in blocks]
        hidden = places()
        ctx.js('window.__skep.links.reveal(%s, 2)' % json.dumps(doc))
        ctx.settle()
        shown = places()
        ctx.js('window.__skep.links.hide(%s)' % json.dumps(doc))
        ctx.settle()
        ctx.frames(2)
        moves = [b for b, h, w in zip(blocks, hidden, shown) if math.hypot(w['x'] - h['x'], w['y'] - h['y']) > 1]
        tried.append([doc, len(moves)])
        if moves:
            break
    else:
        r.note('the hold through a re-set is unmeasured on this board: no document tried reveals a paragraph its symbols move (%s); layer.test.js holds the rule' % tried)
        return {'unmeasured': tried}
    later = moves[-1]
    ctx.view_at(doc, later['pos'])
    cam = ctx.camera()
    pos = ctx.js('window.__skep.posAt(%s, %s, %s)' % (json.dumps(doc), cam['x'], cam['y']))
    def seen():
        """where the passage's first character stands now: on screen, and in the plane"""
        return ctx.js('''((a, p) => { const S = window.__skep, q = (S.spanRects(a, p, 1) || []).find((x) => x.w > 0 && x.h > 0), m = S.mounted(a);
          return {line: q || null, place: S.centreOf(a, p), em: m ? m.fs * S.view.camera().scale : null}; })(%s, %s)''' % (json.dumps(doc), json.dumps(pos)))
    before = seen()
    ctx.js('window.__skep.links.reveal(%s, 2)' % json.dumps(doc))
    ctx.settle()
    ctx.frames(3)
    after = seen()
    ctx.js('window.__skep.links.hide(%s)' % json.dumps(doc))
    ctx.settle()
    ctx.frames(2)
    moved = bool(before['place'] and after['place']) and math.hypot(after['place']['x'] - before['place']['x'], after['place']['y'] - before['place']['y']) > 1
    kept = bool(before['line'] and after['line']) and abs(after['line']['y'] - before['line']['y']) <= DRIFT_TOL_PX and before['em'] and after['em'] and abs(after['em'] - before['em']) <= 1e-6
    r.check(pos is not None and moved and kept,
            f'a reveal that re-breaks {doc} while a paragraph its symbols move is read — they move the passage in its room — leaves the line under the view\'s centre where it stood on screen, {DRIFT_TOL_PX} px either way, at its em',
            {'doc': doc, 'pos': pos, 'block': later['pos'], 'blocks_moved': [b['pos'] for b in moves], 'tried': tried, 'before': before, 'after': after, 'moved_in_the_plane': moved})
    return {'doc': doc, 'pos': pos, 'tried': tried, 'before': before, 'after': after}


def bare_holds(ctx, r):
    """ROWS NAMING NOTHING (issue #212's design decision: "A bare row only marks its board. Once the feed has delivered
    what it has, one refresh runs, however many rows were bare"; "What is shown stays until its fresh read lands. Then it
    is set in one step, with the words being read held still: no blanking and no lost place"): the first edition at its
    bare address, at em 12.5 over a paragraph of its own; three rows naming no document and no link — an op unnamed, a
    `nullify` and a `version` by their op alone — handed to the page through the gate's feed door as the feed hands rows,
    reads alone, in one evaluation: no read goes out as they come; once the run is in, one refresh counts the edition's
    chain, each member's metadata asked once, and — where the board answers each member's mint position, or the page holds
    the chain's end, either telling the member the text is — reads the edition's text window again once, else leaves it as
    it stands and reads none of it; its article standing in every frame from the rows to the settle, the line under the
    view's centre where it stood on screen, DRIFT_TOL_PX either way, at its em; its figures"""
    ctx.leap(DOC)
    shown = ctx.js('window.__skep.go.shownIn(%s)' % json.dumps(DOC))
    r.check(shown == DOC, 'the first edition\'s box shows its plain address: its text is what its bare address answered', shown)
    ctx.view_doc_em(DOC, 12.5)
    blocks = [b for b in ctx.js('window.__skep.model.doc(%s).blocks' % json.dumps(DOC)) if b['kind'] == 'para' and b['text'].strip()]
    ctx.view_at(DOC, blocks[len(blocks) // 2]['pos'])
    cam = ctx.camera()
    pos = ctx.js('window.__skep.posAt(%s, %s, %s)' % (json.dumps(DOC), cam['x'], cam['y']))

    def seen():
        """where the passage under the view's centre stands now: its line on screen, and the article's em"""
        return ctx.js('''((a, p) => { const S = window.__skep, q = (S.spanRects(a, p, 1) || []).find((x) => x.w > 0 && x.h > 0), m = S.mounted(a);
          return {line: q || null, em: m ? m.fs * S.view.camera().scale : null}; })(%s, %s)''' % (json.dumps(DOC), json.dumps(pos)))
    before = seen()
    held = ctx.js('(() => { const d = window.__skep.model.doc(%s); return {members: d.members, ended: d.ended}; })()' % json.dumps(DOC))
    rows = [{'position': 0, 'at': 0, 'op': op, 'docs': None, 'class': 'published'} for op in (None, 'nullify', 'version')]
    came = ctx.js('''((rows, a) => { const S = window.__skep, n = S.bridge.calls().length;
      window.__gateBare = {frames: 0, standing: 0, stop: false};
      const watch = () => { const g = window.__gateBare; if (g.stop) return; g.frames++; const m = S.mounted(a); if (m && m.text) g.standing++; requestAnimationFrame(watch); };
      requestAnimationFrame(watch);
      for (const row of rows) S.model.feed(row);
      return {n, calls: S.bridge.calls().length - n}; })(%s, %s)''' % (json.dumps(rows), json.dumps(DOC)))
    ctx.settle()
    ctx.frames(3)
    watched = ctx.js('(() => { const g = window.__gateBare; g.stop = true; return {frames: g.frames, standing: g.standing}; })()')
    after = seen()
    calls = [c for c in ctx.js('window.__skep.bridge.calls()')[came['n']:] if c.get('frame')]
    frames = [json.loads(c['frame']) for c in calls]
    member = lambda f: f.get('op') == 'doc_metadata' and f.get('doc', '').startswith(DOC + '.') and f['doc'].count('.') == DOC.count('.') + 1
    members = [f['doc'] for f in frames if member(f)]
    answers = [json.loads(c['answer']) for c, f in zip(calls, frames) if member(f) and c.get('answer')]
    minted = any(isinstance(a.get('result'), dict) and a['result'].get('at') is not None for a in answers)
    texts = [f for f in frames if f.get('op') == 'retrieve_v' and (f.get('specs') or [{}])[0].get('doc') == DOC]
    told = minted or bool(held['ended'])
    r.check(came['calls'] == 0, 'three rows naming nothing, handed to the page together: no read goes out as they come — they mark the board (issue #212)', came)
    r.check(bool(members) and len(set(members)) == len(members), 'once the run is in, one refresh counts the first edition\'s chain: each member\'s metadata asked once', members)
    r.check(len(texts) == (1 if told else 0),
            'the edition\'s text window read again once, the member its text is told by '
            + ('the board\'s mint positions' if minted else 'the chain\'s end the page held') if told else
            'the board answering no mint position and the page holding no chain\'s end, the edition left as it stands, none of its text read',
            {'texts': len(texts), 'minted': minted, 'held': held})
    r.check(watched['frames'] > 0 and watched['standing'] == watched['frames'], 'the first edition\'s article stands in every frame from the rows to the settle: nothing shown is emptied while its read is out', watched)
    kept = bool(before['line'] and after['line']) and abs(after['line']['y'] - before['line']['y']) <= DRIFT_TOL_PX and before['em'] and after['em'] and abs(after['em'] - before['em']) <= 1e-6
    r.check(pos is not None and kept, f'the line under the view\'s centre stands where it stood on screen, {DRIFT_TOL_PX} px either way, at its em', {'pos': pos, 'before': before, 'after': after})
    return {'pos': pos, 'members': members, 'minted': minted, 'held': held, 'texts': len(texts), 'frames': watched, 'before': before, 'after': after,
            'reads': sorted(set(f.get('op') for f in frames))}


def named_holds(ctx, r):
    """A ROW NAMING A DOCUMENT THE VIEW SHOWS (issue #285's design decision: "Nothing is taken down to wait. Everything last
    set stays, unmarked: text, marks, beams, corner, faces, clauses"; "`pump.js` stops dropping shown documents. `layer.js`
    keeps them until the re-read sets them"): the first edition at em 12.5 over a paragraph of its own; a published row
    naming it, handed to the page through the gate's feed door as the feed hands rows, reads alone: the model holds its
    text in every frame from the row to the settle, and its article and its corner stand in every one, its beams as many
    as stood before; its text window read again once, its image with it; the line under the view's centre where it stood
    on screen, DRIFT_TOL_PX either way, at its em; its figures"""
    ctx.leap(DOC)
    ctx.view_doc_em(DOC, 12.5)
    blocks = [b for b in ctx.js('window.__skep.model.doc(%s).blocks' % json.dumps(DOC)) if b['kind'] == 'para' and b['text'].strip()]
    ctx.view_at(DOC, blocks[len(blocks) // 2]['pos'])
    ctx.settle()
    ctx.frames(2)
    cam = ctx.camera()
    pos = ctx.js('window.__skep.posAt(%s, %s, %s)' % (json.dumps(DOC), cam['x'], cam['y']))

    def seen():
        """where the passage under the view's centre stands now: its line on screen, and the article's em"""
        return ctx.js('''((a, p) => { const S = window.__skep, q = (S.spanRects(a, p, 1) || []).find((x) => x.w > 0 && x.h > 0), m = S.mounted(a);
          return {line: q || null, em: m ? m.fs * S.view.camera().scale : null}; })(%s, %s)''' % (json.dumps(DOC), json.dumps(pos)))
    before = seen()
    row = {'position': 0, 'at': 0, 'op': 'insert', 'docs': [DOC], 'class': 'published'}
    came = ctx.js('''((row, a) => { const S = window.__skep, n = S.bridge.calls().length, beams = S.beams();
      window.__gateNamed = {frames: 0, standing: 0, held: 0, cornered: 0, beamed: 0, beams, stop: false};
      const watch = () => { const g = window.__gateNamed; if (g.stop) return; g.frames++; const m = S.mounted(a);
        if (m && m.text) g.standing++; if (S.model.doc(a).from >= 0) g.held++; if (S.corner(a)) g.cornered++; if (S.beams() >= g.beams) g.beamed++;
        requestAnimationFrame(watch); };
      requestAnimationFrame(watch);
      S.model.feed(row);
      return {n, beams, from: S.model.doc(a).from, corner: !!S.corner(a)}; })(%s, %s)''' % (json.dumps(row), json.dumps(DOC)))
    ctx.settle()
    ctx.frames(3)
    watched = ctx.js('(() => { const g = window.__gateNamed; g.stop = true; return {frames: g.frames, standing: g.standing, held: g.held, cornered: g.cornered, beamed: g.beamed, beams: g.beams}; })()')
    after = seen()
    calls = [c for c in ctx.js('window.__skep.bridge.calls()')[came['n']:] if c.get('frame')]
    frames = [json.loads(c['frame']) for c in calls]
    texts = [f for f in frames if f.get('op') == 'retrieve_v' and (f.get('specs') or [{}])[0].get('doc') == DOC]
    images = [f for f in frames if f.get('op') == 'image' and f.get('d') == DOC]
    every = watched['frames'] > 0
    r.check(came['from'] >= 0 and every and watched['held'] == watched['frames'], 'a row naming the first edition, which the view shows: the model holds its text as the row is taken and in every frame until its read again lands (issue #285)', dict(watched, at_row=came['from']))
    r.check(every and watched['standing'] == watched['frames'] and (not came['corner'] or watched['cornered'] == watched['frames']) and watched['beamed'] == watched['frames'],
            'its article stands in every frame from the row to the settle, its corner beside it, and as many beams as stood before: nothing taken down to wait', dict(watched, corner_before=came['corner']))
    r.check(len(texts) == 1 and len(images) >= 1, 'its text window read again once, its image with it: one read again, setting it in one step', {'texts': len(texts), 'images': len(images), 'reads': sorted(set(f.get('op') for f in frames))})
    kept = bool(before['line'] and after['line']) and abs(after['line']['y'] - before['line']['y']) <= DRIFT_TOL_PX and before['em'] and after['em'] and abs(after['em'] - before['em']) <= 1e-6
    r.check(pos is not None and kept, f'the line under the view\'s centre stands where it stood on screen, {DRIFT_TOL_PX} px either way, at its em', {'pos': pos, 'before': before, 'after': after})
    return {'pos': pos, 'frames': watched, 'texts': len(texts), 'images': len(images), 'before': before, 'after': after, 'reads': sorted(set(f.get('op') for f in frames))}


# a second, and the frames a kept clause takes to stand once it has passed (PUMP's KEPT_MS, unmeasured margin)
KEPT_WAIT_S = 1.4


def kept_holds(ctx, r):
    """A KEPT DOCUMENT SAYS SO ONCE, WHERE ITS NAME IS (issue #345's design decision: "Once the re-read has been out for a
    second, the clause goes wherever the document's name is"; "It lifts in the same frame that the fresh read sets the
    document"): the first edition at em 12.5, the walk on it whole; a published row naming it handed to the page through the
    gate's feed door, its text window's read again held at its answer past a second — the one line, naming it, carries
    "links as last read ⟨when⟩" (an edition's words never change), ⟨when⟩ the page's clock as the row came (issue #367's
    design decision: "⟨when⟩ is the page's clock at the row or drop that left the copy behind"), in a segment of its own
    right after the address segment, its mirror item the same words, its corner none; the walk stepped out to its
    account, the camera put back, a second
    such row: its corner carries the words as its last item, every item above it where it stood before; each read answered,
    no clause stands in the frame the model's text is set; the status region saying its appearing once — its name as the
    mirror finds it, its first line's words then its address, and the clause — and its lifting once, current and unchanged,
    the board answering the text as it stood (issue #369's design decision); reads alone"""
    # a LEAP to the edition with no position stands the walk on it whole
    ctx.leap(DOC)
    ctx.view_doc_em(DOC, 12.5)
    ctx.settle()
    ctx.frames(2)
    cam = ctx.camera()
    ctx.js('''(async () => { const K = window.__gateKept = {REC: await import('./model/records.js'), PUMP: await import('./model/pump.js'), ST: await import('./strings.js'), LAYER: await import('./text/layer.js'), said: [], lift: null};
      const live = document.getElementById('live');
      new MutationObserver(() => K.said.push(live.textContent)).observe(live, {childList: true, characterData: true, subtree: true});
      return true; })()''')
    seen = '''((a) => { const K = window.__gateKept, d = K.REC.doc(a), seg = document.querySelector('#line .seg.kept');
      const c = document.querySelector(`#corners .corner[data-corner="${a}"]`), k = c && c.querySelector('.kept'), li = document.querySelector(`#mirror li[data-addr="${a}"]`);
      const box = (e) => { const q = e.getBoundingClientRect(); return {x: q.left, y: q.top, w: q.width, h: q.height}; };
      const sep = seg && seg.previousElementSibling, before = sep && sep.previousElementSibling;
      const held = K.PUMP.kept(a);
      return {words: held && d.linksRead ? K.ST.t('L.kept.links', {when: K.ST.lastRead(held.since)}) : null, kept: !!held, since: held ? held.since : null, named: window.__skep.named(),
        seg: seg && {text: seg.textContent, id: seg.dataset.string, beside: !!before && before.matches('.address-part')},
        corner: c && {kept: k ? {text: k.textContent, id: k.dataset.string, last: c.lastElementChild === k} : null, top: c.getBoundingClientRect().top, items: [...c.children].filter((e) => e !== k).map(box)},
        mirror: li && {kept: li.dataset.kept || '', text: li.textContent}}; })(%s)''' % json.dumps(DOC)
    # every frame watched from now until the one whose model holds the text set again: what stands in that frame
    lift = '''((a) => { const K = window.__gateKept, r0 = K.REC.doc(a).runs; K.lift = null;
      const watch = () => { if (K.lift) return; const d = K.REC.doc(a);
        if (d.runs !== r0) { const c = document.querySelector(`#corners .corner[data-corner="${a}"]`), li = document.querySelector(`#mirror li[data-addr="${a}"]`);
          K.lift = {seg: !!document.querySelector('#line .seg.kept'), corner: !!(c && c.querySelector('.kept')), mirror: li ? li.dataset.kept || '' : null, kept: !!K.PUMP.kept(a)}; return; }
        requestAnimationFrame(watch); };
      requestAnimationFrame(watch); return true; })(%s)''' % json.dumps(DOC)
    row = {'position': 0, 'at': 0, 'op': 'insert', 'docs': [DOC], 'class': 'published'}

    def kept_round():
        """a row naming the first edition, its text window's read again held at its answer; a second let pass: what stands then,
        and, the read answered, what stands in the frame its text is set and what the status region said meanwhile"""
        ctx.js('window.__gateKept.said = []')
        was = ctx.js(seen)
        ctx.drv.hold_op('retrieve_v', DOC)
        fed = ctx.js('(() => { const t0 = Date.now(); window.__skep.model.feed(%s); return [t0, Date.now()]; })()' % json.dumps(row))
        ctx.drv.pump_events(KEPT_WAIT_S)
        ctx.frames(3)
        held = ctx.js(seen)
        ctx.js(lift)
        answered = ctx.drv.answer_op('whole')
        ctx.settle()
        ctx.frames(3)
        return {'before': was, 'fed': fed, 'held': held, 'answered': answered, 'lift': ctx.js('window.__gateKept.lift'), 'after': ctx.js(seen), 'said': ctx.js('window.__gateKept.said')}

    def said_once(said, words):
        """how many times the status region was told `words`"""
        return sum(1 for x in said if x == words)

    named = kept_round()
    h, words = named['held'], named['held']['words']
    # the item's sentence for the clause (ST's `asSentence`; style S1, S2)
    clause = ctx.js('window.__gateKept.ST.asSentence(%s)' % json.dumps({'id': 'L.kept.links', 'text': words})) if words else None
    name = ctx.js('window.__gateKept.LAYER.boxName(%s).name' % json.dumps(DOC))
    appear = ctx.js('window.__gateKept.ST.t("L.kept.said", %s)' % json.dumps({'name': name, 'clause': words or ''}))
    lifted = ctx.js('window.__gateKept.ST.t("L.kept.unchanged", %s)' % json.dumps({'name': name}))
    r.check(named['answered'] and h['kept'] and (h['named'] or {}).get('doc') == DOC and bool(words) and bool(h['seg']) and h['seg']['text'] == words and h['seg']['id'] == 'L.kept.links' and h['seg']['beside']
            and bool(h['corner']) and h['corner']['kept'] is None,
            'the line naming the first edition, its read again out past a second: "links as last read ⟨when⟩" in a segment of its own right after the address segment, its corner carrying none (issue #345)',
            {'named': h['named'], 'seg': h['seg'], 'words': words, 'corner': h['corner'] and h['corner']['kept']})
    r.check(h['since'] is not None and named['fed'][0] <= h['since'] <= named['fed'][1],
            'its ⟨when⟩ the page\'s clock as the row came, never as a read landed (issue #367)', {'since': h['since'], 'fed': named['fed']})
    r.check(bool(h['mirror']) and bool(clause) and h['mirror']['kept'] == clause and ('. %s ' % clause) in h['mirror']['text'],
            'its mirror item carries the same words, a sentence of its own after its words (FP-33; style S1, S2)', {'mirror': h['mirror'], 'clause': clause})
    nl = named['lift'] or {}
    r.check(bool(named['lift']) and not nl['seg'] and not nl['corner'] and nl['mirror'] == '' and not nl['kept'],
            'the read answered: in the frame the model\'s text is set, no clause stands in the line, the corner or the mirror item', named['lift'])
    r.check(said_once(named['said'], appear) == 1 and said_once(named['said'], lifted) == 1 and bool(name) and name.endswith(' ' + DOC),
            'the status region said its appearing once, by its name — its first line\'s words, then its address — with its clause, and its lifting once, current and unchanged (FP-36; issue #369)',
            {'said': named['said'], 'appear': appear, 'lifted': lifted, 'name': name})
    ctx.js('window.__skep.walk.key("out")')
    ctx.settle()
    ctx.set_view(cam['x'], cam['y'], cam['scale'])
    cornered = kept_round()
    b, h2, w2 = cornered['before'], cornered['held'], cornered['held']['words']
    moved = None
    if b['corner'] and h2['corner'] and len(b['corner']['items']) == len(h2['corner']['items']):
        moved = max([abs(b['corner']['top'] - h2['corner']['top'])] + [max(abs(p[k] - q[k]) for k in ('x', 'y', 'w', 'h')) for p, q in zip(b['corner']['items'], h2['corner']['items'])])
    r.check(cornered['answered'] and h2['kept'] and (h2['named'] or {}).get('doc') is None and not h2['seg'] and bool(h2['corner']) and bool(h2['corner']['kept'])
            and h2['corner']['kept']['text'] == w2 and h2['corner']['kept']['id'] == 'L.kept.links' and h2['corner']['kept']['last'],
            'the line naming its account: the first edition\'s corner carries the words as its last item, the line none',
            {'named': h2['named'], 'seg': h2['seg'], 'corner': h2['corner'] and h2['corner']['kept'], 'words': w2})
    r.check(b['corner'] is not None and b['corner']['kept'] is None and moved is not None and moved <= DRIFT_TOL_PX,
            f'its arrival moves nothing else: the corner\'s top and every item above the clause where it stood, {DRIFT_TOL_PX} px either way', {'moved_px': moved, 'before': b['corner'], 'after': h2['corner']})
    cl = cornered['lift'] or {}
    r.check(bool(cornered['lift']) and not cl['corner'] and not cl['seg'] and not cl['kept'],
            'the read answered: in the frame the model\'s text is set, the corner carries no clause', cornered['lift'])
    return {'named': named, 'cornered': {k: cornered[k] for k in ('held', 'lift', 'said')}, 'moved_px': moved}


# how far above the one line's bottom the first edition's outline's top stands while its label is held over its text in the mount band
KEPT_UNDER_PX = 40


def kept_label_holds(ctx, r):
    """BELOW ITS READING SCALE A KEPT DOCUMENT'S LABEL SAYS SO (issue #368's design decision: "On the canvas label, the
    clause follows the address, at the address's small size. It never follows the first line, and the first line gives
    way first"): the first edition at em 4, below its mount, the walk stepped out to its account so the one line names it
    not; a published row naming it handed to the page through the gate's feed door, its text window's read again held at
    its answer past a second — its canvas label carries "links as last read ⟨when⟩" right after its address, at the
    address's size in the client's face: whole on its row, ending at its outline's first row's end with the address a
    space before it, or else first beneath the row; the line carries none, and every label check holds over the frame; at
    em 7, its article standing in the mount band with no corner, its outline's top KEPT_UNDER_PX above the one line, its
    label held over its text carries the words last, right after its address; the read answered, neither label carries
    them; reads alone"""
    ctx.leap(DOC)
    ctx.js('window.__skep.walk.key("out")')
    ctx.settle()
    ctx.view_doc_em(DOC, 4)
    ctx.frames(2)
    words = '''(async (a) => { const PUMP = await import('./model/pump.js'), REC = await import('./model/records.js'), ST = await import('./strings.js');
      const k = PUMP.kept(a); return k && REC.doc(a).linksRead ? ST.t('L.kept.links', {when: ST.lastRead(k.since)}) : null; })(%s)''' % json.dumps(DOC)
    line_kept = "!!document.querySelector('#line .seg.kept')"

    def canvas(said):
        """the first edition's canvas label at the frame: its lines, its address, and the lines that say `said` — the one
        line right after the address on its row, or the lines beneath the row that make its words up"""
        v = label_view(ctx)
        mine = next((l for l in v['labels'] if l['kind'] == 'doc' and l['place'] == DOC), None)
        lines = mine['lines'] if mine else []
        a = address_line(mine) if mine else None
        i = lines.index(a) if a in lines else -1
        nxt = lines[i + 1] if 0 <= i < len(lines) - 1 else None
        on_row = bool(nxt and said) and nxt['text'] == said and abs(nxt['rect']['y'] + nxt['rect']['h'] / 2 - (a['rect']['y'] + a['rect']['h'] / 2)) <= LABEL_TOL_PX
        clause = [nxt] if on_row else []
        if not on_row and said and a:
            acc = ''
            for x in lines[i + 1:]:
                if acc == said or x['rect']['y'] < a['rect']['y'] + a['rect']['h'] - LABEL_TOL_PX:
                    break
                acc = (acc + ' ' + x['text']).strip()
                clause.append(x)
            if acc != said:
                clause = []
        return {'v': v, 'lines': lines, 'address': a, 'clause': clause, 'on_row': on_row, 'row': v['rows'].get(DOC)}

    row = {'position': 0, 'at': 0, 'op': 'insert', 'docs': [DOC], 'class': 'published'}
    ctx.drv.hold_op('retrieve_v', DOC)
    ctx.js('window.__skep.model.feed(%s)' % json.dumps(row))
    ctx.drv.pump_events(KEPT_WAIT_S)
    ctx.frames(3)
    said = ctx.js(words)
    c4 = canvas(said)
    seen = {'kept-em4': labels_hold(r, 'kept-em4', c4['v'])}
    a, k, rw = c4['address'], c4['clause'], c4['row']
    placed = bool(a and k and rw) and (not c4['on_row'] or (abs(k[0]['rect']['x'] + k[0]['rect']['w'] - (rw['x'] + rw['w'])) <= LABEL_TOL_PX and 0 < k[0]['rect']['x'] - (a['rect']['x'] + a['rect']['w']) <= k[0]['px']))
    faced = bool(k) and all(x['px'] == a['px'] and x['runs'] and all(q['face'] == 'client' for q in x['runs']) for x in k)
    lined = ctx.js(line_kept)
    r.check(bool(said) and placed and faced and not lined,
            'em 4: the first edition kept past a second, its read again out, the one line naming its account: its canvas label carries "links as last read ⟨when⟩" right after its address, at the address\'s size in the client\'s face — whole on its row, ending at its outline\'s first row\'s end with the address a space before it, or else first beneath the row — and the line none (issue #368)',
            {'said': said, 'lines': [[x['text'], x['rect'], x['px']] for x in c4['lines']], 'on_row': c4['on_row'], 'row': rw, 'line_kept': lined, 'named': c4['v']['named'],
             'left_out': [[x['text'], x['reason']] for x in c4['v']['out'] if x['kind'] == 'doc' and x['place'] == DOC]})
    # its article in the mount band, below its reading scale: its outline's top risen past the one line, its label held over its text
    s7 = ctx.js('window.__skep.scaleFor(%s, "em", 7)' % json.dumps(DOC))
    f7 = ctx.js('window.__skep.fold(%s)' % json.dumps(DOC))
    first = ctx.js('window.__skep.centreOf(%s, null)' % json.dumps(DOC))
    vp = ctx.js('window.__skep.view.viewport()')
    top = ctx.js("document.getElementById('line').getBoundingClientRect().bottom")
    at7 = {'x': first['x'], 'y': f7['outline']['y'] + (vp['VH'] / 2 - (top - KEPT_UNDER_PX)) / s7, 'scale': s7}
    held_js = '''((a) => ({held: window.__skep.heldLabel(a), mounted: window.__skep.mountedAddrs().includes(a), corner: !!document.querySelector(`#corners .corner[data-corner="${a}"]`), named: window.__skep.named()}))(%s)''' % json.dumps(DOC)
    ctx.js('window.__skep.view.set(%s)' % json.dumps(at7))
    ctx.frames(4)
    h7 = ctx.js(held_js)
    texts = (h7['held'] or {}).get('text') or []
    short = DOC[len(account_of(DOC)):]
    r.check(bool(said) and h7['mounted'] and not h7['corner'] and (h7['named'] or {}).get('doc') is None and len(texts) >= 2 and texts[-1] == said and texts[-2] in (short, DOC),
            f'em 7: the first edition\'s article in the mount band, no corner beside it, its outline\'s top {KEPT_UNDER_PX} px above the one line: its label held over its text carries the words last, right after its address (issue #368)',
            {'said': said, 'held': h7})
    answered = ctx.drv.answer_op('whole')
    ctx.settle()
    ctx.frames(3)
    after7 = ctx.js(held_js)
    ctx.view_doc_em(DOC, 4)
    ctx.frames(2)
    after4 = canvas(said)
    gone = said not in ((after7['held'] or {}).get('text') or []) and not after4['clause']
    r.check(answered and bool(said) and gone and not ctx.js(words),
            'the read answered: the first edition no longer kept, neither its held label nor its canvas label carries the words',
            {'answered': answered, 'held': after7['held'], 'canvas': [x['text'] for x in after4['lines']]})
    return {'said': said, 'em4': {'lines': [[x['text'], x['rect']] for x in c4['lines']], 'on_row': c4['on_row']}, 'em7': h7, 'labels': seen}


def longest_holds(ctx, r):
    """THE LONGEST EDITION the claimant's index lists (the typography review's finding 7: under a size fitted to its
    length its line ran wider than the window) — found by the harness's own reads of each edition's span set — shown at
    mid scale and at reading scale (issue #15): its columns inside its room at mid, its bars in their columns; LEAPt to,
    its article mounted at the measure, every row inside its column and its room; its figures"""
    longest, extents, docs = ctx.longest_edition()
    r.check(longest is not None, 'the longest edition the claimant\'s index lists, by the board\'s own span sets', {'read': len(extents), 'of': docs})
    if longest is None:
        return None
    ctx.leap(longest)
    ctx.frames(2)
    f = ctx.js('window.__skep.fold(%s)' % json.dumps(longest))
    m = measure_view(ctx)
    mine = [a for a in m if a['addr'] == longest]
    ov = ctx.js('window.__skep.overlapCheck()')
    cut = [c for c in ov['blocks_cut'] if c['addr'] == longest]
    room = f['room']
    inside_room = all(c['x'] >= room['x'] - 1e-6 and c['y'] >= room['y'] - 1e-6 and c['x'] + c['w'] <= room['x'] + room['w'] + 1e-6 and c['y'] + c['h'] <= room['y'] + room['h'] + 1e-6 for c in f['columns'])
    r.check(bool(mine) and inside_room and not cut, f'reading scale: the longest edition, {longest} ({extents[longest]} positions, {len(f["columns"])} columns at step {f["step"]}), stands mounted, its columns inside its room, every row inside its column and its room',
            {'mounted': bool(mine), 'columns': len(f['columns']), 'step': f['step'], 'cut': cut[:4]})
    measure_holds(r, f'reading scale: the longest edition, {longest}', mine)
    # what stands of it (issue #122: a document stands by line, the cost bounded by the screen), set afresh at the landing
    # — the reveal hidden again, which sets every standing article again (`bump`), so no part stands from the flight's
    # wider views: every part standing — a run of one column's lines, its box as the engine sets it — meets the view
    # and STAND_PAD_PX about it and reaches past that by no more than two of its tallest line boxes, fewer of its lines
    # stand than it holds, each part's blocks are their text over the characters they hold, and each stands on its bars
    ctx.js('window.__skep.links.hide(%s)' % json.dumps(longest))
    ctx.frames(3)
    reach = 2 * LINE_RATIO * 1.25 * f['fs'] * ctx.camera()['scale']
    parts = ctx.js('''((a, pad, reach) => { const S = window.__skep, p = S.view.viewport(), blocks = new Map(S.model.doc(a).blocks.map((b) => [b.pos, b]));
      return [...document.querySelectorAll(`#domlayer article.dtext[data-addr="${a}"] .col`)].map((c) => { const q = c.getBoundingClientRect();
        const off = [...c.querySelectorAll('.run > .sp')].filter((e) => { const b = blocks.get(Number(e.dataset.pos)); if (!b || b.kind !== 'para') return false;
          const k = e.cloneNode(true); k.querySelectorAll('.others,.sym').forEach((x) => x.remove()); const char = Number(e.dataset.char || 0);
          return k.textContent !== b.text.slice(char, char + k.textContent.length); }).map((e) => Number(e.dataset.pos));
        return {column: c.dataset.column ?? null, first: c.dataset.first ?? null, end: c.dataset.end ?? null, top: q.top, bottom: q.bottom,
                meets: q.right >= -pad && q.left <= p.VW + pad && q.bottom >= -pad && q.top <= p.VH + pad, within: q.top >= -pad - reach && q.bottom <= p.VH + pad + reach, off}; }); })(%s, %d, %s)''' % (json.dumps(longest), STAND_PAD_PX, reach))
    standing = sum(int(p['end']) - int(p['first']) for p in parts if p['first'] is not None and p['end'] is not None)
    r.check(bool(parts) and all(p['meets'] and p['within'] and p['first'] is not None for p in parts) and 0 < standing < f['lines'],
            f'reading scale: the longest edition stands by line — every part of it standing meets the view, {STAND_PAD_PX} px about it, reaching past that by no more than two line boxes, and {standing} of its {f["lines"]} lines stand',
            {'parts': [{k: p[k] for k in ('column', 'first', 'end', 'top', 'bottom', 'meets', 'within')} for p in parts], 'lines': f['lines'], 'reach_px': reach})
    r.check(bool(parts) and not any(p['off'] for p in parts), 'reading scale: every block part of the longest edition standing is its block\'s text over the characters it holds', [p for p in parts if p['off']][:4])
    ho = handoff(ctx)
    r.check(ho['compared'] > 0 and not ho['off'], 'reading scale: every part of the longest edition standing, and of every other article, stands on its bars', {'compared': ho['compared'], 'off': ho['off'][:6]})
    # below the mount, where the canvas draws its bars: its own em 4 — it stands six grids deep, so its own em, not the
    # plane's bands, says where its text is greeked
    ctx.view_doc_em(longest, 4)
    bars = ctx.js('''((a) => { const S = window.__skep, h = S.barsOf(a), f = S.fold(a); if (!h) return null;
      return {columns: f.columns.length, parts: h.bars.length, outside: h.bars.filter((b) => { const c = f.columns[b.column], cam = S.view.camera(), p = S.view.viewport();
        const top = (c.y - cam.y) * cam.scale + p.VH / 2; return b.top < top - 0.5 || b.top + b.height > top + c.h * cam.scale + 0.5; }).length}; })(%s)''' % json.dumps(longest))
    em = f['fs'] * ctx.camera()['scale']
    standing = longest in ctx.js('window.__skep.mountedAddrs()')
    r.check(bool(bars) and bars['parts'] > 0 and bars['outside'] == 0 and not standing and 3 <= em < ctx.js('window.__skep.constants.MOUNT_EM'),
            'below the mount, at its own em 4: the longest edition greeked in its columns — its article down, each block part\'s bars inside the column that holds it', dict(bars or {}, em=em, mounted=standing))
    return {'doc': longest, 'positions': extents[longest], 'columns': len(f['columns']), 'step': f['step'], 'fs': f['fs'], 'editions_read': len(extents)}


def view_reading(ctx, em):
    """the camera over the first edition's first column at an em of `em` px, the column and the corner beside it on its
    left (foundations §3.1) centred across the viewport together — at em 30 the column alone is most of the window's width"""
    ctx.view_doc_em(DOC, em)
    c = corner_of(ctx)
    room = (c['corner']['rect']['w'] if c['corner'] else 121) + CORNER_GAP_PX
    f, cam, vp = ctx.js('window.__skep.fold(%s)' % json.dumps(DOC)), ctx.camera(), ctx.js('window.__skep.view.viewport()')
    c0 = f['columns'][0]
    left = (vp['VW'] - c0['w'] * cam['scale'] - room) / 2 + room
    ctx.set_view(c0['x'] - (left - vp['VW'] / 2) / cam['scale'], cam['y'], cam['scale'])


def corner_rect(ctx):
    """the first edition's corner as the page shows it (the `visible` oracle) and as the page placed it — the column it
    stands beside and its form — beside the fold's columns on screen, the view's size and the one line's bottom"""
    return ctx.js('''(() => { const S = window.__skep, v = S.visible(%s), f = S.fold(%s), c = S.view.camera(), p = S.view.viewport();
      const scr = (x) => (x - c.x) * c.scale + p.VW / 2;
      return {corner: v.length === 1 ? v[0] : null, placed: S.corner(%s), view: p, line: document.getElementById('line').getBoundingClientRect().bottom,
              columns: f.columns.map((k) => ({left: scr(k.x), right: scr(k.x + k.w), top: (k.y - c.y) * c.scale + p.VH / 2, bottom: (k.y + k.h - c.y) * c.scale + p.VH / 2})),
              box: (() => { const b = S.boxOf(%s); return {left: scr(b.x), right: scr(b.x + b.w)}; })()}; })()''' % (json.dumps(CORNER), json.dumps(DOC), json.dumps(DOC), json.dumps(DOC)))


def corner_follows(ctx, r):
    """THE CORNER FOLLOWS THE COLUMN NEAREST THE VIEW'S CENTRE (issue #151's design decision; FP-26: "Short of room it
    compacts there"): the first edition read at the reading size over its first column, its corner whole beside that
    column; then over its second column, the corner beside that one — its right edge CORNER_GAP_PX short of the column's
    text, below the one line and in view, inside its own document's box and clear of the first column's text — compact,
    narrower than it stands whole, the gutter and the edge there holding less; its glyph's act opening it whole where it
    stands, the act again compacting it (FP-26: "A compact sign opens whole on its act"); its figures"""
    f = ctx.js('window.__skep.fold(%s)' % json.dumps(DOC))
    if len(f['columns']) < 2:
        r.note('the corner beside a later column is unmeasured on this board: the first edition folds into one column')
        return {'unmeasured': len(f['columns'])}
    s = ctx.js('window.__skep.scaleFor(%s, "em", %s)' % (json.dumps(DOC), READING_PX))
    over = lambda i: ctx.set_view(f['columns'][i]['x'] + f['columns'][i]['w'] / 2, f['columns'][i]['y'] + f['columns'][i]['h'] / 2, s)
    over(0)
    first = corner_rect(ctx)
    whole = first['corner']['rect']['w'] if first['corner'] else None
    r.check(bool(first['corner']) and first['placed'] == {'column': 0, 'compact': False, 'opened': False, 'head': False} and first['corner']['inView'],
            f'em {READING_PX} over the first column: the first edition\'s corner beside it, whole, in view', first)
    over(1)
    v = corner_rect(ctx)
    c, col, col0 = v['corner'], v['columns'][1], v['columns'][0]
    beside = bool(c) and abs(c['rect']['x'] + c['rect']['w'] - (col['left'] - CORNER_GAP_PX)) <= 1 and c['inView'] and c['inClip'] and c['rect']['y'] >= v['line'] - 0.5
    clear = bool(c) and c['rect']['x'] >= col0['right'] - 0.5 and c['rect']['x'] >= v['box']['left'] and c['rect']['x'] + c['rect']['w'] <= v['box']['right']
    compact = bool(c) and whole is not None and c['rect']['w'] < whole - 1 and v['placed'] == {'column': 1, 'compact': True, 'opened': False, 'head': False}
    r.check(beside and clear and compact,
            f'em {READING_PX} over the second column: the corner beside it — its right edge {CORNER_GAP_PX} px short of the column\'s text, below the one line, in view — in the gutter, clear of the first column\'s text and inside its own document\'s box, compact: narrower than its {whole} px whole',
            {'corner': c and c['rect'], 'placed': v['placed'], 'column': col, 'first_column': col0, 'box': v['box'], 'whole_px': whole})
    ov = ctx.js('window.__skep.overlapCheck()')
    r.check(not ov['corners_into'] and not ov['corners_clipped'], 'over the second column the corner reaches into no other document\'s box, and nothing clips it', {'into': ov['corners_into'][:4], 'clipped': ov['corners_clipped']})
    # its glyph's act opens it whole where it stands; the act again compacts it
    act = '''(() => { const g = document.querySelector(%s + ' .%%s'); if (!g) return false; const q = g.getBoundingClientRect();
      g.dispatchEvent(new MouseEvent('click', {bubbles: true, cancelable: true, clientX: q.left + q.width / 2, clientY: q.top + q.height / 2})); return true; })()''' % json.dumps(CORNER)
    acted = ctx.js(act % 'glyph')
    ctx.frames(3)
    opened = corner_rect(ctx)
    ctx.js(act % 'st')
    ctx.frames(3)
    closed = corner_rect(ctx)
    oc, cc = opened['corner'], closed['corner']
    r.check(acted and bool(oc and cc) and abs(oc['rect']['w'] - whole) <= 1 and abs(oc['rect']['x'] + oc['rect']['w'] - (col['left'] - CORNER_GAP_PX)) <= 1 and opened['placed'] == {'column': 1, 'compact': False, 'opened': True, 'head': False}
            and abs(cc['rect']['w'] - c['rect']['w']) <= 1 and closed['placed'] == {'column': 1, 'compact': True, 'opened': False, 'head': False},
            'the compact corner\'s glyph opens it whole on its act, standing where it stood, and the act at the corner opened compacts it again', {'opened': oc and oc['rect'], 'closed': cc and cc['rect'], 'acted': acted})
    return {'whole_px': whole, 'compact': c and c['rect'], 'opened': oc and oc['rect']}


def seen_centre(ctx):
    """the visible view's centre — the viewport's below the one line — in world units, and on screen"""
    return ctx.js('''(() => { const S = window.__skep, c = S.view.camera(), p = S.view.viewport(), top = document.getElementById('line').getBoundingClientRect().bottom;
      const sy = (top + p.VH) / 2; return {x: c.x, y: c.y + (sy - p.VH / 2) / c.scale, sy}; })()''')


def line_from(ctx, pos, mid):
    """the height of the middle of the line holding a position of the first edition from the visible view's centre, on
    screen"""
    at, cam, vp = ctx.js('window.__skep.centreOf(%s, %s)' % (json.dumps(DOC), json.dumps(pos))), ctx.camera(), ctx.js('window.__skep.view.viewport()')
    return {'dy': (at['y'] - cam['y']) * cam['scale'] + vp['VH'] / 2 - mid['sy']}


def measure_narrows(ctx, r):
    """THE MEASURE NARROWS TO WHAT THE VIEW HOLDS (issue #151's design decisions; FP-26: "margins compact first, then the
    measure narrows in characters ... zoom never changes the measure"; issue #436's: "Below forty, the corner moves to the
    document's head, across the column being read, and its room goes back to the measure"): the window set NARROW_PX wide
    and the first edition LEAPt to a passage — every mounted column a whole count of its face's average advance fewer than
    the full measure, one for every column, the page's measure in force, the corner at the document's head; the landed
    line's column and its edge, EDGE_EM em at the reading size, inside the visible view at the reading size, the corner
    across them, in view below the one line; a zoom changing no count; and the window put back — every column at the full
    measure again, the line under the view's centre at the height it stood, from the view's centre, at its em; its
    figures"""
    pos = PASSAGE
    was = ctx.resize(NARROW_PX, 900)
    try:
        ctx.settle()
        ctx.leap(DOC, pos)
        ctx.frames(3)
        fit = ctx.js('window.__skep.measure()')
        cols = measure_view(ctx)
        cpl = [c for a in cols for c in (a['cpl'] or [])]
        whole = bool(cpl) and all(abs(c - round(c)) <= MEASURE_CH_TOL and abs(c - cpl[0]) <= 2 * MEASURE_CH_TOL for c in cpl)
        r.check(whole and round(cpl[0]) < MEASURE_CH[1] and abs(round(cpl[0]) - fit['cpl']) <= 0 and fit['compact'] and fit['head'],
                f'a {NARROW_PX} px window: every mounted column a whole count of its face\'s average advance fewer than the full measure, one count for every column — the page\'s measure in force, its corner at the document\'s head',
                {'cpl': sorted(set(round(c, 3) for c in cpl)), 'fit': fit})
        v, at = corner_rect(ctx), ctx.js('window.__skep.centreOf(%s, %d)' % (json.dumps(DOC), pos))
        cam, vp = ctx.camera(), v['view']
        line_x = (at['x'] - cam['x']) * cam['scale'] + vp['VW'] / 2
        col = next((k for k in v['columns'] if k['left'] <= line_x <= k['right']), None)
        c = v['corner']
        edge = col and col['right'] + EDGE_EM * READING_PX
        framed = bool(col and c) and col['left'] >= -0.5 and edge <= vp['VW'] + 0.5 and abs(c['rect']['x'] - col['left']) <= 1 and abs(c['rect']['x'] + c['rect']['w'] - edge) <= 1 and c['rect']['y'] >= v['line'] - 0.5
        em = ctx.js('window.__skep.fold(%s).fs' % json.dumps(DOC)) * cam['scale']
        r.check(framed and abs(em - READING_PX) < 1e-6 and v['placed'] and v['placed']['head'],
                f'a {NARROW_PX} px window: the landed line\'s column and its {EDGE_EM} em edge inside the view, at the reading size, {READING_PX} px an em — the corner across them at the document\'s head, below the one line',
                {'corner': c and c['rect'], 'column': col, 'edge_right': edge, 'view': vp, 'em': em, 'placed': v['placed']})
        ctx.set_view(cam['x'], cam['y'], cam['scale'] * 1.6)
        zoomed = [c for a in measure_view(ctx) for c in (a['cpl'] or [])]
        r.check(bool(zoomed) and all(abs(z - cpl[0]) <= 2 * MEASURE_CH_TOL for z in zoomed) and ctx.js('window.__skep.measure()') == fit,
                f'a {NARROW_PX} px window, zoomed in: every column\'s count as it was — zoom never changes the measure', {'zoomed': sorted(set(round(z, 3) for z in zoomed)), 'was': round(cpl[0], 3) if cpl else None})
        ctx.set_view(cam['x'], cam['y'], cam['scale'])
        # the passage at the visible view's centre — the viewport's below the one line — and its line's height from that centre
        mid = seen_centre(ctx)
        under = ctx.js('window.__skep.posAt(%s, %s, %s)' % (json.dumps(DOC), mid['x'], mid['y']))
        before = line_from(ctx, under, mid)
        before['em'] = em
    finally:
        ctx.resize(*was)
    ctx.settle()
    ctx.frames(3)
    back = [c for a in measure_view(ctx) for c in (a['cpl'] or [])]
    after = line_from(ctx, under, seen_centre(ctx))
    after['em'] = ctx.js('window.__skep.fold(%s).fs' % json.dumps(DOC)) * ctx.camera()['scale']
    r.check(bool(back) and all(abs(b - MEASURE_CH[1]) <= MEASURE_CH_TOL for b in back) and abs(after['dy'] - before['dy']) <= 1 and abs(after['em'] - before['em']) <= 1e-6,
            f'the window put back: every column at the full measure again, the line under the visible view\'s centre at the height it stood from that centre, 1 px either way, at its em',
            {'back': sorted(set(round(b, 3) for b in back)), 'before': before, 'after': after, 'pos': under})
    return {'window': NARROW_PX, 'cpl': round(cpl[0], 3) if cpl else None, 'fit': fit, 'before': before, 'after': after}


def resize_frames(ctx, r):
    """A RESIZE FRAMES THE VIEW ACROSS THE COLUMN BEING READ (issue #436's design decision: "A refold keeps the passage's
    line in place and frames sideways the way a LEAP does, with the corner included"): the first edition LEAPt to a
    passage in the wide window, then the window set REFIT_PX wide — the measure narrowed, the corner compact beside the
    landed line's column — the corner inside the view below the one line, the column and its edge in view, the line under
    the visible view's centre at the height it stood from that centre, at its em; its figures"""
    ctx.leap(DOC, PASSAGE)
    ctx.frames(3)
    mid = seen_centre(ctx)
    under = ctx.js('window.__skep.posAt(%s, %s, %s)' % (json.dumps(DOC), mid['x'], mid['y']))
    before = line_from(ctx, under, mid)
    before['em'] = ctx.js('window.__skep.fold(%s).fs' % json.dumps(DOC)) * ctx.camera()['scale']
    was = ctx.resize(REFIT_PX, 900)
    try:
        ctx.settle()
        ctx.frames(3)
        fit, v = ctx.js('window.__skep.measure()'), corner_rect(ctx)
        after = line_from(ctx, under, seen_centre(ctx))
        after['em'] = ctx.js('window.__skep.fold(%s).fs' % json.dumps(DOC)) * ctx.camera()['scale']
        at, cam, vp = ctx.js('window.__skep.centreOf(%s, %s)' % (json.dumps(DOC), json.dumps(under))), ctx.camera(), v['view']
        line_x = (at['x'] - cam['x']) * cam['scale'] + vp['VW'] / 2
        col, c = next((k for k in v['columns'] if k['left'] <= line_x <= k['right']), None), v['corner']
        inside = bool(c and col) and c['rect']['x'] >= -0.5 and c['rect']['x'] + c['rect']['w'] <= col['left'] + 0.5 and col['right'] + EDGE_EM * READING_PX <= vp['VW'] + 0.5 and c['rect']['y'] >= v['line'] - 0.5
        r.check(fit['cpl'] < MEASURE_CH[1] and not fit['head'] and bool(v['placed']) and v['placed']['compact'] and not v['placed']['head'] and inside
                and abs(after['dy'] - before['dy']) <= 1 and abs(after['em'] - before['em']) <= 1e-6,
                f'the window set {REFIT_PX} px wide after a LEAP in the wide one: the corner compact beside the landed line\'s column, inside the view below the one line, the column and its {EDGE_EM} em edge in view, the line under the visible view\'s centre at the height it stood from that centre, 1 px either way, at its em (issue #436)',
                {'fit': fit, 'placed': v['placed'], 'corner': c and c['rect'], 'column': col, 'view': vp, 'line': v['line'], 'before': before, 'after': after})
    finally:
        ctx.resize(*was)
    ctx.settle()
    ctx.frames(3)
    return {'window': REFIT_PX, 'pos': under, 'corner': c and c['rect'], 'before': before, 'after': after}


# the first text node of a block's first part in a document's mounted article that carries the block's own characters, the
# chrome inside it skipped (T-SPAN's CHROME) — where the harness sets the platform's selection
OWN_TEXT = '''((addr, pos) => { const el = document.querySelector(`#domlayer article.dtext[data-addr="${addr}"] .run > .sp[data-pos="${pos}"]`);
  if (!el) return null; const w = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
  for (let n = w.nextNode(); n; n = w.nextNode()) if (!n.parentElement.closest('.sym, .edge') && n.data.trim()) return n;
  return null; })'''


def line_top(ctx, pos):
    """the top of the line holding a position of the first edition, on screen, where its fold sets it at the camera now"""
    return ctx.js('''((a, p, k) => { const S = window.__skep, c = S.centreOf(a, p), v = S.view.camera(), vp = S.view.viewport(), fs = S.fold(a).fs;
      return (c.y - v.y) * v.scale + vp.VH / 2 - k * fs * v.scale / 2; })(%s, %d, %s)''' % (json.dumps(DOC), pos, LINE_RATIO))


def below_head(ctx, pos):
    """the camera moved up or down alone so the line holding a position of the first edition stands 2 px below what its
    head covers (`headClear`) — its corner at its head, the first row held below the one line; what the head covers
    then, or None where no head stands"""
    clear = None
    for _ in range(4):
        ctx.frames(2)
        clear = ctx.js('window.__skep.headClear(%s)' % json.dumps(DOC))
        if clear is None:
            return None
        delta = clear + 2 - line_top(ctx, pos)
        if abs(delta) < 0.5:
            break
        cam = ctx.camera()
        ctx.set_view(cam['x'], cam['y'] - delta / cam['scale'], cam['scale'])
    return clear


def head_guards(ctx, r):
    """NOTHING LEFT UNDER THE HEAD'S HELD ROW (issue #436's design decision: "No caret, focus, selection or landing
    stands under that row"; FP-37): in a window NARROW_PX wide, the first edition's corner standing at its head and the
    paragraph at PASSAGE set just below the held row — Shift+↑ (K-8) selecting it whole moving nothing; Shift+↑ again,
    extending the selection to the typed line before it, whose first line stands under the row, bringing that line to
    the row's bottom by the camera moved down alone, by the least pan; and a selection the platform holds, its focus
    point on that first line under the row, taken as the page's, so too; its figures"""
    sel_clear = '(async () => { (await import("./overlays/selection.js")).clear(); window.getSelection().removeAllRanges(); })()'
    blocks = ctx.js('window.__skep.model.doc(%s).blocks' % json.dumps(DOC)) or []
    i = next((k for k, x in enumerate(blocks) if x['pos'] == PASSAGE), None)
    b, prev = (blocks[i], blocks[i - 1]) if i else (None, None)
    ok = bool(b and prev) and b['kind'] == 'para' and prev['kind'] == 'para' and bool(prev['text'].strip())
    r.check(ok, f'the first edition holds a typed line before its paragraph at {PASSAGE} (what the checks below stand on)', {'block': b and b['pos'], 'before': prev and prev['pos']})
    if not ok:
        return {'block': b and b['pos'], 'before': prev and prev['pos']}
    was = ctx.resize(NARROW_PX, 900)
    try:
        ctx.settle()
        ctx.js(sel_clear)
        ctx.leap(DOC, PASSAGE)
        focus = ctx.js('window.__skep.view.focus()')
        clear = below_head(ctx, PASSAGE)
        r.check(clear is not None and bool(focus) and focus['kind'] == 'block' and focus['pos'] == PASSAGE,
                f'a {NARROW_PX} px window: the first edition\'s corner at its head, the walk on the paragraph at {PASSAGE}, its first line set just below the held row (what the checks below stand on)',
                {'focus': focus, 'clear': clear})
        if clear is None:
            return {'focus': focus}
        cam0 = ctx.camera()
        ctx.drv.key('ArrowUp', mods=('Shift',))
        ctx.frames(3)
        whole, cam1, under = ctx.js('window.__skep.selection()'), ctx.camera(), line_top(ctx, prev['pos'])
        r.check(whole == {'addr': DOC, 'pos': b['pos'], 'width': b['width']} and same_view(cam1, cam0) and under < clear - 1,
                f'Shift+↑ selects the paragraph at {PASSAGE} whole, its first line clear of the held row, the camera unmoved — the typed line before it under the row',
                {'selection': whole, 'camera': [cam0, cam1], 'before_top': under, 'clear': clear})
        ctx.drv.key('ArrowUp', mods=('Shift',))
        ctx.frames(3)
        ctx.settle()
        ctx.frames(2)
        grown, cam2, top2, clear2 = ctx.js('window.__skep.selection()'), ctx.camera(), line_top(ctx, prev['pos']), ctx.js('window.__skep.headClear(%s)' % json.dumps(DOC))
        down = (cam1['y'] - cam2['y']) * cam2['scale']
        r.check(grown == {'addr': DOC, 'pos': prev['pos'], 'width': b['pos'] + b['width'] - prev['pos']} and clear2 is not None and abs(top2 - clear2) <= 1
                and abs(down - (clear - under)) <= 1 and abs(cam2['x'] - cam1['x']) < 1e-9 and abs(cam2['scale'] - cam1['scale']) < 1e-12,
                'Shift+↑ again extends the selection to the typed line before it, and the camera moves down alone by the least pan, that line\'s first line at the held row\'s bottom',
                {'selection': grown, 'down_px': down, 'want_px': clear - under, 'top': top2, 'clear': clear2, 'camera': [cam1, cam2]})
        ctx.js(sel_clear)
        ctx.frames(2)
        clear = below_head(ctx, PASSAGE)
        cam3, under3 = ctx.camera(), line_top(ctx, prev['pos'])
        made = ctx.js('''((a, p, q) => { const own = %s, x = own(a, p), y = own(a, q); if (!x || !y) return false;
          window.getSelection().setBaseAndExtent(x, Math.min(2, x.length), y, 0); return true; })(%s, %d, %d)''' % (OWN_TEXT, json.dumps(DOC), b['pos'], prev['pos']))
        ctx.frames(4)
        ctx.settle()
        ctx.frames(2)
        taken, cam4, top4, clear4 = ctx.js('window.__skep.selection()'), ctx.camera(), line_top(ctx, prev['pos']), ctx.js('window.__skep.headClear(%s)' % json.dumps(DOC))
        down4 = (cam3['y'] - cam4['y']) * cam4['scale']
        r.check(bool(made) and bool(taken) and taken['pos'] == prev['pos'] and clear is not None and under3 < clear - 1 and clear4 is not None and abs(top4 - clear4) <= 1
                and abs(down4 - (clear - under3)) <= 1 and abs(cam4['x'] - cam3['x']) < 1e-9,
                'a selection the platform holds from the paragraph back to the first line of the typed line before it, under the held row, taken as the page\'s: the camera moves down alone by the least pan, that line at the held row\'s bottom',
                {'made': made, 'selection': taken, 'down_px': down4, 'want_px': clear is not None and clear - under3, 'top': top4, 'clear': clear4})
    finally:
        ctx.js(sel_clear)
        ctx.resize(*was)
    ctx.settle()
    ctx.frames(3)
    return {'window': NARROW_PX, 'block': b['pos'], 'before': prev['pos'], 'k8_down_px': down, 'platform_down_px': down4}


# the first edition's corner on the plane: its rect on screen, whether the platform's focus stands in it and on which of its
# acts, by the act's first class, and the one line's bottom
CORNER_AT = '''((a) => { const e = document.querySelector(`#corners [data-corner="${a}"]`); if (!e) return null; const q = e.getBoundingClientRect(), f = document.activeElement;
  return {x: q.left, y: q.top, w: q.width, h: q.height, focus: !!f && e.contains(f), act: !!f && f !== e && e.contains(f) && f.tagName === 'BUTTON' ? f.className.split(' ')[0] : null,
          line: document.getElementById('line').getBoundingClientRect().bottom}; })(%s)'''


def corner_tabbed(ctx, r):
    """A CORNER TABBED TO OUT OF VIEW (issue #436's design decision: "When focus lands in the corner, the camera pans it
    into view"; FP-20): in a window REFIT_PX wide the first edition LEAPt to a passage, the camera then moved alone so its
    corner stands left of the view while the view's centre stays over the column it stands beside; Tab from the walk's
    item lands on the corner's stop, its version statement, the edition's line's first act, and the camera moves across
    alone by the least pan, the corner's left edge at the view's; its figures"""
    was = ctx.resize(REFIT_PX, 900)
    try:
        ctx.settle()
        ctx.leap(DOC, PASSAGE)
        ctx.frames(3)
        placed = ctx.js('window.__skep.corner(%s)' % json.dumps(DOC))
        col = ctx.js('window.__skep.fold(%s).columns[%d]' % (json.dumps(DOC), placed['column'] if placed else 0))
        cam = ctx.camera()
        # the column's text 4 px in from the view's left: its corner, a gap short of it, wholly left of the view (the hook's
        # columns in world units)
        left = (col['x'] - cam['x']) * cam['scale'] + REFIT_PX / 2
        ctx.set_view(cam['x'] + (left - 4) / cam['scale'], cam['y'], cam['scale'])
        ctx.frames(3)
        before, cam0 = ctx.js(CORNER_AT % json.dumps(DOC)), ctx.camera()
        r.check(bool(placed) and not placed['head'] and bool(before) and before['x'] + before['w'] <= 0.5 and ctx.js('window.__skep.corner(%s).column' % json.dumps(DOC)) == placed['column'],
                f'a {REFIT_PX} px window, the camera moved alone: the first edition\'s corner beside the column under the view\'s centre, wholly left of the view (what the next check stands on)',
                {'placed': placed, 'corner': before})
        ctx.js('document.getElementById("walk-" + window.__skep.mirror.index()).focus({preventScroll: true})')
        ctx.frames(1)
        ctx.drv.key('Tab')
        ctx.frames(3)
        after, cam1 = ctx.js(CORNER_AT % json.dumps(DOC)), ctx.camera()
        across = (cam0['x'] - cam1['x']) * cam1['scale']
        r.check(bool(after) and after['focus'] and after['act'] == 'version' and abs(after['x']) <= 1 and after['x'] + after['w'] <= REFIT_PX + 0.5 and after['y'] >= after['line'] - 0.5 and after['y'] + after['h'] <= 900.5
                and bool(before) and abs(across + before['x']) <= 1 and abs(cam1['y'] - cam0['y']) < 1e-9 and abs(cam1['scale'] - cam0['scale']) < 1e-12,
                'Tab from the walk\'s item lands on the corner\'s stop, its version statement, and the camera moves across alone by the least pan, the corner inside the view below the one line, its left edge at the view\'s',
                {'before': before, 'after': after, 'across_px': across, 'camera': [cam0, cam1]})
    finally:
        ctx.resize(*was)
    ctx.settle()
    ctx.frames(3)
    return {'window': REFIT_PX, 'before': before, 'after': after, 'across_px': across}


def back_after_resize(ctx, r):
    """THE PASSAGE LEFT (issue #221: "Back finds where that passage sits now and lands on it"): in a window NARROW_PX wide
    the first edition LEAPt to a passage, the position its line under the visible view's centre opens at noted, with the
    height of the line holding it from that centre and the em; a LEAP to the far edition, the window put back — every
    document folded again at the full measure, so the line holding that position stands elsewhere from the visible centre
    of the view left — and Mod+[: the line holding it at the height it stood from the visible centre, 1 px either way, at
    its em; its figures"""
    was = ctx.resize(NARROW_PX, 900)
    try:
        ctx.settle()
        ctx.leap(DOC, PASSAGE)
        ctx.frames(3)
        mid = seen_centre(ctx)
        under = ctx.js('window.__skep.posAt(%s, %s, %s)' % (json.dumps(DOC), mid['x'], mid['y']))
        before = line_from(ctx, under, mid)
        before['em'] = ctx.js('window.__skep.fold(%s).fs' % json.dumps(DOC)) * ctx.camera()['scale']
        left = ctx.camera()
        ctx.leap(FAR_LEAP)
    finally:
        ctx.resize(*was)
    ctx.settle()
    ctx.frames(3)
    # the view left, in the window put back: the line holding the position, from that view's visible centre, on screen
    stale = ctx.js('''((v) => { const S = window.__skep, p = S.view.viewport(), top = document.getElementById('line').getBoundingClientRect().bottom, at = S.centreOf(%s, %s);
      return (at.y - v.y) * v.scale + p.VH / 2 - (top + p.VH) / 2; })(%s)''' % (json.dumps(DOC), json.dumps(under), json.dumps(left)))
    line_px = ctx.js('window.__skep.fold(%s).fs' % json.dumps(DOC)) * left['scale'] * LINE_RATIO
    r.check(stale is not None and abs(stale - before['dy']) > line_px,
            f'the window put back from {NARROW_PX} px: the first edition folded again at the full measure, the line holding the passage left no longer where it stood from the visible centre of the view left',
            {'under': under, 'dy_before': before['dy'], 'dy_from_the_view_left': stale, 'line_px': line_px})
    ctx.drv.key('[', code='BracketLeft', mods=('Meta',))
    ctx.settle()
    ctx.frames(3)
    after = line_from(ctx, under, seen_centre(ctx))
    after['em'] = ctx.js('window.__skep.fold(%s).fs' % json.dumps(DOC)) * ctx.camera()['scale']
    entry = ctx.js('(() => { const t = window.__skep.trail(); return t.entries[t.cursor].addr; })()')
    r.check(entry == DOC and abs(after['dy'] - before['dy']) <= 1 and abs(after['em'] - before['em']) <= 1e-6,
            'Mod+[ lands on the passage left in the narrow window: the line holding it at the height it stood from the visible view\'s centre, 1 px either way, at its em (issue #221)',
            {'entry': entry, 'under': under, 'before': before, 'after': after})
    return {'window': NARROW_PX, 'pos': under, 'dy_from_the_view_left': stale, 'before': before, 'after': after}


def leap_onto_rendered(ctx, r):
    """THE LINES A LEAP LANDS ON (issue #296: "The flight lands on the line the passage is actually on"): the first edition
    set at the full measure, the view away at the far edition and the window set narrower — the first edition's lines set
    at no measure in force, its fold P-LAY's prediction — at the first of RENDERED_PX where that prediction places the line
    holding the window run's first position half a line or more from where the platform sets it; a LEAP there lands on
    its lines as rendered: the camera at the frame of that line in the fold the first edition stands mounted in, 1 px
    either way, its em the landing's; its figures"""
    pos = WINDOW[0]
    tried = []
    for px in RENDERED_PX:
        ctx.leap(DOC, pos)
        ctx.leap(FAR_LEAP)
        was = ctx.resize(px, 900)
        try:
            ctx.settle()
            ctx.frames(3)
            # the line's middle as the first edition's fold stands unmounted, read by the hook that sets no line
            predicted = ctx.js('window.__skep.centreOf(%s, %d)' % (json.dumps(DOC), pos))
            ctx.leap(DOC, pos)
            ctx.frames(3)
            cam, fit = ctx.camera(), ctx.js('window.__skep.measure()')
            at = ctx.js('window.__skep.frameOf(%s, %d)' % (json.dumps(DOC), pos))
            rendered = ctx.js('window.__skep.centreOf(%s, %d)' % (json.dumps(DOC), pos))
            mounted = ctx.js('window.__skep.mounted(%s)' % json.dumps(DOC))
        finally:
            ctx.resize(*was)
        ctx.settle()
        ctx.frames(3)
        line_px = fit['px'] * LINE_RATIO
        apart = math.hypot(rendered['x'] - predicted['x'], rendered['y'] - predicted['y']) * cam['scale']
        tried.append({'window': px, 'cpl': fit['cpl'], 'apart_px': apart, 'line_px': line_px})
        if apart >= line_px / 2:
            break
    r.check(apart >= line_px / 2,
            f'a window of {px} px, the view away: the first edition\'s fold, its lines set at no measure in force, places the line holding the window run\'s first position half a line or more from where the platform sets it',
            {'pos': pos, 'predicted': predicted, 'rendered': rendered, 'tried': tried})
    off = {'dx': (at['x'] - cam['x']) * cam['scale'], 'dy': (at['y'] - cam['y']) * cam['scale']}
    em = mounted['fs'] * cam['scale'] if mounted else None
    r.check(mounted is not None and abs(off['dx']) <= 1 and abs(off['dy']) <= 1 and abs(em - fit['px']) < 1e-6,
            f'a LEAP into the first edition there lands on its lines as rendered: the camera at the frame of the line holding that position in the fold it stands mounted in, 1 px either way, at the landing\'s em, {fit["px"]} px (issue #296)',
            {'pos': pos, 'camera': cam, 'frame': at, 'off_px': off, 'em': em, 'landing_px': fit['px']})
    return {'window': px, 'pos': pos, 'tried': tried, 'off_px': off, 'em': em}


# every frame from here on sampled until stopped: whether the camera flew in it, and the viewport's width the page held
NARROWED = '''(() => { const g = window.__gateNarrowed = {seen: [], stop: false};
  const tick = () => { if (g.stop) return; g.seen.push([window.__skep.view.flying(), window.__skep.view.viewport().VW]); requestAnimationFrame(tick); }; requestAnimationFrame(tick); })()'''
NARROWED_SEEN = '(() => { const g = window.__gateNarrowed; if (!g) return []; g.stop = true; return g.seen; })()'


def middle(xs):
    """the middle value of some figures, the upper of the two middle ones where they are even; None where there are none"""
    return sorted(xs)[len(xs) // 2] if xs else None


def leap_across_resize(ctx, r):
    """A FLIGHT ACROSS A RESIZE (FP-8, FP-25): the view away at the far edition at the full measure, a LEAP into the
    first edition at the window run's first position made, and the window set NARROW_PX wide while its camera flies —
    the first edition folded again at the measure the narrowed window holds — it lands on the line holding that
    position in that fold: the camera at that line's frame there, 1 px either way, at the landing's em; its figures,
    the intervals and draw times of the frames from the act to the landing among them, measured on this machine
    (FP-18)"""
    pos = WINDOW[0]
    ctx.leap(FAR_LEAP)
    ctx.js(NARROWED)
    t0 = ctx.js('performance.now()')
    ctx.js('void window.__skep.go.leapTo(%s, %d)' % (json.dumps(DOC), pos))
    was = ctx.resize(NARROW_PX, 900)
    try:
        ctx.settle()
        ctx.frames(3)
        seen = ctx.js(NARROWED_SEEN)
        cam, fit = ctx.camera(), ctx.js('window.__skep.measure()')
        at = ctx.js('window.__skep.frameOf(%s, %d)' % (json.dumps(DOC), pos))
        mounted = ctx.js('window.__skep.mounted(%s)' % json.dumps(DOC))
        flown = ctx.js('window.__skep.frames().filter((f) => f.t >= %s).map((f) => [f.interval, f.drawMs])' % t0)
    finally:
        ctx.js(NARROWED_SEEN)
        ctx.resize(*was)
    ctx.settle()
    ctx.frames(3)
    narrowed = sum(1 for flying, vw in seen if flying and vw == NARROW_PX)
    r.check(narrowed > 0, f'the window set {NARROW_PX} px wide while the LEAP\'s camera flew: frames that flew in the narrowed window',
            {'frames': len(seen), 'flew_narrowed': narrowed})
    off = {'dx': (at['x'] - cam['x']) * cam['scale'], 'dy': (at['y'] - cam['y']) * cam['scale']}
    em = mounted['fs'] * cam['scale'] if mounted else None
    r.check(mounted is not None and abs(off['dx']) <= 1 and abs(off['dy']) <= 1 and abs(em - fit['px']) < 1e-6,
            f'a LEAP whose window narrows to {NARROW_PX} px as it flies lands on the line in the fold the narrowed window sets the first edition in: the camera at that line\'s frame there, 1 px either way, at the landing\'s em, {fit["px"]} px (FP-8, FP-25)',
            {'pos': pos, 'camera': cam, 'frame': at, 'off_px': off, 'em': em, 'landing_px': fit['px']})
    intervals, draws = [f[0] for f in flown], [f[1] for f in flown]
    return {'window': NARROW_PX, 'pos': pos, 'flew_narrowed': narrowed, 'off_px': off, 'em': em, 'frames': len(flown),
            'interval_ms': {'middle': middle(intervals), 'max': max(intervals, default=None)},
            'draw_ms': {'middle': middle(draws), 'max': max(draws, default=None)}}


def step(ctx, em):
    """the camera over the first edition at an em, and what the frames that step drew show: the most documents any of
    them drew as bars under their own mounted text (`both`), and yielded to text that was not mounted (`neither`)"""
    t0 = ctx.js('performance.now()')
    ctx.view_doc_em(DOC, em)
    f = ctx.js('window.__skep.frames().filter(f => f.t >= %s).map(f => [f.both, f.neither])' % t0)
    return {'em': em, 'frames': len(f), 'both': max((x[0] for x in f), default=0), 'neither': max((x[1] for x in f), default=0)}


def run(ctx):
    r = Result()
    ctx.leap(DOC, WINDOW[0])
    drift = {}
    for em in LEVELS_EM:
        view_reading(ctx, em)
        sample = ctx.js('window.__skep.driftSample(%s)' % json.dumps('em%d' % em))
        mine = [s for s in sample if s['addr'] == DOC]
        r.check(len(mine) == 1, f'em {em}: the first edition is mounted', [s['addr'] for s in sample])
        worst = max((max(abs(s['dx']), abs(s['dy']), s.get('span_dx', 0), s.get('span_dy', 0)) for s in sample), default=None)
        r.check(worst is not None and worst <= DRIFT_TOL_PX, f'em {em}: registration drift {DRIFT_TOL_PX} px or less for every mounted article — its box against the projected origin, and every span\'s line against its laid-out place', sample)
        ov = ctx.js('window.__skep.overlapCheck()')
        r.check(ov['intersecting_pairs'] == 0, f'em {em}: containment — no two mounted articles intersect', ov['intersecting_pairs'])
        r.check(not ov['blocks_cut'], f'em {em}: containment — every row of every mounted article, its head, its blocks and the scene-offer, lies inside the column that holds it, its clip and its room; none is cut at a column\'s edge or the room\'s', {'blocks_cut': ov['blocks_cut'][:6], 'worst_overflow_px': ov['worst_overflow_px']})
        r.check(not ov['corners_missing'], f'em {em}: every mounted article at reading scale carries its corner beside it', ov['corners_missing'])
        r.check(not ov['corners_clipped'], f'em {em}: no corner is clipped by a box of the page — it stands beside its article, outside the box that clips the text', ov['corners_clipped'])
        r.check(not ov['corners_into'], f'em {em}: no corner reaches into another document\'s box, mounted or only drawn', ov['corners_into'][:6])
        c = corner_of(ctx)
        shown = c['corner'] is not None and c['corner']['inClip'] and c['corner']['inView'] and c['corner']['rect']['y'] >= c['line'] - 0.5
        r.check(shown, f'em {em}: the first edition\'s corner is in view, below the one line', c)
        ho = handoff(ctx)
        r.check(ho['compared'] > 0 and not ho['off'], f'em {em}: the handoff — every part of every block of every mounted article stands on the canvas\'s bars for it in its column: its top and its height within {HANDOFF_TOL_PX} px of its bars\', and as many lines', {'compared': ho['compared'], 'off': ho['off'][:6]})
        drift['em%d' % em] = {'samples': sample, 'worst_px': worst, 'containment': ov, 'em_px_measured': mine[0]['em_px'] if mine else None, 'corner': c['corner'] and c['corner']['rect'], 'handoff': {'compared': ho['compared'], 'off': len(ho['off']), 'gaps': ho['gaps']}}
        drift['em%d' % em]['measure'] = measure_holds(r, f'em {em}', measure_view(ctx))
    r.figures['drift'] = drift
    # the corner holds to the top of the document's visible part (foundations §3.1): its first column's top risen past
    # the one line, the corner stands just below the line; its outline's bottom risen near it, the corner rises with the
    # bottom (issue #15: the document's place is its columns)
    f = ctx.js('window.__skep.fold(%s)' % json.dumps(DOC))
    c0, vp = f['columns'][0], ctx.js('window.__skep.view.viewport()')
    s14 = ctx.js('window.__skep.scaleFor(%s, "em", 14)' % json.dumps(DOC))
    line = ctx.js("document.getElementById('line').getBoundingClientRect().bottom")
    ctx.set_view(c0['x'] + c0['w'] / 2, c0['y'] + (vp['VH'] / 2 - (line - 100)) / s14, s14)
    held = corner_of(ctx)
    r.check(held['top'] < held['line'] and held['corner'] is not None and held['corner']['inView'] and held['line'] <= held['corner']['rect']['y'] <= held['line'] + 16,
            'the first column\'s top above the one line: the corner holds just below the line, in view', held)
    # THE HELD LABEL (issue #169's design decision): the walk still in the first edition, where the run's landing stood it, the line
    # names it — no label held over its text; stepped out to its account, the line names the account — its label held there
    named = held_label(ctx)
    r.check(held['top'] < held['line'] and named['named']['doc'] == DOC and named['label'] is None,
            'landed in the first edition, the walk in it, its first column\'s top risen past the one line: the line names it, and no label is held over its text — the line is its running head', {'named': named['named'], 'label': named['label']})
    ctx.js('window.__skep.walk.key("out")')
    ctx.js('window.__skep.walk.key("out")')
    ctx.settle()
    ctx.set_view(c0['x'] + c0['w'] / 2, c0['y'] + (vp['VH'] / 2 - (line - 100)) / s14, s14)
    hl = held_label(ctx)
    q, cq = (hl['label'] or {}).get('rect'), hl['corner']
    words = (hl['label'] and hl['label']['text']) or []
    rest = words[:-1]
    r.check(hl['named']['doc'] is None and hl['named']['account'] == account_of(DOC) and bool(q) and words[-1:] == [DOC[len(account_of(DOC)):]]
            and all(BADGE.match(x) for x in (rest[1:] if rest and word_cut(rest[0], hl['lead']) else rest))
            and abs(q['y'] - (hl['line'] + HOLD_GAP_PX)) <= 1 and abs(q['x'] - hl['left']) <= 1 and in_shape(q, hl['rects']),
            f'the walk stepped out to the first edition\'s account, which the line names: its label held over its text, {HOLD_GAP_PX} px below the line, from its first column\'s text left, inside its outline — its first line, where set, cut on a word, its badge, then its address past its region\'s prefix at the line\'s end',
            {'named': hl['named'], 'label': hl['label'], 'lead': hl['lead'], 'line': hl['line'], 'left': hl['left'], 'outline': hl['rects']})
    r.check(bool(q and cq) and abs(q['y'] - cq['y']) <= 1 and not meets(q, cq),
            'the held label and the corner stand level below the line, and never overlap (issue #169: "The corner keeps its side, outside the text, level with the label")', {'label': q, 'corner': cq})
    r.check(bool(q) and hl['hidden'] == 'true' and hl['cornerLike'] is False and hl['takes'] and hl['label']['legible'],
            'the held label is drawn and never announced — hidden from assistive technology, no corner to the page\'s readers — and at the reading size a press on it meets it, never the text it covers',
            {'aria_hidden': hl['hidden'], 'corner_like': hl['cornerLike'], 'takes_press': hl['takes'], 'legible': hl['label'] and hl['label']['legible']})
    rise = held['line'] + HOLD_GAP_PX + (held['corner']['rect']['h'] if held['corner'] else 0) - 20
    ctx.set_view(c0['x'] + c0['w'] / 2, f['outline']['y'] + f['outline']['h'] + (vp['VH'] / 2 - rise) / s14, s14)
    rising = corner_of(ctx)
    rc = rising['corner']
    r.check(rc is not None and abs(rising['bottom'] - rise) <= 1 and abs(rc['rect']['y'] + rc['rect']['h'] - rising['bottom']) <= 1,
            f'the outline\'s bottom risen to {round(rise)} px, less than the corner\'s height below where it holds: the corner rises with it, its bottom at the outline\'s, never past it', rising)
    # the outline's foot risen within the held label's line box of the hold: the label pushed up under the line too, its bottom on the foot
    # inside the half gutter
    foot = hl['line'] + hl['gutter'] + 0.75 * (q['h'] if q else 0)
    ctx.set_view(c0['x'] + c0['w'] / 2, f['outline']['y'] + f['outline']['h'] + (vp['VH'] / 2 - foot) / s14, s14)
    pushed = held_label(ctx)
    pq = (pushed['label'] or {}).get('rect')
    r.check(bool(pq) and abs(pq['y'] + pq['h'] - (pushed['bottom'] - pushed['gutter'])) <= 1 and pq['y'] < pushed['line'] < pq['y'] + pq['h'] and not (pushed['corner'] and meets(pq, pushed['corner'])),
            'the outline\'s foot risen near the line: the held label rises with it, its bottom on the foot inside the half gutter, pushed up under the line and still in view, clear of the corner',
            {'label': pq, 'bottom': pushed['bottom'], 'gutter': pushed['gutter'], 'line': pushed['line'], 'corner': pushed['corner']})
    r.figures['corner_held'] = {'held': held['corner'] and held['corner']['rect'], 'line': held['line'], 'rising': rc and rc['rect'], 'box_bottom': rising['bottom'],
                                'held_label': q, 'held_label_pushed': pq}
    ctx.leap(DOC, WINDOW[0])
    # the corner follows the column nearest the view's centre, and the measure narrows to what a narrow view holds (issue #151)
    r.figures['corner_follows'] = corner_follows(ctx, r)
    r.figures['measure_narrows'] = measure_narrows(ctx, r)
    # a resize that narrows the measure frames the view across the column being read, the corner in view (issue #436)
    r.figures['resize_frames'] = resize_frames(ctx, r)
    # no selection an act makes is left under a head's held row (issue #436)
    r.figures['head_guards'] = head_guards(ctx, r)
    # a focus landing in a corner the view does not show brings it in (issue #436)
    r.figures['corner_tabbed'] = corner_tabbed(ctx, r)
    # Back after the window was put back from a narrow one lands on the passage left there (issue #221)
    r.figures['back_after_resize'] = back_after_resize(ctx, r)
    # a LEAP into a document whose lines are set at no measure in force lands on its lines as rendered (issue #296)
    r.figures['leap_onto_rendered'] = leap_onto_rendered(ctx, r)
    # a LEAP whose window narrows while its camera flies lands on its passage in the fold the narrowed window sets
    r.figures['leap_across_resize'] = leap_across_resize(ctx, r)
    # a continuous zoom: drift sampled across a sweep, about the first column
    first = ctx.js('window.__skep.centreOf(%s, null)' % json.dumps(DOC))
    s_lo = ctx.js('window.__skep.scaleFor(%s, "em", 7)' % json.dumps(DOC))
    s_hi = ctx.js('window.__skep.scaleFor(%s, "em", 28)' % json.dumps(DOC))
    sweep = ctx.js('''(async () => {
      const out = []; const S = window.__skep; const x = %s, y = %s;
      for (let i = 0; i <= 40; i++) { const u = i / 40; const scale = Math.exp(Math.log(%s) + (Math.log(%s) - Math.log(%s)) * u); S.view.set({x, y, scale}); await new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r))); for (const s of S.driftSample('sweep')) out.push({scale: s.scale, dx: s.dx, dy: s.dy, span_dx: s.span_dx, span_dy: s.span_dy, em: s.em_px}); }
      return out; })()''' % (first['x'], first['y'], s_lo, s_hi, s_lo))
    worst_sweep = max((max(abs(s['dx']), abs(s['dy']), s.get('span_dx', 0), s.get('span_dy', 0)) for s in sweep), default=0)
    r.check(worst_sweep <= DRIFT_TOL_PX, 'continuous zoom: drift within tolerance across the sweep', {'samples': len(sweep), 'worst_px': worst_sweep})
    r.figures['sweep'] = {'samples': len(sweep), 'worst_px': worst_sweep}
    # the symbols: stage 2 at the first edition, each at its span — after the last word its marked words touch, in the
    # paragraph holding them, and never past a word after them
    ctx.view_doc_em(DOC, 12.5)
    hidden_face = ctx.js('window.__skep.mounted(%s).fs' % json.dumps(DOC))
    ctx.js('window.__skep.links.reveal(%s, 2)' % json.dumps(DOC))
    ctx.settle()
    ctx.frames(3)
    drawn = [s for s in (symbols_view(ctx) or []) if s['words']]
    misplaced = [s for s in drawn if s['syms'] != 1 or not s.get('same_block') or not s.get('after_words') or re.search(r'\s', s.get('between') or '')]
    followed = [s for s in drawn if s not in misplaced and (s.get('after') or '').strip()]
    r.check(bool(drawn) and not misplaced, 'stage 2: each link of the first edition drawn at one span has one symbol, in the paragraph holding the end of its marked words, with nothing but the rest of their last word between them and it',
            [{k: s.get(k) for k in ('link', 'pos', 'width', 'syms', 'same_block', 'after_words', 'between')} for s in misplaced[:6]])
    r.check(bool(followed), 'stage 2: among them, symbols with another word of their paragraph after them — a symbol at the paragraph\'s end would stand past it', {'drawn': len(drawn), 'followed': len(followed)})
    r.figures['symbols'] = {'drawn': len(drawn), 'misplaced': len(misplaced), 'followed_by_a_word': len(followed)}
    # THE TAILS (issue #132's design decision): stage 3 at the first edition, whose every citation reaches a ghost the plane draws
    # nowhere — each draws no beam, and leaves the text by a tail at its passage's line, at the edge of the part of its block holding it
    ctx.js('window.__skep.links.reveal(%s, 3)' % json.dumps(DOC))
    ctx.settle()
    ctx.frames(3)
    r.figures['tails'] = tails_hold(ctx, r)
    # THE SIZE under the reveal: others' links on too, and the model moved by a read (the ghost's, refused) so the fold is
    # read from the model as it stands — the article holds in its columns and its room, at the size it was mounted at hidden
    ctx.js('window.__skep.links.setOthers(%s, true)' % json.dumps(DOC))
    ctx.js('window.__skep.model.loadWhole(%s)' % json.dumps(GHOST))
    ctx.settle()
    ctx.frames(3)
    ov = ctx.js('window.__skep.overlapCheck()')
    revealed = ctx.js('window.__skep.mounted(%s)' % json.dumps(DOC))
    r.check(not ov['blocks_cut'], 'em 12.5, the reveal at stage 3 with others\' links on: containment — every row of every mounted article, its head, its blocks and the scene-offer, lies inside the column that holds it, its clip and its room', {'blocks_cut': ov['blocks_cut'][:6], 'worst_overflow_px': ov['worst_overflow_px']})
    r.check(revealed is not None and revealed['fs'] == hidden_face, 'em 12.5: the reveal at stage 3 with others\' links on leaves the first edition at the size it was mounted at hidden, the model moved between them — no reveal sets it at another size',
            {'hidden': hidden_face, 'revealed': revealed and revealed['fs']})
    r.figures['size_under_reveal'] = {'hidden': hidden_face, 'revealed': revealed and revealed['fs'], 'worst_overflow_px': ov['worst_overflow_px']}
    ctx.js('window.__skep.links.setOthers(%s, false)' % json.dumps(DOC))
    ctx.js('window.__skep.links.hide(%s)' % json.dumps(DOC))
    ctx.frames(2)
    r.check(ctx.js('window.__skep.beams()') == 0, 'hidden again: no beams')
    # THE BEAMS, where citations reach documents the plane draws: at BEAMED, a citer of FAR_LEAP
    r.figures['beams'] = beams_hold(ctx, r)
    # the arrival: a landing as a follow lands — the door naming its span and its link — on a drawn link's span half its
    # paragraph or narrower outlines that span's own lines, never the paragraph's box
    shown = ctx.js('window.__skep.links.shown(%s)' % json.dumps(DOC))
    paras = [b for b in ctx.js('window.__skep.model.doc(%s).blocks' % json.dumps(DOC)) if b['kind'] == 'para']
    once = [s for s in shown if sum(1 for x in shown if x['link'] == s['link']) == 1]
    target = next((s for s in once for b in paras if b['pos'] <= s['pos'] and s['pos'] + s['width'] <= b['pos'] + b['width'] and 2 * s['width'] <= b['width']), None)
    r.check(target is not None, 'the arrival: a drawn link of the first edition at one span, half its paragraph or narrower', [[s['pos'], s['width']] for s in once[:8]])
    if target is not None:
        ctx.js('window.__skep.go.leapTo(%s, %d, %s)' % (json.dumps(DOC), target['pos'], json.dumps({'runs': [{'pos': target['pos'], 'width': target['width']}], 'link': target['link']})))
        ctx.settle()
        ctx.frames(3)
        a = ctx.js('window.__skep.arrivalAnchors()') or {}
        outline, words, block = a.get('outline') or [], a.get('words') or [], a.get('block')
        r.check(bool(outline) and bool(words) and all(any(rect_like(o, w) for w in words) for o in outline) and all(any(rect_like(w, o) for o in outline) for w in words),
                f'the arrival: the outline stands on its span\'s own lines — each rect it outlines one of the line rects of the link\'s marked words, and each of those outlined, {ANCHOR_TOL_PX} px either way',
                {'link': target['link'], 'pos': target['pos'], 'width': target['width'], 'outline': outline[:6], 'words': words[:6]})
        r.check(block is not None and not any(rect_like(o, block) for o in outline), 'the arrival: no rect it outlines is the paragraph\'s box', {'block': block, 'outline': outline[:6]})
        r.figures['arrival'] = {'link': target['link'], 'pos': target['pos'], 'width': target['width'], 'outlined_lines': len(outline), 'word_lines': len(words)}
        # a far end the far document's text holds in two runs apart — a passage a later edit cut in two — outlined in both:
        # the door naming the drawn link's span cut in three, its first and last thirds the runs, the outline stands on each
        # run's own lines — read from the article's own text — and on nothing between them
        third = target['width'] // 3
        runs = [{'pos': target['pos'], 'width': third}, {'pos': target['pos'] + target['width'] - third, 'width': third}]
        lines, outlined = [], []
        if third >= 1:
            ctx.js('window.__skep.go.leapTo(%s, %d, %s)' % (json.dumps(DOC), target['pos'], json.dumps({'runs': runs, 'link': target['link']})))
            ctx.settle()
            ctx.frames(3)
            outlined = (ctx.js('window.__skep.arrivalAnchors()') or {}).get('outline') or []
            lines = [[q for q in ctx.js('window.__skep.spanRects(%s, %d, %d)' % (json.dumps(DOC), x['pos'], x['width'])) or [] if q['w'] > 0 and q['h'] > 0] for x in runs]
        each = [q for ls in lines for q in ls]
        r.check(third >= 1 and all(lines) and len(outlined) == len(each) and all(any(rect_like(o, q) for q in each) for o in outlined) and all(any(rect_like(q, o) for o in outlined) for q in each),
                f'the arrival in two runs: the outline stands on each run\'s own lines and on nothing between them — each rect it outlines one of the runs\' line rects, and each of those outlined, {ANCHOR_TOL_PX} px either way',
                {'link': target['link'], 'runs': runs, 'outline': outlined[:6], 'lines': [ls[:4] for ls in lines]})
        r.figures['arrival']['runs'] = {'runs': runs, 'outlined_lines': len(outlined), 'run_lines': [len(ls) for ls in lines]}
        # gone at the next act (foundations §3.2: "both gone at the next act — a pan or a zoom none"): HOME made from the
        # landing, then the camera set back on the landing's view — a camera move, no act — with the article mounted there again
        landing = ctx.camera()
        ctx.js('window.__skep.go.home()')
        ctx.settle()
        ctx.set_view(landing['x'], landing['y'], landing['scale'])
        again = ctx.js('window.__skep.arrivalAnchors()')
        mounted = DOC in ctx.js('window.__skep.mountedAddrs()')
        r.check(mounted and again is None, 'the arrival: gone at the next landing — HOME made from the landing, the camera set back on the landing\'s view finds the article mounted and nothing outlined in it',
                {'mounted': mounted, 'arrival': again and {k: again[k] for k in ('addr', 'pos', 'runs', 'link')}, 'outline': again and again['outline'][:4]})
        # the link followed drawn heavier (foundations §2.1's register: "the arrival an outline around its span with the
        # followed link drawn heavier"): at BEAMED, whose citations draw beams — the first edition's every citation a tail — the
        # reveal at stage 3, the landing that names a beamed link lays more ink about its beam's start than a landing on the same
        # span that names none. The link named: a beamed link whose span lies within one paragraph, so its symbol — set after
        # its span's last word — stands with its words at the landing
        beamed = [x for x in ctx.js('window.__skep.links.shown(%s)' % json.dumps(BEAMED)) if ctx.js('window.__skep.links.tailed(%s, %s)' % (json.dumps(BEAMED), json.dumps(x['link']))) is False]
        beamed_paras = [b for b in ctx.js('window.__skep.model.doc(%s).blocks' % json.dumps(BEAMED)) if b['kind'] == 'para']
        heavy = next((x for x in beamed if any(b['pos'] <= x['pos'] and x['pos'] + x['width'] <= b['pos'] + b['width'] for b in beamed_paras)), None)
        ink = {True: None, False: None}
        # and its symbol in the article, marked heavier in place while the arrival stands (FP-30; issue #202): the one the
        # landing names, and none where it names none
        sym = {True: None, False: None}
        sym_at = '#domlayer article.dtext[data-addr="%s"] .sym[data-link="%s"]' % (BEAMED, heavy['link']) if heavy else ''
        if heavy is not None:
            ctx.js('window.__skep.links.reveal(%s, 3)' % json.dumps(BEAMED))
            for named in (True, False):
                ctx.js('window.__skep.go.leapTo(%s, %d, %s)' % (json.dumps(BEAMED), heavy['pos'], json.dumps({'runs': [{'pos': heavy['pos'], 'width': heavy['width']}], 'link': heavy['link'] if named else None})))
                ctx.settle()
                ctx.frames(3)
                ink[named] = beam_ink(ctx, BEAMED, heavy['link'], heavy['pos'])
                sym[named] = ctx.js('(() => { const e = document.querySelector(%s); return e ? e.classList.contains("heavier") : null; })()' % json.dumps(sym_at))
            ctx.js('window.__skep.links.hide(%s)' % json.dumps(BEAMED))
        lit, unlit = ink[True], ink[False]
        r.check(bool(lit) and bool(unlit) and unlit['ink'] > 0 and lit['ink'] >= HEAVIER_INK * unlit['ink'],
                f'the arrival: the link followed drawn heavier — at {BEAMED}, the reveal at stage 3, the landing that names a link drawn as a beam lays {HEAVIER_INK:g} times the ink or more within {BEAM_WINDOW_PX} px of its beam\'s start that a landing on the same span naming none lays',
                {'link': heavy and heavy['link'], 'lit': lit, 'unlit': unlit})
        r.check(sym[True] is True and sym[False] is False,
                f'the arrival: the link followed lights its symbol too — at {BEAMED}, the landing that names it marks the link\'s symbol in the mounted article heavier, and a landing on the same span naming none leaves it unlit (FP-30; issue #202)',
                {'link': heavy and heavy['link'], 'named': sym[True], 'naming_none': sym[False]})
        r.figures['arrival'].update(gone_at_next_act=again is None, beam_ink={'doc': BEAMED, 'link': heavy and heavy['link'], 'lit': lit and round(lit['ink'], 2), 'unlit': unlit and round(unlit['ink'], 2)}, symbol_lit={'named': sym[True], 'naming_none': sym[False]})
        ctx.leap(DOC, WINDOW[0])
    # the mount thresholds: mounted at em 6.5 and above, unmounted below 5.5; at each step the frames it drew drew no
    # document both as bars and as text, nor left one yielded and unmounted; where the article stands just mounted, it
    # stands on its bars
    steps = []
    def crossed(em, how):
        s = step(ctx, em)
        steps.append(dict(s, how=how))
        r.check(s['frames'] > 0 and s['both'] == 0 and s['neither'] == 0, f'em {em} ({how}): no frame of the step drew a document\'s bars under its own mounted text, or left a document yielded to text that is not mounted', s)
    crossed(7, 'from above')
    r.check(DOC in ctx.js('window.__skep.mountedAddrs()'), 'em 7: the article is mounted (above the 6.5 threshold)')
    crossed(6, 'from above')
    r.check(DOC in ctx.js('window.__skep.mountedAddrs()'), 'em 6 from above: still mounted (hysteresis)')
    ho = handoff(ctx)
    r.check(ho['compared'] > 0 and not ho['off'], 'em 6 from above: the handoff — every part of every block of every mounted article stands on its bars in its column', {'compared': ho['compared'], 'off': ho['off'][:6]})
    crossed(5, 'from above')
    r.check(DOC not in ctx.js('window.__skep.mountedAddrs()'), 'em 5: the article is unmounted (below the 5.5 hysteresis)')
    crossed(6, 'from below')
    r.check(DOC not in ctx.js('window.__skep.mountedAddrs()'), 'em 6 from below: not yet mounted (hysteresis)')
    crossed(6.6, 'from below')
    r.check(DOC in ctx.js('window.__skep.mountedAddrs()'), 'em 6.6 from below: mounted (above the 6.5 threshold)')
    ho = handoff(ctx)
    r.check(ho['compared'] > 0 and not ho['off'], 'em 6.6 from below: the handoff — every part of every block of every mounted article stands on its bars in its column', {'compared': ho['compared'], 'off': ho['off'][:6]})
    crossed(12.5, 'from below')
    r.check(DOC in ctx.js('window.__skep.mountedAddrs()'), 'em 12.5: mounted')
    r.figures['mount_steps'] = steps
    r.figures['handoff_stand_in'] = stand_in_holds(ctx, r)
    cap = ctx.js('window.__skep.constants')
    r.figures['constants'] = cap
    # the projection's places: no two indexed documents of the account share a box (reading order seeded by the prefix — M2's site)
    boxes = ctx.js('window.__skep.model.places().filter(p => !p.system).slice(0, 120).map(p => [p.doc, window.__skep.boxOf(p.doc)])')
    pairs = 0
    for i in range(len(boxes)):
        for j in range(i + 1, len(boxes)):
            a, b = boxes[i][1], boxes[j][1]
            if a.get('residue') or b.get('residue'):
                continue
            if a['x'] < b['x'] + b['w'] and b['x'] < a['x'] + a['w'] and a['y'] < b['y'] + b['h'] and b['y'] < a['y'] + a['h']:
                pairs += 1
    r.check(pairs == 0, 'no two indexed documents share a box (the first 120 places; the residue cell apart)', pairs)
    cell = ctx.js('window.__skep.accountCell("1.0.1")')
    outside = [d for d, b in boxes if d.startswith('1.0.1.0.') and not (b['x'] >= cell['x'] - 1e-6 and b['y'] >= cell['y'] - 1e-6 and b['x'] + b['w'] <= cell['x'] + cell['w'] + 1e-6 and b['y'] + b['h'] <= cell['y'] + cell['h'] + 1e-6)]
    r.check(not outside, 'every document box lies inside its account\'s cell', outside[:5])
    r.figures['boxes_checked'] = len(boxes)
    # reading order (foundations §2.1): the first seven documents of an account share the first row, the eighth starts the next; document 1 is in the first column
    row = [ctx.js('window.__skep.boxOf(%s)' % json.dumps('1.0.1.0.%d' % k)) for k in range(1, 9)]
    eps = 1e-6
    r.check(all(abs(row[k]['y'] - row[0]['y']) < eps for k in range(1, 7)), 'documents 1–7 lie along the first row of their account\'s grid', [round(b['y']) for b in row[:7]])
    r.check(all(row[k]['x'] > row[k - 1]['x'] for k in range(1, 7)), 'documents 1–7 advance along the row', [round(b['x']) for b in row[:7]])
    r.check(abs(row[7]['x'] - row[0]['x']) < eps and row[7]['y'] > row[0]['y'], 'document 8 starts the second row under document 1', {'d1': (round(row[0]['x']), round(row[0]['y'])), 'd8': (round(row[7]['x']), round(row[7]['y']))})
    r.check(row[0]['x'] < cell['x'] + cell['w'] / 7 and row[0]['y'] < cell['y'] + cell['h'] / 7, 'document 1 lies in the first cell of the grid', {'d1': (round(row[0]['x']), round(row[0]['y'])), 'cell': (round(cell['x']), round(cell['y']))})
    # THE LABELS: at each of S3's thresholds over the first edition, then with its box risen under the one line, then at HOME and at WHOLE BOARD
    box = ctx.js('window.__skep.boxOf(%s)' % json.dumps(DOC))
    first = ctx.js('window.__skep.centreOf(%s, null)' % json.dumps(DOC))
    seen = {}
    for name, value, kind in ctx.js('window.__skep.thresholds'):
        # an em threshold over the first edition's first column, where its text stands; a box threshold over its room
        at = first if kind == 'em' else {'x': box['x'] + box['w'] / 2, 'y': box['y'] + box['h'] / 2}
        ctx.set_view(at['x'], at['y'], ctx.js('window.__skep.scaleFor(%s, %s, %s)' % (json.dumps(DOC), json.dumps(kind), value)))
        seen[name] = labels_hold(r, name, label_view(ctx))
    # a box risen under the one line (issue #169's design decision: "Held below the line"): S3's mid-extents, where the line names the
    # account under the camera and never the first edition, its box's top UNDER_LINE_PX above the line's bottom; then its outline's
    # foot risen to within its label's line box of the hold, then past the line
    vp = ctx.js('window.__skep.view.viewport()')
    s90 = ctx.js('window.__skep.scaleFor(%s, "doc", 90)' % json.dumps(DOC))
    f90 = ctx.js('window.__skep.fold(%s)' % json.dumps(DOC))
    short = DOC[len(account_of(DOC)):]
    lh = None
    def risen(name, y_at):
        """the camera at mid-extents with the first edition's outline's top at `y_at` on screen; the label view, and the first
        edition's label set there, with its outline on screen and the half gutter"""
        ctx.set_view(box['x'] + box['w'] / 2, f90['outline']['y'] + (vp['VH'] / 2 - y_at) / s90, s90)
        v = label_view(ctx)
        seen[name] = labels_hold(r, name, v)
        cam = ctx.camera()
        sy = lambda y: (y - cam['y']) * cam['scale'] + vp['VH'] / 2
        o = {'top': sy(f90['outline']['y']), 'bottom': sy(f90['outline']['y'] + f90['outline']['h']), 'left': (f90['outline']['x'] - cam['x']) * cam['scale'] + vp['VW'] / 2}
        mine = next((l for l in v['labels'] if l['kind'] == 'doc' and l['place'] == DOC), None)
        seen[name].update(outline_top=round(o['top'], 2), outline_bottom=round(o['bottom'], 2), line=v['seen']['y'], held=mine and [[x['text'], x['rect']] for x in mine['lines']])
        return v, o, mine, GUTTER_EM / 2 * f90['fs'] * cam['scale']
    for under in UNDER_LINE_PX:
        name = 'under-the-line-%d' % under
        top = ctx.js("document.getElementById('line').getBoundingClientRect().bottom")
        v, o, mine, g = risen(name, top - under)
        line = v['seen']['y']
        below = sorted(l['place'] for l in v['labels'] if l['kind'] == 'doc' and l['place'] != DOC and all(x['rect']['y'] >= line - LABEL_TOL_PX for x in l['lines']))
        a = address_line(mine) if mine else None
        q = a['rect'] if a else None
        first = mine['lines'][0] if mine and mine['lines'][0] is not a else None
        at_hold = bool(q) and abs(q['y'] - (line + HOLD_GAP_PX)) <= LABEL_TOL_PX
        on_foot = bool(q) and abs(q['y'] + q['h'] - (o['bottom'] - g)) <= LABEL_TOL_PX
        lead = v['leads'].get(DOC, {}).get('words') or ''
        r.check(abs(line - o['top'] - under) <= LABEL_TOL_PX and v['named']['doc'] is None and bool(mine) and mine.get('held') and bool(a) and a['text'] == short and mine.get('plate') is not None
                and abs(q['x'] + q['w'] - (mine['within']['x'] + mine['within']['w'])) <= LABEL_TOL_PX and abs(mine['within']['x'] - (o['left'] + g)) <= LABEL_TOL_PX
                and (first is None or (abs(first['rect']['x'] - (o['left'] + g)) <= LABEL_TOL_PX and word_cut(first['text'], lead)))
                and q['y'] <= line + HOLD_GAP_PX + LABEL_TOL_PX and q['y'] + q['h'] <= o['bottom'] - g + LABEL_TOL_PX and (at_hold or on_foot) and bool(below),
                f'{name}: the first edition\'s box\'s top {under} px above the one line\'s bottom, the line naming its account and not it: its label held below the line — one line from its first column\'s text left, on its ground, its first line, where set, at that left cut on a word and its address at the line\'s end, its top {HOLD_GAP_PX} px below the line or its bottom on its outline\'s foot inside the half gutter — and the labels of the documents below the line set',
                {'line': line, 'outline': o, 'gutter': g, 'named': v['named'], 'held': mine and {'lines': [[x['text'], x['rect']] for x in mine['lines']], 'plate': mine.get('plate'), 'held': mine.get('held'), 'within': mine.get('within')},
                 'left_out': [[x['text'], x['reason']] for x in v['out'] if x['kind'] == 'doc' and x['place'] == DOC], 'set_below': below[:8]})
        if q:
            lh = q['h']
    # the outline's foot risen to within the label's line box of the hold — the label floor's where no label was held — the label pushed up
    # under the line, its bottom on the foot; then risen wholly under the line
    lh = lh or MIN_LABEL_PX * 1.2
    top = ctx.js("document.getElementById('line').getBoundingClientRect().bottom")
    h90 = f90['outline']['h'] * s90
    v, o, mine, g = risen('under-the-line-foot', top + g + 0.75 * lh - h90)
    q = (address_line(mine) or mine['lines'][0])['rect'] if mine else None
    r.check(bool(q) and mine.get('held') and abs(q['y'] + q['h'] - (o['bottom'] - g)) <= LABEL_TOL_PX and q['y'] < v['seen']['y'] and q['y'] + q['h'] > v['seen']['y'],
            'under-the-line-foot: the first edition\'s outline\'s foot risen near the one line pushes its held label up under the line, its bottom on the foot inside the half gutter, still in view',
            {'line': v['seen']['y'], 'outline': o, 'gutter': g, 'held': mine and [[x['text'], x['rect']] for x in mine['lines']]})
    v, o, mine, g = risen('under-the-line-gone', top - 2 - h90)
    why = [x['reason'] for x in v['out'] if x['kind'] == 'doc' and x['place'] == DOC]
    r.check(mine is None and why[:1] == ['view'], 'under-the-line-gone: the first edition\'s outline risen wholly under the one line: no label, left out past the visible view',
            {'line': v['seen']['y'], 'outline': o, 'set': mine and [[x['text'], x['rect']] for x in mine['lines']], 'left_out': why})
    for name, door in (('home', 'home'), ('whole-board', 'wholeBoard')):
        ctx.js('window.__skep.go.%s()' % door)
        ctx.settle()
        ctx.frames(2)
        seen[name] = labels_hold(r, name, label_view(ctx))
    r.figures['labels'] = seen
    r.figures['contents_handoff'] = lead_handoff(ctx, r)
    r.figures['address_dots'] = address_dots(ctx, r)
    # THE TYPE, THE READING SCENE, THE CARRY, THE VERSION MOVE, THE CHROME, THE TRAIL
    r.figures['type'] = type_holds(ctx, r)
    r.figures['scene'] = scene_holds(ctx, r)
    r.figures['scene_kept'] = scene_kept_holds(ctx, r)
    r.figures['carried'] = carried_holds(ctx, r)
    r.figures['pieces'] = pieces_hold(ctx, r)
    r.figures['versions'] = version_holds(ctx, r)
    r.figures['chrome'] = chrome_holds(ctx, r)
    r.figures['line_label'] = line_label_holds(ctx, r)
    r.figures['trail'] = trail_holds(ctx, r)
    r.figures['stub'] = stub_holds(ctx, r)
    r.figures['hold'] = hold_holds(ctx, r)
    r.figures['bare'] = bare_holds(ctx, r)
    r.figures['named'] = named_holds(ctx, r)
    r.figures['kept'] = kept_holds(ctx, r)
    r.figures['kept_label'] = kept_label_holds(ctx, r)
    r.figures['longest'] = longest_holds(ctx, r)
    r.figures['walk'] = walk_holds(ctx, r)
    r.figures['line_rows'] = line_rows_hold(ctx, r)
    r.figures['panels'] = panels_hold(ctx, r)
    r.figures['overlay_room'] = overlay_room_holds(ctx, r)
    r.figures['leap_room'] = leap_room_holds(ctx, r)
    r.figures['scene_strokes'] = scene_strokes_hold(ctx, r)
    r.figures['scene_return'] = scene_return_holds(ctx, r)
    r.figures['scene_pane_return'] = scene_pane_return_holds(ctx, r)
    ctx.leap(DOC, WINDOW[0])
    return r.out()
